import type { MvBook } from '../molytvoslov';
const D: MvBook[] = [{"u":"Акафіст святителю Афанасію, єпископу Ковровському","e":"Akathist to St Athanasius, Bishop of Kovrov","secs":[{"h":"Кондак 1","ps":["Возбранниче сві́тлий на тьму ві́ка сего́, во вся ору́жія Бо́жия облече́нний і ві́ру Христо́ву, а́ки щит, проти́ву су́єтних мудрова́ній держа́вий, восхваля́єм тя любо́вію, святи́телю і іспові́дниче Афана́сіє, ти же я́ко моли́твенник о нас ко Го́споду дерзнове́нний, утвержде́нія в і́стині Правосла́вія іспроси́ нам, зовущим:","Ра́дуйся, Афана́сіє, но́вий іспові́дниче і Правосла́вія учи́телю."]},{"h":"Ікос 1","ps":["А́нгельськаго ча́я о́браза, Афана́сіє блаже́нне, ізмла́да ігранієм детським не внима́л єси́ ра́зумом, моли́твам же те́плим во хра́мі Госпо́дні і рукоді́лію в до́мі ма́тернем, а́ки би в ке́ллії, всегда́ приліжа́, дерзнове́нно предвозвещал єси́ отроко́м, сверстним тебі́, я́ко і́маши би́ти Це́ркве Христо́ви служи́тель свяще́нний. Ві́дуще у́бо ми, я́ко Про́мислом Бо́жиїм сбися рече́ніє твоє́, со удивле́нієм зове́м ті:","Ра́дуйся, дре́внею і свято́ю земле́ю Влади́мирською в добронравії воспита́нний;","ра́дуйся, в Ла́врі преподо́бнаго Се́ргия ли́ку інокующих вчиненний.","Ра́дуйся, посто́м і моли́твою житіє́ богоуго́дноє стяжа́вий;","ра́дуйся, от Го́спода к по́двигу свиді́тельства во дні лука́вия ізбра́нний.","Ра́дуйся, благолі́пія церко́внаго блюсти́телю;","ра́дуйся, прему́дрим Правосла́вія наста́вником подо́бниче.","Ра́дуйся, Афана́сіє, но́вий іспові́дниче і Правосла́вія учи́телю."]},{"h":"Кондак 2","ps":["Ви́дів, я́ко лю́тоє на Це́рков Россі́йськую гоне́ніє наста́, не то́чію гнів Бо́жий, пра́ведно дви́жимий на ни, помишля́л єси́ о́ноє, Афана́сіє богоразумне, но па́че прему́друю жа́тву душа́м, я́же созрі́ша в живо́т ві́чний, і сего́ ра́ди Го́споду жа́тви Христу́ воспіва́л єси́: Аллилу́я."]},{"h":"Ікос 2","ps":["Разумі́я Собо́р всіх святи́х землі́ Ру́ськия, Оте́честву на́шему от бід ізбавле́ніє би́ти, словеса́ тім пра́здничная нача́ слагати, богодухнове́нне, пі́сньми ди́вними Це́рков украша́я. Ми же, грі́шнії, ни́ні тя зря́ще в ли́ці при́сно тобо́ю что́мих уго́дников Бо́жиїх, воспису́єм ті похва́льная сія́:","Ра́дуйся, моле́ній умиле́нних слагателю;","ра́дуйся, пі́нія Го́сподеві разу́мнаго рачи́телю.","Ра́дуйся, чудотво́рцев Россі́йських чи́сті возлюби́вий;","ра́дуйся, предста́телей страни́ на́шея в по́мощ всегда́ призива́вий.","Ра́дуйся, я́ко страстоте́рпці но́вия увінча́л єси́ на землі́ похвала́ми;","ра́дуйся, я́ко в со́нмі тіх на Небесі́ Бо́га сла́виши.","Ра́дуйся, Афана́сіє, но́вий іспові́дниче і Правосла́вія учи́телю."]},{"h":"Кондак 3","ps":["Си́лу мня́ще безбожници на правові́ріє прия́ти, честни́я мо́щі святи́х землі́ Влади́мирськия посреді́ Успе́нськаго хра́ма собо́рнаго непокровенни поста́виша, во є́же посмеятися їм, ти же, до́блій ратниче Христо́в, наро́ду во храм притекшу, воззва́л єси́ велегла́сно: Благослове́н Бог наш! І та́ко злоумисляємоє святи́ням поруга́ніє в моле́бноє прославле́ніє претвори́л єси́, с ві́рними вку́пі вопія́ Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́ющу ті почтенну би́ти честнейшим єпи́скопства са́ном, всу́є потщишася гони́телі Це́ркве Христо́ви пре́жде архієре́йства твоєго́ грозними словеси́ і преще́нії тя устраши́ти, я́ко благода́ть Свята́го Ду́ха досто́йно пома́за тя во святи́телі землі́ Влади́мирськия, іді́же іспові́дник і Правосла́вія учи́тель яви́лся єси́, Афана́сіє боголюбе́зне. Помина́юще у́бо ревностноє служе́ніє твоє́, глаго́лем ті си́це:","Ра́дуйся, ві́ри пра́вия крі́пкий побо́рниче;","ра́дуйся, раско́ла нові́йшаго небоя́зненний обличи́телю.","Ра́дуйся, мудрова́ній ві́ка сего́, вознося́щихся на ра́зум Бо́жий, посрамле́ніє;","ра́дуйся, от волко́в, в оде́жді о́вчей во ста́до Христо́во входя́щих, огражде́ніє.","Ра́дуйся, смуще́нієм коле́блемих в і́стині утверждавий;","ра́дуйся, отсту́пников ко обраще́нію приводи́вий.","Ра́дуйся, Афана́сіє, но́вий іспові́дниче і Правосла́вія учи́телю."]},{"h":"Кондак 4","ps":["Бу́ри і см'яте́нію раско́ла проти́ву стоя́, а́ще і в заточе́ніє бисть непра́ведно вве́ржен, святи́телю Бо́жий, оба́че не оста́вил єси́ корми́ла церко́внаго, вся ві́рния писа́ньми твої́ми увіщава́я і моля́, да не соєдиня́ються с отступниками ні да боя́ться лука́ваго того́ вре́мене, но я́ко ма́лоє ста́до, єму́же благоізво́ли Оте́ць Небе́сний да́ти Ца́рство, взива́ють ви́ну: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше, дивля́хуся всі ві́рнії благодушію твоєму́, іспові́дниче, темни́цю бо, в ню́же затворе́н бисть, прибі́жище благо́є от поветрія обновленчеськаго нариця́л єси́, імі́я же та́мо соузников нема́ло, вку́пі с тобо́ю за ві́ру Христо́ву стра́ждущих, весели́лся єси́ о Го́споді со єдиноми́сленники твої́ми, вся святи́я землі́ Ру́ськия моли́твенно воспіва́я. Ми же, я́ко досто́йний о́браз нам злострада́нія явля́єши, прино́сим ті такова́я:","Ра́дуйся, темни́цю моли́твенним сія́нієм озари́вий;","ра́дуйся, і во враті́х сме́ртних Жизнода́вцю хвалу́ возсилавий.","Ра́дуйся, стра́ждущих і́стини ра́ди милосе́рдий уті́шителю;","ра́дуйся, і безбожников заточе́нних человіколю́бний пита́телю.","Ра́дуйся, скорбми́ от любве́ Бо́жия не разлученний;","ра́дуйся, в терпі́нії твоє́м от Го́спода укрепленний.","Ра́дуйся, Афана́сіє, но́вий іспові́дниче і Правосла́вія учи́телю."]},{"h":"Кондак 5","ps":["Богохранимаго ізбра́нника помишля́єм тя, дру́же Христо́в Афана́сіє, зане́ на бре́зі Онежськаго єзе́ра в темни́ці наро́чито учиненной, да би заточенния та́мо сме́рті удо́бно преда́ти, мно́зі спленници твоя́ ну́ждні от мучи́телей кончи́ну прия́ша, тебі́ же, тріє́ мі́сяци день і нощ убіє́нієм безсудним угрожаєма би́вша, ізба́ви Госпо́дь Многоми́лостивий, Єму́же благода́рно воззва́л єси́: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дя всегда́ очи́ма се́рдця твоєго́, духоно́сне Афана́сіє, коликими ра́нами і труди́ стяжа́ша отці́ святі́ї і́стинноє по Бо́зі житіє́, доса́ди і укори́зни мно́гая претерпіва́л єси́, гони́телей твої́х, я́ко запові́да Христо́с, благословля́я. Обремене́н же бив го́ркими рабо́тами, во узи́лищі, а́ки втори́й Іоа́нн Дамаски́н, вся мі́ста нечи́стая рука́ма твої́ма безро́потні омива́л єси́. Неізрече́ннаго ра́ди смире́нія твоєго́ прино́сим ті похва́льная сія́:","Ра́дуйся, кро́тости пречу́дния о́бразе;","ра́дуйся, блаже́ннійшаго послуша́нія си́не.","Ра́дуйся, от нечести́вих уничиже́ніє в честь себі́ вміни́вий;","ра́дуйся, обидящим тебі́ вседу́шно погріше́нія прости́вий.","Ра́дуйся, враждебников твої́х возлюбителю нелицемі́рний;","ра́дуйся, ненавидящим тебі́ благоді́телю усе́рдний.","Ра́дуйся, Афана́сіє, но́вий іспові́дниче і Правосла́вія учи́телю."]},{"h":"Кондак 6","ps":["Пропові́дник немолчен Єва́нгелія Христо́ва і в темни́цях яви́лся єси́, Афана́сіє досточу́дне, разбо́йников бо да́же і душегубцев суро́вих к покая́нію приводи́л і науча́л єси́ піснь хвали́ і благодаре́нія воспіва́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́вшу тебі́ в темни́ці сві́том і́стини, приказа мучи́тель ні́кий отвести́ тя во узи́лищі іно́є, і стражници, я́же ведо́ша тебі́, немилосерди би́ша зіло́ і томляху тя, ста́рче святи́й, ско́ро гоня́ще, во є́же ма́лими де́ньми прейти́ толи́кую долготу́ путі́. Та́же гла́дом в заточе́нії том непреста́нно морим бисть, я́ко єдва́ тебі́ живу́ оста́тися. Оба́че, крі́постію тіле́сною ізнемогая, не ізнемога́л єси́ терпі́нієм, вся Христа́ ра́ди препобіжда́я. Ми же, таково́му див'я́щеся по́двигу твоєму́, поє́м ті си́це:","Ра́дуйся, без кро́ве му́чениче добропобі́дний;","ра́дуйся, во́їне Христо́в непреодолі́нний.","Ра́дуйся, огне́м страда́ній па́че зла́та іскушенний;","ра́дуйся, в му́жестві непоступнем па́че адама́нта утвержде́нний.","Ра́дуйся, кро́тці в же́ртву пра́вди Бо́га ра́ди себе́ преда́вий;","ра́дуйся, слеза́ми всі́янноє ра́достію пожавий.","Ра́дуйся, Афана́сіє, но́вий іспові́дниче і Правосла́вія учи́телю."]},{"h":"Кондак 7","ps":["Хотя́ще безбожници, іспові́данія ра́ди і са́на твоєго́ святи́тельськаго, не отпусти́ти да́же по заточе́нії тя свобо́дна, глаго́лаша лука́вне, я́ко ні от кого́ і́маши обрісти́ послуже́нія в ста́рости твоє́й, і затвори́ша тя в темни́чнім до́ме призрі́нія, гді па́че не́же в узи́лищі, безчи́сленними скорбми́ і поноше́нії стужа́ху ті. Но попече́нієм христия́н благочести́вих от го́ршаго мі́ста о́наго ізведе́н бил єси́, воспіва́я по́мощі пода́телю Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вому наста́вшу гоне́нію на Це́рков Христо́ву, повелі́ша богопротивници заключи́ти святи́я хра́ми, а іни́я до основа́нія разори́ти. Ти же, на Го́спода наді́яся несумні́нно, му́жество бли́жнім твої́м внуша́л єси́, да не бу́дуть страшли́ви і малоду́шнії, рече́ бо Госпо́дь, я́ко врата́ а́дова не одолі́ють Це́ркві Єго́. Ті́мже вопіє́м ті си́це:","Ра́дуйся, неізрече́ннаго милосе́рдія Христо́ва до́брий вестниче;","ра́дуйся, благонаде́жнаго упова́нія Бо́жия ти́хий А́нгеле.","Ра́дуйся, глубино́ю покая́нія висоту́ смиренному́дрія стяжа́вий;","ра́дуйся, от сино́вняго Це́ркві послуша́нія к соверше́нію святи́х оте́ць єя́ востекший.","Ра́дуйся, за Оте́чество на́ше моли́твенниче непреста́нний;","ра́дуйся, хода́таю о лю́діх єго́ ко Творцю́ неуси́пний.","Ра́дуйся, Афана́сіє, но́вий іспові́дниче і Правосла́вія учи́телю."]},{"h":"Кондак 8","ps":["Стра́нноє і неудо́б разумі́ємоє чу́до яви́ о тебі́ Госпо́дь, святи́телю Афана́сіє, литургисавшу бо ті во святі́й оби́телі преподо́бнаго Се́ргия, ні́циї от моля́щихся зреша тя а́ки би во́лною, із алтаря свята́го і па́ки во о́ний по возду́ху ізноси́ма і вносима би́ти. Самови́дці же чудеси́ тому́ со удивле́нієм возопи́ша в сердця́х свої́х Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Всім неблагоразсудним, я́же то́чію в домі́х свої́х моли́шася, обще́нія же церко́внаго ся отлучаху, богоразу́мними словеси́ і посла́ньми твої́ми, нака́зовал єси́, миротво́рче усе́рдний, присоєдини́ться, а́ки у́дом, про́чему тілесі́ церковному, да раско́ла би но́ваго не сотвори́ли, і тіх к согласному єдиномислію до́брі упра́вил єси́. Того́ ра́ди і ми, ми́ра днесь Це́ркве Правосла́вній і ско́раго раздо́ром утоле́нія взиску́юще, зове́м ті:","Ра́дуйся, собла́зни і несогла́сія среді́ ві́рних потреби́вий;","ра́дуйся, хито́на церко́внаго раздранію возбрани́ти предуспі́вий.","Ра́дуйся, расточе́нния о́вці Христо́ви во єди́но ста́до собира́яй;","ра́дуйся, заблужда́ющих от путі́ і́стиннаго к покая́нію обраща́яй.","Ра́дуйся, я́ко послуша́нію Ма́тері Це́ркві ча́да єя́ наставля́єши;","ра́дуйся, я́ко ві́ру правосла́вную храни́ти науча́єши.","Ра́дуйся, Афана́сіє, но́вий іспові́дниче і Правосла́вія учи́телю."]},{"h":"Кондак 9","ps":["Всю ві́рним би́вшую ра́дость кто ізрещи́ возмо́жеть, святи́телю сла́вне, єгда́ во Влади́мирі гра́де яви́лся єси́, пра́зднества ра́ди осми́ сот лі́том собо́ра Успе́нськаго; ка́ко кли́риці і вся лю́ди сла́дці зря́ху на тя і любе́зно о Го́споді тя цілова́ху; та́же виді́нієм твої́м духо́внаго весе́лія іспо́лньшеся, вма́лі не на рука́х свої́х внесо́ша тебі́ во храм, пою́ще Бо́гові: Аллилу́я."]},{"h":"Ікос 9","ps":["Ветію тя преізя́щна показа́ Госпо́дь, Афана́сіє благоглаго́ливе, пі́сньми но́вими украси́вшаго па́м'яті і пра́здники святи́х землі́ Ру́ськия, гимни бо церко́вния і кано́нов словеса́ слага́я, в такови́х труді́х душеполе́зних і Це́ркві Христо́вой зіло́ потре́бних, препроводи́л єси́ лі́та дово́льна, отту́ду же і піснопи́сця прозва́ніє стяжа́л єси́. Ми же, от умиле́нних глаго́лов твої́х і до днесь, а́ки пи́щею духо́вною пита́ющеся і а́ки сла́дким пото́ком ся напая́юще, восхваля́єм тя:","Ра́дуйся, тала́нт песнотворчества, от Бо́га ті да́нний, ізря́дно умно́живий;","ра́дуйся, молитвосло́вія многоразли́чна, послуша́нія ра́ди церко́внаго, со тща́нієм до́брі іспра́вивий.","Ра́дуйся, цівни́це духо́вная, се́рдця на́ша увеселя́ющая;","ра́дуйся, істо́чниче ізоби́льний, во́ду живоно́сную нам істоча́ющий.","Ра́дуйся, я́ко песнописці но́вия к усе́рдію благочести́вому подвиза́єши;","ра́дуйся, я́ко, от слове́с твої́х оправда́нний, і нам у Бо́га оправда́нія мо́лиши.","Ра́дуйся, Афана́сіє, но́вий іспові́дниче і Правосла́вія учи́телю."]},{"h":"Кондак 10","ps":["Спасе́нному путі́ по вся дні ча́да церко́вная наставля́л єси́, духоно́сне Афана́сіє, мно́зі бо ві́рнії с любо́вію к тебі́ теча́ху, да би поучи́тися от честна́го житія́ твоєго́, поєли́ку се́рдцем смире́н і тих оби́чаєм, негневлив і кро́ток, і всіх доброді́телей іспо́лнен сий, ді́ли твої́ми па́че слове́с науча́л єси́ пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Сті́ну тве́рдую от наві́т і ко́зней вра́жиїх ві́ру правосла́вную пе́рвіє пропові́дал єси́, ста́рче святи́й, та́же покая́ніє сле́зноє і моли́тву непреста́нную вку́пі с богоуго́дними ді́ли, і себе́ на служе́ніє всім приходящим к тебі́ предавая, мно́гих ко спасе́нію до́брі упра́вил єси́. Сего́ ра́ди і ми, недосто́йнії, руководствія до́браго тре́бующе, вопіє́м ті та́ко:","Ра́дуйся, недоумевающим благи́й советниче;","ра́дуйся, заблужда́ющих кро́ткоє вразумле́ніє.","Ра́дуйся, душ см'яте́нних сла́достний умири́телю;","ра́дуйся, неудобоїзцельних страсте́й отгони́телю.","Ра́дуйся, лука́вия по́мисли в сердця́х челові́чеських прови́дівий;","ра́дуйся, благоуветливими словеси́ ко отложенію гріхо́внаго прило́га увещававий.","Ра́дуйся, Афана́сіє, но́вий іспові́дниче і Правосла́вія учи́телю."]},{"h":"Кондак 11","ps":["Пі́нію моле́бному приліжа́ща усе́рдно, уті́ши тя Госпо́дь пред кончи́ною виді́нієм чу́дним, я́ко святи́х землі́ Ру́ськия, ї́хже при́сно почита́л бі любо́вію, зрі́ти сподо́бился єси́ ку́пно со Христо́м, Єму́же а́біє воззва́л єси́: Аллилу́я."]},{"h":"Ікос 11","ps":["Сві́том Боже́ственнаго явле́нія осія́нний, послі́дній бо день і час блаже́ннаго ісхо́да твоєго́ провозвещен бисть от Го́спода ті, ми́рно пре́дал єси́, тайнови́дче, ду́шу твою́ в ру́ці Христа́ Бо́га, Єго́же от ю́ности возлюби́л і за Него́же толи́кая пострада́л єси́. Но я́ко в животі́ своє́м, подви́жниче ве́лій, світ бисть ми́ру та́кожде і по преставле́нії чудеси́ мно́гими озари́ти нас не престає́ши, зову́щих:","Ра́дуйся, во́їна ю́наго от лю́тия сме́рті чуде́сно ізба́вивий;","ра́дуйся, вдови́цю благочести́вую із ру́ку зловольника ди́вно ісхи́тивий.","Ра́дуйся, я́ко персть і би́ліє от гро́ба твоєго́ неду́жним ісціле́нія подаваша;","ра́дуйся, я́ко мно́зі при гро́бі твоє́м молившеся, душепагубним страсте́м врачество́ обріто́ша.","Ра́дуйся, честна́го бра́ка христия́нськаго ізві́стний покрови́телю;","ра́дуйся, ді́вствующих і цілому́дренних засту́пниче благонаде́жний.","Ра́дуйся, Афана́сіє, но́вий іспові́дниче і Правосла́вія учи́телю."]},{"h":"Кондак 12","ps":["Благода́ть, ю́же ті́сним твої́м житіє́м і по́двиги мно́гими у Бо́га стяжа́л єси́, ві́дая, освяще́нний Собо́р Правосла́вния на́шея Це́ркве сопричте тебі́ со́нму всіх ру́ських святи́х, в том же сві́тло лику́єши ни́ні, всесоставним гла́сом воспіва́я побі́дную піснь: Аллилу́я."]},{"h":"Ікос 12","ps":["Поє́м тя со умиле́нієм, святи́телю достохва́льне, я́ко во оби́телі го́рній всели́вийся, на землі́ нам оста́вил єси́ честни́я твоя́ мо́щі, я́же благогові́йно днесь почита́єм і ско́раго ісціле́нія скорбе́м душе́вним і тіле́сним ча́юще, взива́єм ті та́ко:","Ра́дуйся, блаже́нства ізгна́нних пра́вди ра́ди пра́ведно удосто́єнний;","ра́дуйся, в сві́тлостіх немерцающих Пресвяти́я Тро́йці при́сно живу́щим соводворенний.","Ра́дуйся, а́нгельським чи́ном сликовствующий во ви́шніх;","ра́дуйся, от челові́к похвали́ досточестно приє́млющий в ни́жніх.","Ра́дуйся, ві́рою тя почита́ющим ско́роє утіше́ніє;","ра́дуйся, любо́вію тя воспіва́ющим благо́є весе́ліє.","Ра́дуйся, Афана́сіє, но́вий іспові́дниче і Правосла́вія учи́телю."]},{"h":"Кондак 13","ps":["О святи́телю благоглаго́ливе Афана́сіє, і́мене Бо́жия досточу́дний іспові́дниче, землі́ Владимирстей ра́дованіє і Це́ркві Святі́й украше́ніє, убо́гоє сіє́ усли́ши моле́ніє на́ше і благомо́щноє хода́тайство твоє́ вознеси́ о нас Го́сподеві, да вся поле́зная ко спасе́нію душе́вному нам да́руєть, во є́же непреткнове́нно вни́ти нам в Ца́рство Небе́сноє і воспі́ти та́мо Живоночальной Тро́йце: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгельськаго ча́я о́браза, Афана́сіє блаже́нне, ізмла́да ігранієм детським не внима́л єси́ ра́зумом, моли́твам же те́плим во хра́мі Госпо́дні і рукоді́лію в до́мі ма́тернем, а́ки би в ке́ллії, всегда́ приліжа́, дерзнове́нно предвозвещал єси́ отроко́м, сверстним тебі́, я́ко і́маши би́ти Це́ркве Христо́ви служи́тель свяще́нний. Ві́дуще у́бо ми, я́ко Про́мислом Бо́жиїм сбися рече́ніє твоє́, со удивле́нієм зове́м ті:","Ра́дуйся, дре́внею і свято́ю земле́ю Влади́мирською в добронравії воспита́нний;","ра́дуйся, в Ла́врі преподо́бнаго Се́ргия ли́ку інокующих вчиненний.","Ра́дуйся, посто́м і моли́твою житіє́ богоуго́дноє стяжа́вий;","ра́дуйся, от Го́спода к по́двигу свиді́тельства во дні лука́вия ізбра́нний.","Ра́дуйся, благолі́пія церко́внаго блюсти́телю;","ра́дуйся, прему́дрим Правосла́вія наста́вником подо́бниче.","Ра́дуйся, Афана́сіє, но́вий іспові́дниче і Правосла́вія учи́телю."]},{"h":"Кондак 1","ps":["Возбранниче сві́тлий на тьму ві́ка сего́, во вся ору́жія Бо́жия облече́нний і ві́ру Христо́ву, а́ки щит, проти́ву су́єтних мудрова́ній держа́вий, восхваля́єм тя любо́вію, святи́телю і іспові́дниче Афана́сіє, ти же я́ко моли́твенник о нас ко Го́споду дерзнове́нний, утвержде́нія в і́стині Правосла́вія іспроси́ нам, зовущим:","Ра́дуйся, Афана́сіє, но́вий іспові́дниче і Правосла́вія учи́телю."]},{"h":"Молитва","ps":["О, многострада́льне і благоглаго́ливе святи́телю і іспові́дниче Христо́в Афана́сіє, па́стирю до́брий па́житей Це́ркве Ру́ськия, Правосла́вія ревни́телю, покая́нія пропові́дниче, моли́тви сто́лпе, любве́ неіссяка́ємий істо́чниче, цівни́це богодухнове́нная! Ти, земле́ю дре́внею і свято́ю воспита́нний, ізмла́да сосу́д ізбра́нний Бо́гу яви́лся єси́, ре́вностно служа́ Єму́ словеси́ і ді́ли, моли́твою те́плою, посто́м неосла́бним, ми́лостинею нелицеме́рной. Службе Бо́жієй зіло́ приліжа́, тала́нт песнотво́рчества усе́рдно умно́жил єси́ і мно́гими духоно́сними пі́нії Це́рков Ру́ськую украси́л єси́, найпа́че же потруди́лся в прославле́нії святи́х землі́ Ру́ськия, ї́хже пред кончи́ною ку́пно с Го́сподом зрі́ти сподо́бился єси́. І́стини ра́ди і кро́тости і пра́вди досто́йно пома́за тя во святи́телі Влади́мирськия благода́ть Свята́го Ду́ха, є́юже просвіще́н, пропові́дал єси́ Правосла́вія преда́нія неукло́нно посреді́ безбо́жних гони́телей. А́ще і в заточе́ніїх, ізгна́ніях і го́рких рабо́тах три́дцять літ проби́л єси́, поноше́нія, озлобле́нія і ра́ни за Христа́ сла́дці претерпіва́я, ти, свяще́нноє іспові́даніє я́ко забра́ло восприї́м, богоху́льниє дерзнове́нно обличи́л єси́ і безпло́тниє враги́ посрами́л єси́, па́ству свою́ ді́ли па́че слов поуча́я, я́ко Бо́гу подоба́єть повинова́тися па́че челові́к. Ті́мже блаже́нства ізгна́нних пра́вди ра́ди сподо́бився і Престо́лу Небе́сному предстоя́, моли́ Всеблага́го Бо́га на́шего, да утверди́ть Це́рков Ру́ськую, єя́ па́стирей непози́блеми в і́стинах ві́ри, от єресе́й і раско́лов, да пребу́дуть ча́да єя́ тве́рди во іспові́данії свята́го Правосла́вія, претерпіва́я все напа́сти вре́мені, прославля́я єди́ним се́рдцем і єди́ними усти́ ди́вного во святи́х Свої́х Бо́га, Отця́ і Си́на і Свята́го Ду́ха, во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Сла́ви Бо́жия ревни́теля / і благолі́пія церко́внаго блюсти́теля, / ті́сним житіє́м і мно́гими по́двиги / вели́кому ієра́рху Александрі́йському подо́бника, / святи́теля Афана́сія, іспові́дника Россі́йськаго, / усе́рдно восхва́лим, ві́рнії. / Сей бо при́сно мо́литься / о спасе́нії земна́го Оте́чества своєго́ / і о всіх, живу́щих в нем, / велегла́сно с любо́вію взива́я: / Русь Свята́я, / храни́ ві́ру правосла́вную, // в не́йже тебі́ утвержде́ніє."]},{"h":"Кондак, глас 3","ps":["Днесь Афана́сій святи́тель, / Христо́в іспові́дник і пра́ведник, / в невече́рнім Ца́рстві Сла́ви / сві́тло лику́єть / і в со́нмі всіх Ру́ських святи́х / всесоста́вним гла́сом / побі́дную піснь воспіва́я, / прилі́жно мо́лить о нас // Преві́чнаго Трієди́наго Бо́га."]},{"h":"Величання","ps":["Велича́єм тя, / святи́телю о́тче Афана́сіє, / і чтим святу́ю па́м'ять твою́, / ти бо мо́лиши о нас // Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст апостолу і євангелісту Луці","e":"Akathist to the Apostle and Evangelist Luke","secs":[{"h":"Кондак 1","ps":["Прему́дрим про́мислом Бо́жиїм ізбра́нний, да благовіству́єши сві́тлость Христо́ва Єва́нгелія всему́ ми́ру, Луко́ всеблаже́нне, ве́ліє дерзнове́ніє і́маши пред лице́м Го́спода, Чей земни́й живо́т і уче́ніє списа́л єси́. Іспроси́ і нам, немощни́м і слабим, проще́ніє согріше́ній і утверди́ в нас наде́жду Ца́рствія Небе́снаго, да возмо́жем ті всера́достно взива́ти:","Ра́дуйся, святи́й Луко́, Євангели́сте Христо́в і Апо́столе."]},{"h":"Ікос 1","ps":["Всеми́лостивий Госпо́дь в гріхі́ потопленному ро́ду челові́чеському посла́ Си́на Своєго́, да Он Свої́м живото́м, сме́ртію і сла́вним Воскресе́нієм ізведе́ть сей род із тьми і напра́вить к свя́тости. Чрез теб'я́ же, Євангели́сте святи́й, начертани та́йни не́ба і землі́, даби́ всі челові́ци до конця́ ві́ка путь к той свя́тости вели і, благода́рні су́ще, взивали ті:","Ра́дуйся, Ду́хом Святи́м просвіще́нний на списа́ніє Єва́нгелія;","ра́дуйся, Фео́филу достопочтенному і всім нам би́сер драги́й Єва́нгелія Христо́ва обрі́тший.","Ра́дуйся, я́ко Бо́гом ізбра́н бил єси́, да об'явиши та́йну спасе́нія;","ра́дуйся, благовестителю Благи́я Ві́сти.","Ра́дуйся, я́ко Христа́ прише́дша грі́шния спасти́ проповедавший;","ра́дуйся, я́ко єди́н єси́ от чети́ріх Євангели́стов.","Ра́дуйся, я́ко Дух Святи́й і чрез тебі́ Четвероєва́нгеліє в мир ізлія́л єси́;","ра́дуйся, в та́йни Бо́жії ду́хом воснесийся.","Ра́дуйся, я́ко словеса́ твоя́ просвіти́ша вселе́нную;","ра́дуйся, я́ко мре́жею твоєго́ Єва́нгелія мно́гі слове́сни душі́ улови́вий.","Ра́дуйся, із'яснителю Но́ваго Заві́та;","ра́дуйся, звіздо́, в Це́ркві Небе́сній сія́ющая.","Ра́дуйся, святи́й Луко́, Євангели́сте Христо́в і Апо́столе."]},{"h":"Кондак 2","ps":["В мла́дости твоє́й возжела́вше мирськи́я му́дрости, Луко́ прему́дрий, єй научи́лся єси́, прише́дше же в Ієрусали́м із Антіохі́ї, єгда́ Госпо́дь Ісу́с Христо́с Своє́ Боже́ственноє сло́во на землі́ сі́ял єси́, се́рдцем до́броє сі́м'я восприя́л єси́, ісполнившись же небе́сній ра́дости, воспі́л єси́ велегла́сно Богочеловеку Христу́: Аллилу́я."]},{"h":"Ікос 2","ps":["Зе́рно боже́ственной любве́ прозябе́ у тебе́ стокра́тний плод, я́ко ти, слу́шая Єго́ уче́ніє і чудеса́ ви́дя, іспо́лнился боже́ственной му́дрості і ві́дінія, коли́ких е́ллинськая і єги́петськая училища да́ти ті тще́тни бисть. Отту́ду ізбра́ тя Госпо́дь і про́чих се́дмдесят Апо́стол і посла́, да пропові́діте Благу́ю Вість спасе́нія ро́да челові́чеськаго. Ми же чрез твоє́ Свято́є Єва́нгеліє і дони́ні пія́ ту Божю прему́дрость, воспіва́єм ті та́ко:","Ра́дуйся, Христо́вой благода́тію в се́рдці уя́звленний;","ра́дуйся, я́ко боже́ственная прему́дрость бі ті вмі́сто мирсько́й му́дрости, є́йже обучен бисть.","Ра́дуйся, я́ко вся оста́вивши, за Христо́м Господом послі́довал єси́;","ра́дуйся, вестниче Госпо́день. Ра́дуйся, зижди́телю ві́ри Христо́вой;","ра́дуйся, самови́дче, Єго́ же чаяли язи́ци.","Ра́дуйся, родосло́віє Христо́во до Ада́ма возведший;","ра́дуйся, Влади́чиці іко́ну пе́рвий написавший.","Ра́дуйся, Ісу́са Сино́м Бо́жиїм і Челові́чеським возвестивший;","ра́дуйся, неутоми́мий ратниче за і́стину Христо́ву.","Ра́дуйся, іску́сний ловителю душ людськи́х;","ра́дуйся, сі́ятелю до́браго сі́мені, стокра́тний плод приносящего.","Ра́дуйся, святи́й Луко́, Євангели́сте Христо́в і Апо́столе."]},{"h":"Кондак 3","ps":["Вооруженний от Го́спода си́лою і вла́стію, святи́й Луко́, да проповедеши Єва́нгеліє і твори́ши чудеса́, со про́чими Апо́столами гряде пред лице́м Го́спода Христа́, уготовля́я Єму́ путь і пропові́дуя лю́дем я́ко в мир прише́л єси́ от ві́ка обетованний Мессія, Ко́єму всі я́ко Бо́гу от ни́ні і до ві́ка да взива́ють: Аллилу́я."]},{"h":"Ікос 3","ps":["В послі́днія дні земна́го живота́ Го́спода Ісу́са Христа́, єгда́ непра́ведния суді́й Пра́веднаго Судію́ осуди́ша і на Кресті́ Го́спода расп'я́ша, ти, святи́й Луко́, в Ієрусали́мі преби́л єси́, со слеза́ми взира́я, ка́ко непови́нная кров Учи́теля твоєго́ ізлива́шеся на грі́шную зе́млю. Пла́чуще єди́но с тобо́ю, с печа́лію ми рече́м ті:","Ра́дуйся, я́ко страда́нія Христа́ Спаси́теля списа́л єси́;","ра́дуйся, ві́рний слуго́ Всецаря́ Христа́.","Ра́дуйся, я́ко сла́ву Бо́жию возвісти́л єси́;","ра́дуйся, луче́ небе́сная во тьмі ми́ра сего́.","Ра́дуйся, проти́ву врага́, в Іу́ду вше́дша, нас вооруживий;","ра́дуйся, Петро́м усеченним і Христо́м ісцеленним рабо́м милосе́рдію нас науча́ющий.","Ра́дуйся, кладезе, із него́же водо́ю живо́ю напоя́ємся;","ра́дуйся, я́ко ра́достно і без стра́ха словеса́ Бо́жії в лю́ди приносивший.","Ра́дуйся, се́рдця обрі́заніє прия́ти па́че плотська́го обрі́занія возжелавший;","ра́дуйся, до́броє гро́здіє виногра́да Госпо́дня.","Ра́дуйся, я́ко лице́м к лицю́ Бо́га чрез Христа́ узрі́л єси́;","ра́дуйся, я́ко Го́спода і ни́ні в Ца́рстві Небе́снім ви́диши.","Ра́дуйся, святи́й Луко́, Євангели́сте Христо́в і Апо́столе."]},{"h":"Кондак 4","ps":["Печа́ль твоя́ претвори́ся в ра́дость, богоуби́йць же ра́дость обрати́ся в печа́ль, я́ко да не мощна́ бисть смерть проти́ву Істо́чника Живота́ і ка́мень гро́бний не можа́ше удержа́ти Ка́меня краєуго́льнаго. Госпо́дь твой воскре́се із ме́ртвих і ми́рові дарова́ живо́т ві́чний. Ти же с бра́тією в ра́дості всеси́льній до небе́с восклиця́ше: Аллилу́я."]},{"h":"Ікос 4","ps":["Єгда́ с Клео́пою в неді́лю Воскресе́нія ідо́ша в бли́жній Еммау́с, яви́ся вам Госпо́дь і ідо́ша с ва́ми. І бисть вам се́рдце горя́ще і душа́ тре́петна, доко́лі Он вас поуча́л о Себі́ от проро́к і писа́нія, ви же Го́спода не позна́ша, до́ндеже на трапе́зі ве́чері преломи́ Он хліб і благослови́, і отверзлись вам о́чі і уразумі́ша, я́ко то бисть воскреси́й Госпо́дь. Познава́я о том із твоєго́ Єва́нгелія, і ни́ні душі́ на́ші притрепетни бисть, сего́ же ра́ди ра́достно воспіва́єм ті:","Ра́дуйся, Воскресе́ніє Христо́во видевший;","ра́дуйся, от несмисленности к богомудренности Христо́м приведенний.","Ра́дуйся, я́ко Христо́с отве́рз ті ра́зум, да уразумі́єши Писа́ніє;","ра́дуйся, я́ко бі ті се́рдце горя́ще, єгда́ Го́спода слушал єси́ на путі́ во Еммау́с.","Ра́дуйся, я́ко ті Христо́с Свої́ма рука́ма хліб преломленни препода́л єси́;","ра́дуйся, я́ко Христо́с словеса́ ва́ша о явле́нії Єго́ на путі́ в Еммау́с, па́ки явившись ученико́м, запечатлі́л єси́.","Ра́дуйся, я́ко іспи́в ча́шу прему́дрости, мно́гих позна́нієм Христа́ Спа́са напої́л єси́;","ра́дуйся, я́ко всім Єва́нгеліє воскре́сшаго Христа́ пропові́дал єси́.","Ра́дуйся, я́ко нам істо́чник спасе́нія отве́рзл єси́;","ра́дуйся, я́ко Путеводительницю к жи́зні во о́бразі нам препода́л єси́.","Ра́дуйся, сві́тлосте разу́мнаго Со́лнця;","ра́дуйся, я́ко нас научи́ша ві́ровати в Святу́ю Тро́йцю.","Ра́дуйся, святи́й Луко́, Євангели́сте Христо́в і Апо́столе."]},{"h":"Кондак 5","ps":["Єгда́ воскреси́й Госпо́дь спасе́нія на́шего ра́ди основа́ Це́рков Свою́ і по обітова́нію низпосла́ в день п'ятидеся́тий по Воскресе́нії Ду́ха Свята́го на Апо́столи, да їх запечатлеєть свиді́телі непоколеби́ми ві́ри христия́нськия, і ти, святи́й Луко́, пребива́ше в Ієрусали́мі. Ку́пно с іни́ми Апо́столи ві́рно свиді́тельствова Богочелові́ка Христа́ і воспіва́л Єму́ я́ко і́стинному Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["В оте́чество по́сліжде твоє́ Антіохі́ю напра́вился єси́, є́же бі страна́ мно́гими христия́ни населе́нная, но в Севасті́ї умедлил єси́, пропові́дующе Єва́нгеліє спасе́нія, та́мо же нетлі́нния мо́щі свята́го Іоа́нна Предте́чі почиваша. Узрі́в ті́ї, возжела́л єси́ с собо́ю їх понести́, христия́не же Севастійскиє не восхоті́вше лиши́тися сицево́й святи́ні і та́ко вручиша ті десни́цю Іоа́ннову, под ню же Сам Госпо́дь приклони́ Боже́ственную главу́ в креще́нії, ту же ти ра́достно поне́сл єси́, ми же, див'я́щеся твоє́й любві́ к святи́м, восклиця́єм ті такова́я:","Ра́дуйся, свиді́телю снисхожде́нія Ду́ха Свята́го;","ра́дуйся, я́ко нам ка́ко Це́рков создана́ била́ єсть описал єси́.","Ра́дуйся, я́ко себе́ росо́ю небе́сною яви́л єси́ і світ просвіти́л єси́;","ра́дуйся, я́ко Ду́хом Святи́м Но́вий Заві́т начерта́ся на се́рдці твоє́м.","Ра́дуйся, я́ко Ду́хом Святи́м ми́ру із'ясни боже́ственную і́стину;","ра́дуйся, Го́спода всіх ми́рові благовестителю.","Ра́дуйся, от Бо́га ізбра́нний таї́нниче;","ра́дуйся, я́ко се́рдце своє́ очи́стил єси́ сві́тлостію Ду́ха Свята́го.","Ра́дуйся, я́ко предста́тельство Предте́чі обрі́л єси́;","ра́дуйся, благочести́ваго употребле́нія веще́й освяще́нних начинателю.","Ра́дуйся, Закхея, сребролю́бієм уя́звленнаго, очи́стившагося показа́вий;","ра́дуйся, я́ко мно́гі тя засту́пником пред Бо́гом імі́ють.","Ра́дуйся, святи́й Луко́, Євангели́сте Христо́в і Апо́столе."]},{"h":"Кондак 6","ps":["С десни́цею же Іоанновою, святи́й Луко́, я́коже сребролю́бець, бесценноє сокро́вище стяжа́в, дости́г своєго́ оте́чества к ра́дости ве́лієй христия́н Антіохійських, ко́їх в словеса́х боже́ственних і ра́дости Христоваго Єва́нгелія па́че утверди́л єси́, глаго́лаше же їм Си́на Бо́жия чудеси́, є́же свої́ма очи́ма ви́діл єси́, і уче́ніє Спаси́теля ми́ра, є́же свої́ма уши́ма сли́шал єси́. Внима́юще глаго́лам твої́м прему́дрим, воспіва́ли они́ ра́достно Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Пребива́л же ти в Антіохі́ї доко́лі Апо́стол Па́вел не призва́ тя, да бу́деши єму́ сотрудник і сопу́тник на путі́ Бо́жиєм і ви в Е́ллинську страну́ на про́повідь Єва́нгелія не отправишася. Па́вел же святи́й оста́ви тя в гра́ді македонськом Фили́ппи, да утверди́ши і умно́жиши Це́рков. Та́мо же преби́л єси́, пропові́дующе і насажда́юще христия́нство. Див'я́щеся таково́му твоєму́ труду́, взива́єм ті:","Ра́дуйся, неутоми́мий спутниче Апо́стола Па́вла;","ра́дуйся, со Па́влом прему́дрим ізбра́нний учи́телем язи́ков.","Ра́дуйся, я́ко неізрече́нно просвіща́єши всю вселе́нную;","ра́дуйся, всіх уя́звленних уті́шителю.","Ра́дуйся, врачу́, си́лою Ви́шняго Врача́ ісціле́ніє подаю́щий;","ра́дуйся, я́ко ти Єва́нгелієм свої́м от смертоно́снаго дре́ва ізба́вил єси́ нас.","Ра́дуйся, служе́ніє імі́нієм а́ки похва́льноє показу́ющий;","ра́дуйся, Марі́ї, Іоанни, Сусанни і про́чих благоразу́мія несребролюбива возвісти́телю.","Ра́дуйся, Іо́сифа Аримафейськаго похвалителю;","ра́дуйся, я́ко уни́ніє із серде́ць на́ших ізгна́л єси́.","Ра́дуйся, моли́твенниче наш пред Бо́гом;","ра́дуйся, я́ко мно́гих ко сві́тлости Живота́ призва́л єси́.","Ра́дуйся, святи́й Луко́, Євангели́сте Христо́в і Апо́столе."]},{"h":"Кондак 7","ps":["Єгда́ святи́й Па́вел при конці́ тре́тіяго апо́стольськаго путеше́ствія па́ки Фили́ппу посіти́, он тя, святи́й Луко́, в Кори́нф направи́л єси́, да приї́меши благослове́ніє си́рим христия́ном, в Палести́ні су́щим. С того́ часа́ не отступа́юще от вели́каго Апо́стола, воспіва́л єси́ с ним вку́пі Всемогу́щему Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Обойдя в ра́дості все Це́ркві в Асі́ї і Іуде́ї, ви Палести́ни дости́гли єсте́, гра́да Кесарі́йськаго, іді́же євре́ї, от лука́ваго одержи́мия, око́вами от ри́мськия вла́сті свята́го Па́вла обложили єсте́, он же потре́бова суда́ ке́саря в Ри́мі. На путі́ же к о́ному, ти єму́ неотсту́пно предстоя́л єси́, мно́гі біди́ претерпіва́юще на мо́рі і на землі́. Восхваля́я за то, почита́юще тя восклиця́єм:","Ра́дуйся, Па́влов помо́щниче в служе́нії;","ра́дуйся, я́ко єго́ пропові́даніє описал єси́.","Ра́дуйся, врачу́ возлю́бленний;","ра́дуйся, колоссян чрез Па́вла во у́зах приветствовавший.","Ра́дуйся, Христа́ сло́вом і писа́нієм свидетельствовавший;","ра́дуйся, я́ко го́рку от безбо́жия соль Боже́ственною солью усладивший.","Ра́дуйся, стрело благоче́стія Христо́ва;","ра́дуйся, я́ко нас напоя́єши Єва́нгелієм Христо́вим.","Ра́дуйся, трубо́ Боже́ственния благода́ті;","ра́дуйся, та́їн неізрече́нних пропові́дниче.","Ра́дуйся, всіх немощни́х укріпле́ніє;","ра́дуйся, от де́монов ізба́вителю.","Ра́дуйся, святи́й Луко́, Євангели́сте Христо́в і Апо́столе."]},{"h":"Кондак 8","ps":["Дости́гнув Ри́ма, ти ку́пно со Апо́столами Па́влом, Ма́рком, Аристархом і про́чими Христа́ проповедовал єси́, вначале євре́ом, после же їх, ва́шим словеса́м не ві́рующим, ра́спри меж собо́ю іму́щим, і всім, не знающим Бо́га, ко́ї усли́шав словеса́ спасе́нія і Ду́хом Святи́м просветленнії, ра́достно воспели Воплоти́вшемуся Христу́ Го́споду: Аллилу́я."]},{"h":"Ікос 8","ps":["Во вре́м'я о́но в Ри́мі ти, святи́й Луко́, соверши́ то, на что Бог ізбра́ тя от ві́ка: списа́ Свято́є Єва́нгеліє, в ко́єм начерта́л живо́т і род Го́спода Ісу́са Христа́, я́ко сам ви́ді і сли́ша і я́ко от самовидцев і слуг Сло́ва прия́л єси́. В о́ном свято́м послуша́нії Апо́стол Па́вел руководи́ тя, по́сліжде он і твоє́ Свято́є Єва́нгеліє похвали́. В Ри́мі же ті су́щу і словеса́ Апо́стола Па́вла слушающу, і дія́нія апо́стольськія списани тобо́ю бисть. Не ві́ми, я́ко тя іні́ї восхваля́ють, ми же ті прино́сим такова́я:","Ра́дуйся, я́ко безбо́жний мир Боже́ственною благода́тію напої́л єси́;","ра́дуйся, Ду́хом Святи́м запечатле́нний.","Ра́дуйся, ві́рний учениче́ неізрече́нних та́їн Христо́вих;","ра́дуйся, догма́тов церко́вних вразуми́телю.","Ра́дуйся, я́ко руко́ю Влади́чнею ви́шнім ві́дінієм обогаще́н бисть;","ра́дуйся, я́ко от Апо́стола Па́вла мно́гія та́йни Христо́ви сли́шал і списа́л єси́.","Ра́дуйся, Апо́стола язи́ков сотру́дниче неутоми́мий;","ра́дуйся, я́ко твоє́ благові́стіє про́йде по всей землі́.","Ра́дуйся, я́ко нам вино́м Бо́жієй прему́дрости се́рдця увеселил єси́;","ра́дуйся, я́ко ти єди́н благоразу́мнаго разбо́йника покая́ніє в Єва́нгелії списа́л єси́.","Ра́дуйся, бога́тство стяжавшим благоразу́міє митаря́ приведи́й;","ра́дуйся, самаря́н-язи́чников благода́рних і милосе́рдих показавший.","Ра́дуйся, святи́й Луко́, Євангели́сте Христо́в і Апо́столе."]},{"h":"Кондак 9","ps":["Єгда́ Апо́стол Па́вел после двухлетніх уз отпуще́н бі і потече́ із Ри́ма обойти ра́ніє основа́нния це́ркві, ти, Луко́ святи́й, єго́ ві́рний спу́тник в том путі́ обрі́теся. Єгда́ же Нерон жесто́коє гоне́ніє на христия́н в Ри́мі воздви́же, ви возврати́стася во є́же ободріте і укріпі́те гони́мую Це́рков, она́ же і в у́зах і в кро́ві ра́достно воспіва́ла єси́ Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Єгда́ возбешенниє безбо́жники Апо́стола Па́вла схватиша і заключи́ша в око́ви, ти святи́й Луко́, і про́чеє с ним ві́рно і неотсту́пно преби́л єси́. Єгда́ же наста́вник твой му́ченичеськи предаваше чи́стую свою́ ду́шу Го́споду, ти со слеза́ми пребива́л при нем. Соскорб'я боли твоє́й, ми велегла́сно поє́м:","Ра́дуйся, я́ко єди́ний Апо́стола Па́вла в у́зах не оста́вил єси́;","ра́дуйся, я́ко му́ченичеськую кончи́ну вели́каго Па́вла узрі́л єси́.","Ра́дуйся, от Троа́ди до врат ра́йських Па́влу послі́довавий;","ра́дуйся, богому́дрим Па́влом ізря́дно наста́вленний.","Ра́дуйся, дія́ній Апо́столов ізложителю;","ра́дуйся, світи́льниче Це́ркві.","Ра́дуйся, я́ко блиста́нієм твоєго́ ду́ха просвіща́єши се́рдця ві́рних;","ра́дуйся, лесть де́монськую теплото́ю ві́ри отгна́вий.","Ра́дуйся, я́ко Госпо́дь чрез теб'я́ мно́гія доброді́телі учини́;","ра́дуйся, ризнице, дарова́ній небе́сних іспо́лненная.","Ра́дуйся, благоче́стія непоколеби́мий сто́лпе;","ра́дуйся, я́ко і́м'я твоє́ свято́є всі язи́ци помина́ють.","Ра́дуйся, святи́й Луко́, Євангели́сте Христо́в і Апо́столе."]},{"h":"Кондак 10","ps":["После му́ченичеськия кончи́ни Апо́стола Па́вла ти, святи́й Луко́, в страні́ Італийстей, Далматстей, Галльстей, сугу́бо же - Македонстей і Ахайстей Христа́ пропові́дал єси́, всю́ду мрак безбо́жия разгоня́я і язи́ки науча́я, да всі Бо́гу Живо́му і І́стинному восклиця́ють: Аллилу́я."]},{"h":"Ікос 10","ps":["В ста́рости твоє́й ти в Єги́пет поте́кл єси́, да пропові́дуєши Благу́ю Вість спасе́нія Го́спода Ісу́са Христа́. Пропові́дуя же, мно́гая муче́нія претерпі́ і мно́жества по́двигов под'я. Возврати́вшуся же ті в страну́ Е́ллинську, ти Це́рков устроя́л єси́, свяще́нники с дияконами рукополагая, боля́щих ті́лом і душе́ю ісціля́я, за что благода́рні су́ще ми ра́достно ті взива́єм:","Ра́дуйся, я́ко Ті́ло Христо́во - Це́рков Святу́ю - устроя́л єси́;","ра́дуйся, заре́ но́ваго дне.","Ра́дуйся, путеводи́телю наш на не́бо;","ра́дуйся, дре́во до́броє, мно́гая плоди́ прине́сшеє.","Ра́дуйся, награ́ду за вість благу́ю в Ца́рствії Небе́сном восприє́мшій;","ра́дуйся, обличи́телю безбо́жия.","Ра́дуйся, пропові́дниче Бо́жиїх пресла́вних чуде́с;","ра́дуйся, я́ко нам но́вий зако́н Бо́жий списа́л єси́.","Ра́дуйся, нас на по́двиг ді́ятельния любве́ подвизающий;","ра́дуйся, я́ко із уст твої́х богото́чния води́ істеко́ша.","Ра́дуйся, я́ко про́повідію твоє́ю со́лнцю подо́бно возсія́л єси́;","ра́дуйся, я́ко іко́на твоя́ украси́ хра́ми христия́нськия.","Ра́дуйся, святи́й Луко́, Євангели́сте Христо́в і Апо́столе."]},{"h":"Кондак 11","ps":["Бі же ті осьмдесят літ і чети́ре, єгда́ зло́бнії ідолопоклонници схватиша тя і бія́ше Христа́ Го́спода ра́ди і возвесиша на масличном дре́ві во Фивах Беотійських, та́мо же і мо́щі твоя́ святи́я погребени бисть. Святу́ю ду́шу твою́ Ангелам предаю́ще, я́ко ті́ї ю ко Го́споду вознесо́ша, Ко́єму ти ві́рно в сем животе́ послужи́л єси́, ти і в о́ном сві́те воспіва́л Го́споду: Аллилу́я."]},{"h":"Ікос 11","ps":["Свята́я твої́ і чудотво́рная мо́щі мно́гих ісціли́ша, сугу́бо же оча́ми боля́щих. Констанцій цар сли́шавше сіє́, с торжество́м їх в Царгра́д прене́сл єси́. Єди́н от євну́х, злі боля́щий, уві́дівше о том, повелі́ ся на ло́же к ра́ці со твої́ми моща́ми принести́ і с тве́рдою ві́рою ра́ки прикосну́лся єси́, і с того́ часа́ здрав бі. Возрадовавшись он со іни́ми мо́щі понесе́, они́ же би́ша положе́ні под свято́ю трапе́зою ку́пно с моща́ми святи́х Апо́столов Андре́я і Тимофе́я. Ми же чу́ду таково́му див'я́щеся, взива́єм ті:","Ра́дуйся, я́ко і на твоє́й му́ченичеськой кро́ві Це́рков Христо́ва созиждена єси́;","ра́дуйся, вінце́м му́ченичеським увінча́нний.","Ра́дуйся, врачу́, от істлі́нія Христо́м до́брі уврачевавийся;","ра́дуйся, сам себе́ в же́ртву благоуха́нную за благу́ю вість прине́сший.","Ра́дуйся, я́ко мно́гия поруга́нія за Христа́ восприявший;","ра́дуйся, я́ко му́ченичеством ві́ру в Христа́ засвидетельствовавший.","Ра́дуйся, я́ко в тіїх муче́ніях стар бі і не ізнемогоше;","ра́дуйся, я́ко твоє́ тече́ніє до́броє страда́ньми запечатлі́л єси́.","Ра́дуйся, я́ко не неві́рен слуга́ Го́спода Христа́ яви́лся єси́, я́ко мно́зі от нас;","ра́дуйся, я́ко тя і земна́я і небе́сная Це́рков сла́вить.","Ра́дуйся, пе́рсті Ду́ха Свята́го;","ра́дуйся, я́ко ра́дуєшися ку́пно со святи́ми в Ца́рстві Небе́сном.","Ра́дуйся, святи́й Луко́, Євангели́сте Христо́в і Апо́столе."]},{"h":"Кондак 12","ps":["Ку́пно со слове́сним Єва́нгелієм, святи́й Луко́, Єва́нгеліє во образах ти нам оста́вил єси́, я́ко христия́нам тіх време́н ізволившим, живописа три іко́ни преблага́го ли́ка Ма́тері Бо́жієй, ре́кшей: Благода́ть Роди́вшагося от Мене́ і Моя́ ми́лость с си́ми іко́нами да пребу́дуть. Благода́рні су́ще, я́ко і нас удосто́їл єси́ благогові́йно взира́ти на лі́поту Ді́ви і Си́на Єя́, ра́достно Прему́дрому Го́споду взива́єм: Аллилу́я."]},{"h":"Ікос 12","ps":["Живописа́л єси́, святи́й Луко́, на дські іко́ни святи́х Апо́столов Петра́ і Па́вла. І та́ко нача́ток положи́л єси́ і в сем дивном і богоуго́дном ді́лі писа́нія святи́х іко́н во сла́ву Бо́жию, Пресвяти́я Богоро́диці і всіх святи́х, они́ же до сих пор благолі́пно украша́ють хра́ми Бо́жії і ко спасе́нію призива́ють всіх, благогові́йно їх почита́ющих. І за сіє́ дарова́нноє тобо́ю нам благода́рні ті су́ще, ми восклиця́єм:","Ра́дуйся, єва́нгельських та́їн благові́стниче;","ра́дуйся, весь род челові́чеський ча́ющим Спаси́теля уяснивший.","Ра́дуйся, Ма́тер Бо́жию на іко́ні ізобразивий;","ра́дуйся, я́ко Она́ твоє́ свято́є ді́ло благослови́ла єси́.","Ра́дуйся, Ді́ви лик увековечивий;","ра́дуйся, я́ко неізрече́нную ра́дость нам тім в се́рдця донесший.","Ра́дуйся, я́ко тобо́ю мно́гі чудеси́ Цари́ця Небе́сная от іко́н Свої́х предначала єси́;","ра́дуйся, я́ко благи́й лик Ма́тері Бо́жієй, тобо́ю отображенний, уни́ніє от нас отгоня́єть.","Ра́дуйся, я́ко ті Ма́тері Бо́жия та́йни о Си́ні Своє́м, в се́рдці носи́мия, поведала єси́;","ра́дуйся, я́ко велича́ніє Ма́ти Бо́жієй в Єя́ честь воспіва́єм із твоєго́ Єва́нгелія.","Ра́дуйся, я́ко ті Ма́ти Бо́жия арха́нгельськоє благові́стіє поведала єси́;","ра́дуйся, я́ко Ма́терію Бо́жієй благослове́нний.","Ра́дуйся, святи́й Луко́, Євангели́сте Христо́в і Апо́столе."]},{"h":"Кондак 13","ps":["О, святи́й Євангели́сте і Апо́столе Луко́, трубо́ небе́сная, прийми́ сія́ не́мощная на́ша словеса́ я́ко моли́тву і іспроси́ нам у Бо́га, Го́спода Ісу́са Христа́, Ко́єму ти та́ко неутомимо послужи́л єси́ і вели́кую ми́лость от Него́ стяжа́л єси́, проще́ніє всіх согріше́ній на́ших, ми́рен і безболі́знен коне́ць живота́ і невозбра́нен прехо́д в мир духо́вний, в нем же всі святі́ї воспіва́ють небе́сную піснь: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["Всеми́лостивий Госпо́дь в гріхі́ потопленному ро́ду челові́чеському посла́ Си́на Своєго́, да Он Свої́м живото́м, сме́ртію і сла́вним Воскресе́нієм ізведе́ть сей род із тьми і напра́вить к свя́тости. Чрез теб'я́ же, Євангели́сте святи́й, начертани та́йни не́ба і землі́, даби́ всі челові́ци до конця́ ві́ка путь к той свя́тости вели і, благода́рні су́ще, взивали ті:","Ра́дуйся, Ду́хом Святи́м просвіще́нний на списа́ніє Єва́нгелія;","ра́дуйся, Фео́филу достопочтенному і всім нам би́сер драги́й Єва́нгелія Христо́ва обрі́тший.","Ра́дуйся, я́ко Бо́гом ізбра́н бил єси́, да об'явиши та́йну спасе́нія;","ра́дуйся, благовестителю Благи́я Ві́сти.","Ра́дуйся, я́ко Христа́ прише́дша грі́шния спасти́ проповедавший;","ра́дуйся, я́ко єди́н єси́ от чети́ріх Євангели́стов.","Ра́дуйся, я́ко Дух Святи́й і чрез тебі́ Четвероєва́нгеліє в мир ізлія́л єси́;","ра́дуйся, в та́йни Бо́жії ду́хом воснесийся.","Ра́дуйся, я́ко словеса́ твоя́ просвіти́ша вселе́нную;","ра́дуйся, я́ко мре́жею твоєго́ Єва́нгелія мно́гі слове́сни душі́ улови́вий.","Ра́дуйся, із'яснителю Но́ваго Заві́та;","ра́дуйся, звіздо́, в Це́ркві Небе́сній сія́ющая.","Ра́дуйся, святи́й Луко́, Євангели́сте Христо́в і Апо́столе."]},{"h":"Кондак 1","ps":["Прему́дрим про́мислом Бо́жиїм ізбра́нний, да благовіству́єши сві́тлость Христо́ва Єва́нгелія всему́ ми́ру, Луко́ всеблаже́нне, ве́ліє дерзнове́ніє і́маши пред лице́м Го́спода, Чей земни́й живо́т і уче́ніє списа́л єси́. Іспроси́ і нам, немощни́м і слабим, проще́ніє согріше́ній і утверди́ в нас наде́жду Ца́рствія Небе́снаго, да возмо́жем ті всера́достно взива́ти:","Ра́дуйся, святи́й Луко́, Євангели́сте Христо́в і Апо́столе."]},{"h":"Молитва","ps":["О, святи́й Луко́, Бо́гом ізбра́нний і Ма́терію Бо́жиєю благослове́нний, пропові́дниче по всей вселе́нній Єва́нгелія Христо́ва, му́чениче і Апо́столе, помо́щниче всім моли́твенно призива́ющим тя, помози́ і нам, непотре́бним рабо́м Госпо́днім, я́ко ми по мно́гим прегріше́ніям на́шим обріта́ємся во тьмі і сі́ні сме́ртній, отдале́че от Бо́га отстоя́. Чрез то студо́м посра́мленния не і́мами дерзнове́нія Го́спода моли́ти о проще́нії, призива́єм тя, вели́кий світи́льниче Бо́жий, я́ко пребива́ющаго в непреходя́щем Єго́ сві́те, моли́ о нас Го́спода, да поми́луєть нас.","Умоли́ Го́спода, святи́й Луко́, да обнови́ть в нас страх Госпо́день, о́ньже люби́ привлека́єть, а гріх отгоня́єть. Я́ко ми та́ко нави́кли гріши́ти по всяк день і час, і во сні, я́ко не ві́ми слов Го́спода: бді́те, я́ко не зна́єте часа́, єгда́ хочу́ прийти́, Он же мо́жеть на всяк час призва́ти нас із сего́ привре́меннаго живота́ во ві́чний. Пробуди́ в нас, святи́й Луко́, страх і прему́дрость, о ни́хже святи́й цар і псалмопі́вець Дави́д рече́. Да твої́ми моли́твами получи́м покая́нія сле́зи, і́миже всі на́ші душі́ от гріха́ очи́стяться. Я́ко ми в духо́вной сліпоті́ і дебе́лости су́ще не мо́жем пла́катися своєго́ мертвеця́, си́річ сами́х себі́, мно́гі же сле́зи, пото́ки слез потре́бно да проліє́м за мно́жество соді́янних гріхо́в.","Помози́ нам, неразу́мним, да уразумі́єм Писа́ніє, є́же ти сам списа́л єси́, я́ко і́стинним ра́зумом уразумі́єм і́стинная словеса́, да біжи́м от гріха́, я́ко от огня́, і всі си́ли приложи́м, да прибли́зить ни Бог. Да уразумі́єм, я́ко гріх єсть смерть, Бог же живо́т. Помози́ нам, святи́й Луко́, да то уразумі́вше, очи́стимся от гріха́ і пре́йдем із сме́рті в живо́т. Да бу́деть нам Бог вся во всем. І ни́ні і во ві́ки да пребу́дем близ Него́. Даби́ і нам, я́ко ті с Клео́пою, єгда́ путешествовали во Еммау́с, се́рдце і душа́ тре́петни би́ша от прису́тствія Єго́. Отню́дуже да сни́деть на ни мир небе́сний, к Ца́рствію Небе́сному ни руководящий і ра́достни ни творя́щий, да возмо́жем стрі́ли лука́ваго, на всяк час в нас іспуща́єми, отгна́ти. С тім же получи́м і люби́ Бо́жия, да руководи́ть нас к ві́чному Оте́честву, іді́же всі си́ли небе́сния, всі святі́ї, Ма́ти Бо́жия пред ни́ми, Єя́же благо́й лик в іко́ні тобо́ю напи́санной, увековечен єси́. О́чі серде́ць на́ших да непреста́нно взира́ють на ту лі́поту і є́ю наслажда́ються, да цари́ть в нас Ца́рство Небе́сноє, в ко́є ча́єм моли́твами твої́ми, святи́й Луко́, пресели́тися, єгда́ нас Госпо́дь призове́ть, да та́мо ві́чно сла́вим Бо́га во Святі́й Тро́йці: Безнача́льнаго Отця́, Єдиноро́днаго Си́на і Пресвята́го Ду́ха, во все безконечниє ві́ки. Амі́нь."]},{"h":"Тропар, глас 5","ps":["Апо́стольських дія́ній сказа́теля, / і Єва́нгелія Христо́ва сві́тла списа́теля, / Луку́ препі́таго, сла́вна су́ща Христо́ві Це́ркві, / пі́сньми свяще́нними свята́го апо́стола похва́лим, / я́ко врача́ су́ща, челові́чеськія не́мощі, / єстества́ неду́ги і я́зі душ ісціля́юща, // і моля́щася непреста́нно за ду́ші на́ша."]},{"h":"Кондак, глас 2","ps":["І́стиннаго благоче́стія пропові́дника, / і та́їн неізрече́нних ри́тора, / звізду́ церко́вную, Луку́ Боже́ственнаго восхва́лим: / Сло́во бо єго́ ізбра́ с Па́влом му́дрим, язи́ков учи́теля, // Єди́н ві́дий серде́чная."]},{"h":"Величання","ps":["Велича́єм тя, апо́столе Христо́в і Євангели́сте Луко́, і чтим болі́зні і труди́ твоя́, ї́миже труди́лся єси́ во благові́стії Христо́ві."]}],"notes":[]},{"u":"Акафіст праведному Філарету Милостивому","e":"Akathist to the Righteous Philaret the Merciful","secs":[{"h":"Кондак 1","ps":["Возбра́нний чудотво́рче і преди́вний уго́дниче Христо́во Філаре́те! Похва́льная прино́сим ті, Авраа́млева страннолю́бія усе́рдний подража́телю, ти бо о лю́діх милосе́рдствуя, рука́ма неіму́щих, Бо́гу взаї́м дая́ти возлюби́л єси́, ті́мже ті, любо́вію Бо́жиєю обогати́вшемуся і дерзнове́ніє к Нему́ стяжа́вшему, припа́дающе, мо́лимся: не оста́ви і нас, к тебі́ в ну́ждах прибіга́ющих і со умиле́нієм зову́щих:","Ра́дуйся, Філаре́те Ми́лостивий, житіє́м свої́м Це́рков Христо́ву украша́ющий."]},{"h":"Ікос 1","ps":["А́нгелом ра́дованіє і челові́ком весе́ліє бисть житіє́ твоє́, Філаре́те Ми́лостивий. Ти бо пра́отцю Авраа́му во ві́рі, І́ову же в терпі́нії послі́дуя, я́ко оте́ць чадолюби́вий: а́лчущих пита́я, стра́нних же с ра́достію приє́мля, любе́зно тіх упокоєва́л, і та́ко дом твой прибі́жище ра́дованія соді́лал єси́. Си́це, ви́дяще тя во́лю Бо́жию в діла́х Милосе́рдія творя́ща, прино́сим ті такови́я похвали́:","Ра́дуйся, страни́ Пафлаго́нськия світи́льниче світоза́рний;","ра́дуйся, человіколю́бія о́бразе пресла́вний.","Ра́дуйся, ти бо в житії́ твоє́м всім се́рдцем Бо́га возлюби́вий;","ра́дуйся, горі́нієм любві́ к Нему́ бога́тство доброді́телей му́дре расточи́вий.","Ра́дуйся, ти бо, милосе́рдієм распаля́єм, благода́ть Ду́ха Свята́го оби́льно стяжа́вий;","ра́дуйся, в любві́ Бо́жієй богаті́я, нікогда́же обнища́вий.","Ра́дуйся, Філаре́те Ми́лостивий, житіє́м свої́м Це́рков Христо́ву украша́ющий."]},{"h":"Кондак 2","ps":["Ви́дяще тя бли́жнії і да́льнії, сострада́нієм распаля́єма, і служе́ніє лю́дем а́ки Самому́ Го́споду усе́рдно творя́ща, в ну́ждах і печа́ліх к тебі́ притека́ху, їх же ти єле́єм милосе́рдія во і́м'я Христо́во утіша́л єси́. Ми же, милосе́рдіє твоє́, ра́зум челові́чеський превосходя́щеє зря́ще, вопіє́м о тебі́ Всеще́дрому Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум Прему́драго воі́стину стяжа́л єси́, всеблаже́нне Філаре́те, я́ко блага́я і зла́я, живо́т і смерть, нищета́ і бога́тство от Го́спода суть, сего́ ра́ди словеса́ Госпо́дня: «Поне́же сотвори́сте єди́ному із бра́тій мої́х ме́ньших, Мні сотвори́сте» – па́че ме́да і со́та се́рдцю твоєму́ би́ша. Си́це тебі́ о такови́х милосе́рдующа, прино́сим похва́льная сія́:","Ра́дуйся, Боже́ственнаго ра́зума преди́вноє вмісти́лище;","ра́дуйся, благоутро́бія Бо́жия всеусе́рднійший пропові́дниче.","Ра́дуйся, єле́й милосе́рдія нікогда́же в дому́ твоє́м істощи́ся;","ра́дуйся, я́ко же в Саре́пті Сидо́нськой, му́ка доброді́телі твоєя́ ніколи́же ума́лися.","Ра́дуйся, боголюби́вих душ ще́дроє увеселе́ніє;","ра́дуйся, в ско́рбіх унива́ющих благода́тноє укріпле́ніє.","Ра́дуйся, Філаре́те Ми́лостивий, житіє́м свої́м Це́рков Христо́ву украша́ющий."]},{"h":"Кондак 3","ps":["Си́лою Ду́ха Свята́го, Єго́ же стяжа́ душа́ твоя́, не поколеба́ся дух твой, блаже́нне Філаре́те, єгда́ Человіколю́бець Бог, я́коже іногда́ на уго́дника своєго́ І́ова, попусти́ на тя по́лчища Ісма́їльтян, огне́м і мече́м опустоши́вших се́ла же, і ни́ви, і вертогра́ди твоя́, і поби́ша домоча́дці твоя́, даби́ іспита́ти незло́біє душі́ твоєя́. Ти же, вся сія́ со смире́нієм прия́л єси́, уста́ми пра́веднаго І́ова благословля́яй Бо́га: наг ізидо́х із чре́ва ма́тере моєя́, наг і оти́ду, Госпо́дь даде́ – Госпо́дь от'я́т, – велегла́сно поя́ Єму́: Аллилу́я."]},{"h":"Ікос 3","ps":["В Бо́зі, упова́ніє імі́яй, в нищеті́ і напа́стіх су́ще, не поскорбе́л, ніже́ согріши́л єси́ уста́ми твої́ми пред лице́м Всеви́шняго, всеблаже́нне, но я́коже о мно́гом бога́тстві, о нищеті́ своє́й веселя́ся, по сло́ву бо Госпо́дню: в по́ті лиця́ яди́й хліб твой, єго́ же, я́ко ізби́точествующий, с нищелю́бці разділя́л єси́. Ублажа́я таково́є упова́ніє твоє́ со умиле́нієм вопіє́м ті:","Ра́дуйся, се́рдця твоєго́ земни́м сокро́вищем не приложи́вий;","ра́дуйся, такови́м бо бли́жнім твої́м со благогові́нієм послужи́вий.","Ра́дуйся, ми́лостиней а́ки ми́ро многоце́нноє в це́ркві Христо́вой благоуха́ющий;","ра́дуйся, вдов і сиро́т, і неіму́щих хлі́бом жи́зні пита́ющий.","Ра́дуйся, благоче́стія сто́лпе непоколеби́мий, небе́с досязу́ющий;","ра́дуйся, доброді́тельми твої́ми а́нгельськи любо́в Бо́жию воспіва́ющий.","Ра́дуйся, Філаре́те Ми́лостивий, житіє́м свої́м Це́рков Христо́ву украша́ющий."]},{"h":"Кондак 4","ps":["Бу́рею іспита́ній і укоре́нієм от бли́жніх свої́х не поколеба́лся єси́, боголюби́ве Філаре́те, єгда́ же узрі́л єси́ земледі́льця убо́га в біді́ су́ща, супру́г воло́в єди́них в дому́ твоє́м би́вших, сему́ отда́л єси́, єва́нгельськи убежда́я жену́ і чад свої́х воззрі́ти на птиць небе́сних, я́ко не сі́ють, не жнуть, не собира́ють в жи́тници, і Оте́ць Небе́сний пита́єть їх. Та́ко сих утіша́юще, Бо́гу воспіва́л єси́: Аллилу́я."]},{"h":"Ікос 4","ps":["Ви́дяще тя боголюби́вий друг твой в нищету́ впа́дше, умилосе́рдися, і дово́льно пшени́ци посла́ ті, да дом свой препита́єши, достоблаже́нне Філаре́те. Ти же сія́, а́ки от рук Бо́жиїх прия́л єси́, і домоча́дці, і сосі́ди своя́, і неіму́щую бра́тію одели́л єси́. Лю́діє же Бо́жії, зря́ще тя милосе́рдієм ізби́точествующе, ублажа́ше тя похвали́ такови́ми:","Ра́дуйся, це́ркве дома́шнія благода́тноє утвержде́ніє;","ра́дуйся, земледі́льцев в ді́ланії ще́дроє благослове́ніє.","Ра́дуйся, а́лчущим і жа́ждущим благи́й хлебода́телю;","ра́дуйся, в біда́х і печа́ліх су́щим ско́рий предста́телю.","Ра́дуйся, незло́бія преізря́дний рачи́телю;","ра́дуйся, добротолю́бія смиренному́дрий учи́телю.","Ра́дуйся, Філаре́те Ми́лостивий, житіє́м свої́м Це́рков Христо́ву украша́ющий."]},{"h":"Кондак 5","ps":["Медото́чней струє́ уподо́бился єси́, богоблаже́нне Філаре́те, єгда́ хлі́ба насу́щна не бі в хра́мині твоє́й, оба́че, ни́щу прише́дшу в дом твой, да сего́ не пре́зриши, ніже́ тща отпу́стиши, от пчел мед от'я́л єси́, і та́ко ду́шу раба́ Христо́ва увесели́л єси́. Ми же, милосе́рдія сего́ в житії́ на́шем не стяжа́вше, но я́же даде́ нам Госпо́дь, безу́мно расточа́юще, ка́ко принесе́м похва́льная ми́лующему нас Бо́гу, а́ще не о тебі́ возопіє́м Єму́: Аллилу́я."]},{"h":"Ікос 5","ps":["Сли́шаще і ви́дяще я́ко ми́лость і і́стина сріто́стіся, пра́вда же і мир в діла́х твої́х облобиза́стася, кто не ублажи́ть по́двиги твоя́, воі́стину Ми́лостивий Філаре́те, іли́ кто не удиви́ться нищелю́бію твоєму́ – ти бо, в кра́йній нищеті́ су́ще: на Бо́га упова́ніє імі́я, псало́мськи іспові́дал єси́: А́ще пойду́ посреді́ ско́рби, Госпо́дь живи́ть м'я, і спасе́ть м'я десни́ця Єго́. К стяжа́нію богому́дрія сего́ подви́гни і нас, взива́ющих ті такова́я:","Ра́дуйся, пла́мене ві́ри боже́ственнаго горі́нія;","ра́дуйся, фимія́ме благово́ннаго пред Бо́гом куре́нія.","Ра́дуйся, кла́дязе милосе́рдія неісчерпа́ємаго;","ра́дуйся, страннопри́їмче черто́га незатворя́ємаго.","Ра́дуйся, пра́ведному І́ову усе́рдний подража́телю;","ра́дуйся, дру́же Христо́в, і о нас пред Ним ві́рний предста́телю.","Ра́дуйся, Філаре́те Ми́лостивий, житіє́м свої́м Це́рков Христо́ву украша́ющий."]},{"h":"Кондак 6","ps":["Пропові́дник милосе́рдія і человіколю́бія Христо́ва яви́лся єси́ благонра́вним житіє́м твої́м, свя́те Філаре́те, і та́ко іна́го Авраа́ма показа́ тя ми́рові Бог. Сего́ ра́ди призрі́ Госпо́дь на смире́ніє твоє́ і от нищети́ кра́йнія к ро́ду ца́рственному вознесе́ наслі́діє твоє́, да у́зриши си́ни і дще́рі ро́да твоєго́, я́ко новосажде́нія ма́сличная, о́крест трапе́зи твоєя́ вся дні живота́ твоєго́, да і ми о тебі́ позна́єм ка́ко пече́ться Госпо́дь о упова́ющих на Него́, і с любо́вію возопіє́м Єму́: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́, я́ко світи́ло лучеза́рноє горі́нієм любве́ твоєя́ ко Го́споду, і на ка́мене ві́ри утверди́ся се́рдце твоє́, прему́дрий ді́лателю виногра́да Христо́ва і, я́ко крин многоцве́тний, по́двигом ві́ри процві́л єси́ со ча́ди твої́ми, їх же долготерпі́нієм твої́м упова́ти на Бо́га науча́л єси́. Они́ же, уразумі́ша гріх ропта́нія своєго́ і, сокруша́яся се́рдцем, благословля́ху Бо́га, сотво́ршаго ми́лость. С ни́ми же і ми к тебі́ припа́даєм і уми́льно взива́єм:","Ра́дуйся, брак честни́й і житіє́ нескве́рноє уго́дная пред Бо́гом сотвори́вий;","ра́дуйся, це́рков дома́шнюю на ка́мене ві́ри богому́дренно утверди́вий.","Ра́дуйся, супру́жеськой ві́рности тве́рдоє охране́ніє;","ра́дуйся, в по́двигі сем ізнемога́ющих благода́тноє укріпле́ніє.","Ра́дуйся, ю́ним супру́гом о́браз христия́нськаго житія́ до́брі показу́ющий;","ра́дуйся, моли́твою пред Бо́гом в ну́ждах їх споспешеству́ющий.","Ра́дуйся, Філаре́те Ми́лостивий, житіє́м свої́м Це́рков Христо́ву украша́ющий."]},{"h":"Кондак 7","ps":["Хотя́ще возда́ти благодаре́ніє Бо́гу, за я́же дарова́ ті неізрече́нная блага́я, рекл єси́ жені́ со ча́ди твої́ми: сотвори́м у́бо пир і умо́лим Царя́ на́шего со вельмо́жами прийти́ к нам. Би́вшу сему́ і́ми угото́вану, поте́кл єси́, всеблаже́нне, на сто́гни гра́да і распу́тія, і єли́ка обрі́л єси́ ни́щих, і сліпи́х і хроми́х, і разсла́бленних, в дому́ твоє́м ца́рськую трапе́зу угото́вал єси́, і і́мже с домоча́дці свої́ми, я́ко Царю́ царе́й, послужи́л єси́. С ни́ми же, я́ко со дру́ги Христо́ви, науча́єши і нас взива́ти в Тро́йці піва́ємому Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́ваго світи́льника, в ді́ліх милосе́рдая просія́вшаго, обрі́те тя Це́рков Христо́ва, ми́лостиве Філаре́те, поне́же не приліпи́ся се́рдце твоє́ сокро́вищем земни́м, ніже́ ца́рським ми́лостиням і щедро́там, їх же нівочто́же вміня́л єси́, і вся я́же тебі́ приноша́ху, убо́гим і стра́ждущим оби́льно расточа́л єси́. Внемли́ же і нам, о всеблаже́нне, да твої́ми моли́твами душе́внаго і тіле́снаго вре́да ізба́вльшеся, щедролю́бієм твої́м уязві́мся, принося́ще тебі́ сія́ похвали́:","Ра́дуйся, отце́м і пра́отцем на́шим во ві́рі подража́телю;","ра́дуйся, сокро́вищ Небе́сних прему́дрий стяжа́телю.","Ра́дуйся, благонра́вієм твої́м цілому́дрію і стра́ху Бо́жию нас науча́єши;","ра́дуйся, болі́знующих жестокосе́рдієм щедролю́бієм ісціля́єши.","Ра́дуйся, па́че ца́рських по́честей нищету́ Христо́ву возлюби́вий;","ра́дуйся, Ца́рствія Христо́ва па́че земни́х кра́сних іска́ти нас научи́вий.","Ра́дуйся, Філаре́те Ми́лостивий, житіє́м свої́м Це́рков Христо́ву украша́ющий."]},{"h":"Кондак 8","ps":["Стра́нно і пресла́вно бисть житіє́ твоє́, преблаже́не Філаре́те, во є́же диви́тися мно́зім, ка́ко у́бо ца́рськими почестьми́ почте́нну ті су́щу, нищету́ духо́вную па́че бога́тства ми́ра сего́ возлюби́в, в пості́ і моли́тві бога́тство некра́домоє душе́ твоє́й стяжа́л єси́. Кто у́бо возмо́жеть ізрещи́ болі́зні і боре́нія твоя́, я́же Христа́ ра́ди претерпі́л єси́, а́ще боже́ственной любо́вію не возгори́ться, во є́же чи́стим се́рдцем непреста́нно взива́ти ко Го́споду: Ти єси́ упова́ніє моє́, часть моя́ єси́ на землі́ живи́х, Аллилу́я."]},{"h":"Ікос 8","ps":["Весь бі во ви́шніх, пра́ведне Філаре́те, єгда́ Ду́хом Святи́м возвісти́ся ті житія́ твоєго́ сконча́ніє і, я́коже дре́вле Патріа́рх Іа́ков, призва́л єси́ ча́ди твоя́ і ча́ди чад твої́х, їм же, проро́чеськи, вся, я́же і́мать во́лею Бо́жиєю соверши́тися, предвозвісти́л єси́. І, та́ко їх благословля́я, я́ко со́лнце лице́м твої́м просія́л, і псало́мськи к Бо́гу воззва́л єси́: Ми́лость і суд воспою́ Тебі́, Го́споди, когда́ приі́деши ко мні; і, си́це моля́щуся, дух твой в ру́ці Бо́жії преда́л єси́. Они́, сокруша́ющеся, рида́ньми вопія́ху:","Ра́дуйся, о́тче ми́лостивий і кро́ткий, любве́ Христо́вой нас науча́ющий;","ра́дуйся, гряду́щая я́ко настоя́щая нам сказу́ющий.","Ра́дуйся, тріє́ вну́ки твоя́ на по́двиг і́ночеський проро́чеськи благослови́вий;","ра́дуйся, послуша́нію, цілому́дрію і нищеті́ Христо́вой їх научи́вий.","Ра́дуйся, сострада́нієм і нищелю́бієм премно́го Бо́гу угоди́вий;","ра́дуйся, ми́лостинею Ца́рствіє Бо́жиє унаслі́дивий.","Ра́дуйся, Філаре́те Ми́лостивий, житіє́м свої́м Це́рков Христо́ву украша́ющий."]},{"h":"Кондак 9","ps":["Вся́ко колі́но земни́х: ца́ріє і вельмо́жи, стра́нници і убо́зії, от градо́в і ве́сей, я́ко мра́вія ко гро́бу твоєму́ стека́шася, блаже́нне Філаре́те, друг дру́га тесня́ще і со слеза́ми взива́ху: О, Го́споди Бо́же наш! Почто́ лиши́л єси́ нас отця́ і пита́теля на́шего? Кто ни́ні а́лчущих напита́єть, наги́х оді́єть, стра́нних в дом свой введе́ть? Кто же уме́ршую і на сто́гнах пове́ржену бра́тію на́шу гро́бу преда́сть? Ми же содрога́ємся се́рдцем і душе́ю, я́ко нічто́же бла́го такови́м сотвори́хом, да вопіє́м с ни́ми хвале́бную піснь Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Ві́тіії многовіща́ннії недоуміва́ють: ки́їми словеси́ восхвали́ти по достоя́нію в супру́жеськом по́двигі непоро́чноє Бо́гу служе́ніє твоє́, боголюби́ве Філаре́те, ніже́ іспові́сть вся пресла́вная чудеса́ твоя́, і́ми і по сме́рті в ско́рбіх к тебі́ притека́вших утіша́л єси́. Си́це бо челові́к от ду́ха зла́го многолі́тні стра́ждущий, єгда́ ко гро́бу твоєму́ пове́ржеся, от ко́зней сего́ мучи́тельних свободи́ся, хвалу́ ве́лію Бо́гу воздаде́. Наро́д же, чудесе́ сего́ свиді́тель бив, благословля́я Бо́га, со стра́хом і умиле́нієм принесе́ тебі́ такова́я:","Ра́дуйся, я́коже Архистрати́г Бо́жий сатану́ до́лу низри́нувий;","ра́дуйся, милосе́рдієм твої́м ло́на Авраа́мова дости́гнувий.","Ра́дуйся, Небе́снаго Домовлади́ки ра́бе благи́й і ві́рний;","ра́дуйся, моли́твенниче о нас у Престо́ла Бо́жия непости́дний.","Ра́дуйся, за любо́в твою́ святу́ю любве́ Царя́ Небе́снаго сподо́бивийся;","ра́дуйся, єва́нгельськи на землі́ потруди́вийся, сожи́тельства а́нгелом удосто́ївийся.","Ра́дуйся, Філаре́те Ми́лостивий, житіє́м свої́м Це́рков Христо́ву украша́ющий."]},{"h":"Кондак 10","ps":["Спаси́тельнаго приста́нища і сла́дости ра́йськия пресла́вно дости́гл єси́ смиренному́дрієм твої́м, достохва́льне Філаре́те, і реку́ о́гненную, нече́стіє попаля́ющую, невреди́мо преше́л єси́, іді́же со ізбра́нними Бо́жиїми даде́ся ті віне́ць сла́ви неув'яда́ємия, в ней бо тя муж пра́ведний узрі́, і от А́нгела Госпо́дня усли́ша: се Филаре́ть Амні́йський єсть, і́же премно́гою своє́ю к ни́щим любо́вію, ми́лостію і чи́стим свої́м житіє́м, втори́м Авраа́м бисть. Та́ко, ви́дяще тя в Бо́зі ликовству́юща, смире́нно і ми вопіє́м: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ і наде́жноє прибі́жище єси́, ми́лостиве Філаре́те, всім к заступле́нію твоєму́ притека́ющих, о них же я́ко о ча́діх свої́х пред Бо́гом в моли́тві хода́тайствуєши. Тім же і нам, к тебі́ с любо́вію припа́дающих, і твоєго́ заступле́нія пред Бо́гом прося́щих, бу́ди стіна́ і огражде́ніє непреодоли́моє, і от всіх ко́зней вра́жиїх ізбавле́ніє непреобори́моє, да твої́ми моли́твами приста́нища ра́йськаго дости́гнем і, в Бо́зі веселя́щеся, вопіє́м ті ра́достно:","Ра́дуйся, от богоми́слія к богові́дінію сла́вно возви́сивийся;","ра́дуйся, о Бо́зі му́дрствуя, лі́потою безсме́ртія украси́вийся.","Ра́дуйся, о ни́щих печа́ляся, у врат до́му твоєго́ у́треневавий;","ра́дуйся, та́ко у́тренююще, любо́в Бо́жию стяжа́вий.","Ра́дуйся, христия́нськаго благоче́стія ди́вний глаша́таю;","ра́дуйся, ми́лостивий о нас пред Бо́гом хода́таю.","Ра́дуйся, Філаре́те Ми́лостивий, житіє́м свої́м Це́рков Христо́ву украша́ющий."]},{"h":"Кондак 11","ps":["Пі́ніє всехва́льноє прино́сим ті, досточу́дне Філаре́те, і псало́мськи вопіє́м: Блаже́н муж, боя́йся Го́спода, в за́повідіх Єго́ восхо́щеть зіло́. Расточи́, даде́ убо́гим: пра́вда єго́ пребива́єть во вік. Та́ко, о всеблаже́нне, житіє́м твої́м показа́л єси́, я́ко мона́си і мирсті́ї, свяще́нници і вельмо́жи, бога́тії і убо́зії зва́ни суть вни́ти в ра́дость Го́спода своєго́, а́ще уразумі́ють я́ко у Го́спода ми́лость, і мно́гоє у Него́ ізбавле́ніє, і в ді́ліх благи́х восхва́лять Трисвято́є і́м'я Єго́: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоно́сним служи́телем милосе́рдія і человіколю́бія предста́л єси́ престо́лу Всеви́шняго Влади́ки і Го́спода Сил, всеблаже́нне Філаре́те, отону́дуже Боже́ственними луча́ми Трисо́лнечнаго Сві́та осіява́єши нас, во тьмі гріхо́вній блужда́ющих, на сві́тлую стезю́ покая́нія і доброде́ланія наставля́єши: не скрива́ти себі́ сокро́вищ на землі́, іді́же черв і тля тлить, і іді́же та́тіє подко́пивають і кра́дуть. Ми же, сла́дкоє сіє́ Христо́во віща́ніє в послуша́ніє приє́млюще, с ра́достію зове́м ті:","Ра́дуйся, колесни́цею доброді́телей от земни́х к небе́сним восхо́д сотвори́вий;","ра́дуйся, вся ко́зні вра́жия милосе́рдієм к лю́дем посрами́вий.","Ра́дуйся, святи́я Це́ркве похвало́ і украше́ніє;","ра́дуйся, среди́ собла́знов ми́ра сего́, непоро́чноє Бо́гу в супру́жестві служе́ніє.","Ра́дуйся, о спасе́нії твоє́м Небе́снії Ли́ки ра́дуються;","ра́дуйся, о і́мені твоє́м всі земноро́днії, веселя́щеся хва́ляться.","Ра́дуйся, Філаре́те Ми́лостивий, житіє́м свої́м Це́рков Христо́ву украша́ющий."]},{"h":"Кондак 12","ps":["Благода́ть Бо́жию оби́льно прия́л єси́, пра́ведне Філаре́те, є́юже укріпи́ся се́рдце твоє́ в любві́ ко Христу́ Бо́гу, си́це бо, долготерпі́нієм і ві́рою просія́в, от земна́го твоєго́ житія́ в Небе́сная селе́нія со А́нгельськими ли́ки водвори́лся, милосе́рдія Бо́жия пропові́дник преізря́ден яви́лся єси́. Єму́ же, со дерзнове́нієм предстоя́, мо́лимся те́плі: благода́тію Свята́го Ду́ха окропи́ти сердця́ на́ша, да твоєго́ житія́ подража́телі бу́дем, ко ісполне́нію за́повідей Христо́вих усе́рдно потщі́мся, вопію́ще Єму́: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще неізрече́нния доброді́телі твоя́, ї́хже ра́ди подража́тель Христо́ва благосе́рдія бил єси́, і я́ко крин неув'яда́ємий посреді́ земноро́дних красото́ю ума́ твоєго́ процві́л, ми́лостиве Філаре́те, черто́га Небе́снаго зрі́ти і воспіва́ти сла́ву Бо́жию удосто́їлся єси́. Сицева́го блаже́нства іспроси́ і нам, чту́щим ві́рою і любо́вію пресві́тлую па́м'ять твою́, да твої́м хода́тайством усли́шим Боже́ственний глас Гряду́щаго суди́ти живи́м і ме́ртвим: Прийді́те благослове́ннії Отця́ Моєго́, наслі́дуйте угото́ванноє вам Ца́рствіє от сложе́нія ми́ра, да благода́рні зове́м ті:","Ра́дуйся, висото́ю ума́ твоєго́ скороги́бнущеє ми́ра сего́ позна́вий;","ра́дуйся, чистото́ю се́рдця твоєго́ любо́в Христо́ву стяжа́вий.","Ра́дуйся, доброді́тельми твої́ми на пир А́гнця Бо́жия нас призива́ющий;","ра́дуйся, моли́твами твої́ми две́рі Ца́рствія Христо́ва нам отверза́ющий.","Ра́дуйся, трубо́ а́нгельськая, воздая́ніє Бо́жиє глася́щая;","ра́дуйся, люби́ неізрече́нная, чрез реку́ о́гненную в черто́г Небе́сний ві́рних вводя́щая.","Ра́дуйся, Філаре́те Ми́лостивий, житіє́м свої́м Це́рков Христо́ву украша́ющий."]},{"h":"Кондак 13","ps":["О, преблаги́й уго́дниче Бо́жий, Філаре́те Ми́лостивий! Прийми́ от нас убо́гоє ві́ри і долготерпі́нія твоєго́ восхвале́ніє і, я́ко імі́яй дерзнове́ніє ко Го́споду і о лю́діх сострада́ніє, іспроси́ у Человіколюби́ваго Бо́га Це́ркве Христо́вой благостоя́ніє непоколеби́моє, нам же, ві́ри благочести́вия утвержде́ніє, наде́жди нело́жноє упова́ніє і братолю́біє нелицемі́рноє, да не ума́литься пра́вда Бо́жія в ді́ліх на́ших, ніже́ постиді́мся пред отці́ і пра́отці на́шими, єгда́ поє́м Бо́гу, Трисвяту́ю піснь: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелом ра́дованіє і челові́ком весе́ліє бисть житіє́ твоє́, Філаре́те Ми́лостивий. Ти бо пра́отцю Авраа́му во ві́рі, І́ову же в терпі́нії послі́дуя, я́ко оте́ць чадолюби́вий: а́лчущих пита́я, стра́нних же с ра́достію приє́мля, любе́зно тіх упокоєва́л, і та́ко дом твой прибі́жище ра́дованія соді́лал єси́. Си́це, ви́дяще тя во́лю Бо́жию в діла́х Милосе́рдія творя́ща, прино́сим ті такови́я похвали́:","Ра́дуйся, страни́ Пафлаго́нськия світи́льниче світоза́рний;","ра́дуйся, человіколю́бія о́бразе пресла́вний.","Ра́дуйся, ти бо в житії́ твоє́м всім се́рдцем Бо́га возлюби́вий;","ра́дуйся, горі́нієм любві́ к Нему́ бога́тство доброді́телей му́дре расточи́вий.","Ра́дуйся, ти бо, милосе́рдієм распаля́єм, благода́ть Ду́ха Свята́го оби́льно стяжа́вий;","ра́дуйся, в любві́ Бо́жієй богаті́я, нікогда́же обнища́вий.","Ра́дуйся, Філаре́те Ми́лостивий, житіє́м свої́м Це́рков Христо́ву украша́ющий."]},{"h":"Кондак 1","ps":["Возбра́нний чудотво́рче і преди́вний уго́дниче Христо́во Філаре́те! Похва́льная прино́сим ті, Авраа́млева страннолю́бія усе́рдний подража́телю, ти бо о лю́діх милосе́рдствуя, рука́ма неіму́щих, Бо́гу взаї́м дая́ти возлюби́л єси́, ті́мже ті, любо́вію Бо́жиєю обогати́вшемуся і дерзнове́ніє к Нему́ стяжа́вшему, припа́дающе, мо́лимся: не оста́ви і нас, к тебі́ в ну́ждах прибіга́ющих і со умиле́нієм зову́щих:","Ра́дуйся, Філаре́те Ми́лостивий, житіє́м свої́м Це́рков Христо́ву украша́ющий."]},{"h":"Молитва","ps":["О, преди́вні ізбра́нниче Бо́жий, Філаре́те Ми́лостивий! Амні́ї преще́дрий хлебода́телю, Правосла́вія світи́льниче, Го́спода Бо́га ра́бе благи́й і ві́рний! Ти бо всім се́рдцем єва́нгельськи Христу́ послі́довавий і да́нний тебі́ тала́нт прему́дре умно́живий: си́рих і убо́гих оді́явий і напита́вий; стра́нних і ни́щих в дом свой введи́й, в ско́рбіх і печа́ліх су́щих уті́шивий, уме́рших і на сто́гнах пове́рженних гро́бу преда́вий; всім вся́чеськи послужи́вий, і та́ко ві́ру свою́ в діла́х показа́л єси́. Єй, святи́й уго́дниче Бо́жий, не пре́зри нас, печа́льми жите́йськими ізнива́ємих і страстьми́ гріхо́вними обурева́ємих. Во вся дні уни́ніє і малоду́шіє коле́блють на́шу ві́ру, жестокосе́рдіє і озлобле́ніє сніда́ють сердця́ на́ша і охлажда́ють любо́в на́шу; честолю́біє же і нетерпі́ніє растліва́ють ду́ші на́ша, і та́ко, а́ки ни́щії, в діла́х благи́х обнища́хом. Ти же, О́тче пра́ведний, милосе́рдствуя о нас, умоли́ Христа́ Бо́га, да обогати́ть сердця́ на́ша Ду́хом Свої́м Святи́м, ісціли́ть душе́вния і тіле́сния неду́ги на́ша, і, а́ки ни́ву жа́ждущую, напоі́ть нас щедро́тами человіколю́бія Своєго́; да ві́рі, долготерпі́нію і милосе́рдію твоєму́ подража́юще, во благоче́стії і чистоті́ поживе́м вся дні живота́ на́шего. Єще́ мо́лим тя, преблаже́нне, єгда́ приспі́єть житія́ на́шего отше́ствіє, к покая́нію нелицемі́рному нас подви́гни, да Христу́ Спаси́телю на́шему чрез святи́я Єго́ Та́їнства приобщі́мся і наслі́дники Ца́рствія Небе́снаго бу́дем, іді́же в ра́дості святи́х і А́нгелов сподо́бимся і ми покланя́тися і воспіва́ти Трисвято́є І́м'я: Отця́, і Си́на, і Свята́го Ду́ха, во ві́ки віко́в. Амі́нь!"]},{"h":"Тропар, глас 4","ps":["Авраа́му во ві́рі подража́я, / І́ову же в терпі́нії послі́дуя, / о́тче Філаре́те, / блага́я землі́ разділя́л єси́ неіму́щим / і лише́ніє сих терпі́л єси́ му́жественні. / Сего́ ра́ди сві́тлим тя вінце́м увінча́ Подвигополо́жник, Христо́с Бог наш, // Єго́же моли́ спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 3","ps":["І́стинно всеізря́дная твоя́ ку́пля зри́ться / і му́дрою би́ти су́диться всі́ми благому́дрствующими: / отда́л бо єси́ до́льняя і кратковре́менная, взиску́я Го́рних і ві́чних. // Ті́мже і досто́йно стяжа́л єси́ ві́чную сла́ву, ми́лостиве Філаре́те."]},{"h":"Величання","ps":["Велича́єм тя, / святи́й пра́ведний Філаре́те, / і чтим святу́ю па́м'ять твою́, / ти бо мо́лиши за нас // Христа́, Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст благовірному князю Михаїлу, Тверському чудотворцю","e":"Akathist to the Right-Believing Prince Michael of Tver, the Wonderworker","secs":[{"h":"Кондак 1","ps":["Ізбра́нний Бо́гом із земни́х князе́й в небе́сноє пресві́тлоє му́ченичеськоє во́їнство, от земни́я сея́ юдо́лі в Ца́рство Небе́сноє пресели́лся єси́: положи́л бо єси́ ду́шу твою́ за лю́ди твоя́. Ті́мже, я́ко імі́яй дерзнове́ніє ко Го́споду, моли́ за держа́ву Россі́йськую, за град твой і лю́ди, тебі́ зову́щия:","Ра́дуйся, благові́рний кня́же Михаї́ле, Тверськи́й пресла́вний чудотво́рче."]},{"h":"Ікос 1","ps":["А́нгелов і всея́ тва́рі Созда́тель, ангелонравна тя прови́дів і воітеля за Христа́ непобіди́ма, архистрати́гу небе́сних во́їнств тезоіме́нне тебі́ нарещи́ся благоустро́ї. Ті́мже сла́в'яще Бо́жиє о тебі́ промишле́ніє, я́ко ізбра́нну сосу́ду Христо́ви благода́ті, вопіє́м ті:","Ра́дуйся, равноапо́стольнаго Влади́мира благослове́нная о́трасле;","Ра́дуйся, благові́рних і благочести́вих Яросла́ва і Ксе́нії ча́до.","Ра́дуйся, я́ко во утро́бі ма́тере осиротев, всіх Бо́га во отця́ мі́сто обрі́л єси́;","Ра́дуйся, я́ко под кро́вом крил Єго́ прему́дростію і во́зрастом преспіва́л єси́.","Ра́дуйся, я́ко отроча́ доброумно і благонра́вно бил єси́;","Ра́дуйся, я́ко от ю́ности твоєя́ па́че вся́каго сокро́вища Христа́ возлюби́л єси́.","Ра́дуйся, я́ко от Бо́га і челові́к досто́йні возлю́блен бил єси́;","Ра́дуйся, благові́рний кня́же Михаї́ле, Тверськи́й пресла́вний чудотво́рче."]},{"h":"Кондак 2","ps":["Ви́дівши тя благові́рная ма́тер твоя́ Ксе́нія, я́ко А́нна Самуї́ла, преспіва́юща во́зрастом і прему́дростію, стра́хом Бо́жиїм і всі́ми доброді́тельми украша́єма, ра́довашеся о тебі́, благода́рно поя́ прему́дрости наста́внику і сми́сла пода́телю Бо́гу: Аллилуя."]},{"h":"Ікос 2","ps":["Ра́зум богому́дрий імі́я, я́ко Соломо́н, всім се́рдцем возлюби́л єси́, блаже́нне, прему́дрость Бо́жию, ю́же і поіска́л єси́ прилі́жно от ю́ности твоєя́; ті́мже от Бо́га дарова́ніє приє́м, храмозданієм Царю́ прему́дрому поревнова́л єси́. Сего́ ра́ди сла́в'яще, зове́м ті:","Ра́дуйся, я́ко храм прекра́сен Преображе́нія Госпо́дня воздви́гл єси́;","Ра́дуйся, я́ко от імі́ній твої́х ще́дро о́ний украси́л єси́.","Ра́дуйся, я́ко всім се́рдцем благолі́піє до́му Бо́жия возлюби́л єси́;","Ра́дуйся, я́ко пребива́ти в нем па́че всіх утех мирськи́х ізво́лил єси́.","Ра́дуйся, я́ко і сам храм Бо́жий живи́й, духо́вний бил єси́;","Ра́дуйся, моли́тви бо твоя́, я́ко кади́ло благово́нноє, Бо́гу прине́сл єси́.","Ра́дуйся, зане́ усе́рдіє моли́тв і діл твої́х, я́ко всесожже́ніє ту́чноє і же́ртву непоро́чную, прия́т Госпо́дь;","Ра́дуйся, я́ко і ни́ні па́че зла́та многоці́ннаго святи́я мо́щі твоя́ украша́ють це́рков сію́.","Ра́дуйся, благові́рний кня́же Михаї́ле, Тверськи́й пресла́вний чудотво́рче."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго осіни́ тя, і Дух Бо́жий ноша́шеся над тобо́ю, я́коже над Дави́дом, єгда́ возведе́ тя Госпо́дь на прароди́тельний престо́л вели́ким князе́м сла́внаго гра́да Влади́мира. Ті́мже священнонача́льници і кня́зі, і всі лю́діє согла́сно ра́довахуся, благодаря́ще Бо́га, вознося́щаго смире́нния Своя́, і пою́ще Єму́: Аллилуя."]},{"h":"Ікос 3","ps":["Імі́я ду́шу боголюби́ву і се́рдце ми́лостиво, єгда́ власть прия́л єси́ великокняжую, не ізміни́л єси́ нра́ва твоєго́ смиренному́драго і любвеобильнаго: потща́лся бо єси́ вся́ку сле́зу от'яти от лиця́ стра́ждущих і бил єси́ всім в ну́ждах помо́щник. Ті́мже не оста́ви і нас, наді́ющихся на тя і вопію́щих такова́я:","Ра́дуйся, святи́телей і свяще́нников люби́телю і богому́дрих і́ноков собесі́дниче;","Ра́дуйся, вдов і сиро́т пита́телю і оби́димих засту́пниче.","Ра́дуйся, отроко́м і ю́ношам чи́стим житіє́м твої́м благоче́стія і цілому́дрія учи́телю;","Ра́дуйся, ста́рцев і убо́гих приста́нище, і неду́гующих і стра́ждущих упокоїтелю.","Ра́дуйся, доброді́тельми па́че, не́же порфи́рою і ви́ссом, украше́нний;","Ра́дуйся, благоче́стієм па́че многоці́нния дияди́ми увінча́нний.","Ра́дуйся, благові́рний кня́же Михаї́ле, Тверськи́й пресла́вний чудотво́рче."]},{"h":"Кондак 4","ps":["Бу́рею властолю́бія обуреваєм, князь Гео́ргій ласка́нієм і да́ри іспроси́ себі́ у хана вели-кокняженіє Владимирськоє; ти же, смиренномудро, отда́в тому́ зако́нноє твоє́ владеніє, во оте́чеський град Твер отше́л єси́. Не хотя́ бо проли́тія кро́ве христия́нськия, ді́ло твоє́ Бо́гу, судя́щему пра́ведно, пре́дал єси́, воспіва́я Єму́: Аллилуя."]},{"h":"Ікос 4","ps":["Сли́шав, я́ко сро́дник твой, неудовлився от'ятієм у тебе́ великокняженія, в преді́ли Тверськи́я со мно́гою ра́тію татарською вни́де, разоря́я оби́телі і хра́ми, ві́си огне́м і мече́м істребля́я, і Бо́гом вруче́нноє ті ста́до распужая і расхищая, я́ко Авраа́м, домоча́дці твоя́ собра́л єси́, і совещався с ни́ми, ду́шу твою́ за святи́ню Госпо́дню і за лю́ди твоя́ положи́ти восхоті́л єси́. Сего́ ра́ди і ни́ні ми благода́рно тебі́ вопіє́м:","Ра́дуйся, кня́же по се́рдцю Бо́жию, скорб твою́ Бо́гу поведавий;","Ра́дуйся, воєво́до благові́рний і смиренному́дрий, печа́ль твою́ на Бо́га возверзий.","Ра́дуйся, за́повідь Христо́ву, є́же возлюби́ти бли́жняго, я́ко себе́, ді́ли оправда́вий;","Ра́дуйся, Мойсе́ю і Па́влу в ре́вности о бла́гі і спасе́нії люде́й твої́х поревнова́вий.","Ра́дуйся, во бра́ні не сла́ви земни́я, но огражде́нія святи́ні Госпо́дней поругаємой іска́вий;","Ра́дуйся, бу́йство татарськоє си́лою Бо́жиєю укроти́вий.","Ра́дуйся, лю́ди твоя́ от разоре́нія, плі́на і лю́тия сме́рті по́мощію Ви́шняго оградивий;","Ра́дуйся, благові́рний кня́же Михаї́ле, Тверськи́й пресла́вний чудотво́рче."]},{"h":"Кондак 5","ps":["Боготе́чная звізда́ во́єм твої́м яви́лся єси́, благові́рний Михаї́ле, предидя бо пред полки́ твої́ми, десни́цею твоє́ю, Бо́гом укрепляємою, разруши́л єси́ врага́ і ме́стника. Ті́мже, побіди́в сопроти́вних Бо́гу, чудоді́йствующему ми́шцею висо́кою, сокруши́вшему бра́ні і спа́сшему лю́ди Своя́, воспі́л єси́: Аллилуя."]},{"h":"Ікос 5","ps":["Ви́дівше жи́теліє гра́да Тве́рі і всея́ Тверськи́я о́бласти Бо́гом да́нную ті побі́ду пресла́вную, я́ко царевну Кончаку і злоко́зненнаго воєво́ду Кавгади́я пліни́л єси́, сла́ву і благодаре́ніє Бо́гу приноша́ху і тебі́, засту́пника своєго́, похвала́ми вінча́ша. Ті́мже і ми днесь, побі́дния по́чести тебі́ воспису́юще, вопіє́м:","Ра́дуйся, архистрати́гу сил небе́сних тезоімені́те і подража́телю, вра́жия си́ли сокруши́вий;","Ра́дуйся, вождю́ богохрани́мий, татарськия по́лчища, я́ко ханане́ї, разсі́явий.","Ра́дуйся, Авраа́ме но́вий, благослове́нний Бо́гом ви́шнім, І́же покори́ враги́ твоя́ под но́ги твоя́;","Ра́дуйся, Дави́де россі́йський, ору́жієм благоволе́нія Бо́жия вінча́нний на землі́.","Ра́дуйся, кня́же благові́рний і благочести́вий, сла́вою і че́стію превознесе́нний на небесі́;","Ра́дуйся, я́ко даде́ тебі́ Госпо́дь благослове́ніє во вік ві́ка і возвесели́ тя ра́достію неізрече́нною пред лице́м Свої́м.","Ра́дуйся, благові́рний кня́же Михаї́ле, Тверськи́й пресла́вний чудотво́рче."]},{"h":"Кондак 6","ps":["Пропові́дник правосла́вния ві́ри яви́лся єси́, благові́рний кня́же, пред си́ни агарянськими; Христа́ бо, Си́на Бо́жия, єди́но спасе́ніє і утіше́ніє челові́ков би́ти пропові́дуя словеси́ богому́дрими і терпі́нієм твої́м до́блим, неві́дущих науча́л єси́ пі́ти Єму́: Аллилуя."]},{"h":"Ікос 6","ps":["Возсія́л єси́ во сві́тлостіх святи́х, я́ко со́лнце, вінце́м сла́ви ув'язе́н на небесі́ і нетлі́нієм тілесе́ просла́влен на землі́: ві́ри бо ра́ди Христо́ви пострада́в. Ца́рствія благолі́піє і віне́ць добро́ти от руки́ Госпо́дні прия́л єси́. Ті́мже, предстоя́ престо́лу сла́ви, помина́й нас, похваля́ющих тя і глаго́лющих:","Ра́дуйся, страстоте́рпче Христо́в, во всем житії́ твоє́м ві́рний Бо́жий служи́телю;","Ра́дуйся, Бо́га ви́ну славивий на землі́, і ни́ні а́нгелом і арха́нгелом сожи́телю.","Ра́дуйся, за труд любве́ і по́двиги благоче́стія с преподо́бними і пра́ведними просла́вленний;","Ра́дуйся, за страда́нія твоя́ і терпі́ніє крі́пкоє му́чеником сопричтенний.","Ра́дуйся, іспові́дниче Христо́в тве́рдий і неустраши́мий;","Ра́дуйся, помо́щниче всім пречу́дний і храни́телю от Бо́га нам да́нний.","Ра́дуйся, моли́твенниче о чту́щих тя те́плий і богоуго́дний;","Ра́дуйся, благові́рний кня́же Михаї́ле, Тверськи́й пресла́вний чудотво́рче."]},{"h":"Кондак 7","ps":["Хотя́й дні ви́діти бла́гі, не мщенієм, но любо́вію возда́л єси́ враго́м твої́м: Кавгади́я бо і іни́я плі́нники с дарми́ в зе́млю їх отпусти́л єси́ і, мир кня́зю Гео́ргію дарова́в, не губи́ти Христия́ни, па́че же защища́ти от пога́них увіща́л єси́. Помози́ у́бо і нам, свя́те, стезя́м ми́ра і любве́ твоєя́ послі́довати, да благоприя́тно Бо́гу ми́ра поє́м: Аллилуя."]},{"h":"Ікос 7","ps":["Но́ваго тя Іо́сифа незло́биваго і Дави́да кро́ткаго разуміва́єм, богому́дре Михаї́ле: ов бо бра́тіям свої́м, сей же Сау́лу мсти́ти за озлобле́нія їх не хотя́ху. І ти у́бо, імі́я во вла́сті твоє́й іщущия погуби́ти тя, не я́ко плі́нния, но я́ко посетителі імі́л єси́ їх, благотворя́ враго́м твої́м. Сего́ ра́ди, похваля́юще тя, вопіє́м:","Ра́дуйся, россі́йський Іо́сифе, от бра́тії твоєя́ ізмаїльтяном на пліне́ніє і смерть обрече́нний;","Ра́дуйся, тіх зло́бу не мече́м то́кмо, но любо́вію укроти́ти поіскавий.","Ра́дуйся, сі́ятеля вражди́ і мще́нія дия́вола, я́ко Дави́д Голія́фа, кро́тостію і ми́лостію ко враго́м побіди́вий;","Ра́дуйся, враги́ твоя́ пліне́нния сло́вом уті́шивий і пи́щею удовли́вий.","Ра́дуйся, лю́ди твоя́, бра́нію расточе́нния, любо́вію собра́вий;","Ра́дуйся, разоре́нния і бедствующия уті́шивий і благопотре́бним снабдивий.","Ра́дуйся, благові́рний кня́же Михаї́ле, Тверськи́й пресла́вний чудотво́рче."]},{"h":"Кондак 8","ps":["Стра́нна ні́кая, но прелюбе́зна Бо́гу і челові́ком ви́дим о тебі́, свя́те Михаї́ле. Ві́дий бо окле-ветанія враго́в твої́х і непра́вду суде́й твої́х, не убоя́лся єси́ гні́ва ханськаго; но да сохрани́ши в ми́рі оте́чество твоє́, ду́шу твою́ положи́ти за лю́ди твоя́ возжелі́л єси́, взира́я на нача́льника ві́ри і соверши́теля Ісу́са, Єму́же і вопія́л єси́: Аллилуя."]},{"h":"Ікос 8","ps":["Всего́ себе́ Бо́гу преда́в, я́ко а́гнець незло́бивий на заколе́ніє текл єси́, блаже́нне; не восхоті́л бо єси́ подо́битися нає́мнику, і́же оставля́єть о́вці, ви́дя во́лка гряду́ща, і бі́гаєть, но я́ко па́стир до́брий, біжа́ти советующим отвіща́л єси́: а́ще і сохрани́ть бі́гство живо́т мой, но погуби́т лю́ди моя́ непови́нния. Ті́мже сла́в'яще благоприя́тноє твоє́ о лю́діх попече́ніє, вопіє́м ті:","Ра́дуйся, па́стирю до́брий, Пастиренача́льнику Христу́ подража́вий;","Ра́дуйся, лю́ди своя́ па́че при́сних твої́х і па́че себі́ самаго́ возлюби́вий.","Ра́дуйся, вся претерпі́ти, то́кмо да лю́ди твоя́ от разоре́нія і напра́сния сме́рті ізба́вити ізво́ливий;","Ра́дуйся, от убива́ющих ті́ло і немогу́щих ли́шше что сотвори́ти не убоя́вийся.","Ра́дуйся, тлі́нную сла́ву земну́ю ні во что́же вміни́вий;","Ра́дуйся, вся ле́стния сові́ти злочести́ваго Кавгади́я презрі́вий.","Ра́дуйся, сохране́ніє ві́ри Христо́ви всім кра́сним і сла́вним ми́ра сего́, тебі́ обещанним, предпочтий;","Ра́дуйся, є́же пострада́ти і умре́ти за Христа́, да с Ним ві́чно ца́рствуєши, предизбравий.","Ра́дуйся, благові́рний кня́же Михаї́ле, Тверськи́й пресла́вний чудотво́рче."]},{"h":"Кондак 9","ps":["Все єстество́ челові́чеськоє кро́тостію і смире́нієм удиви́л єси́, благові́рний кня́же: зло́бния бо клевети́ враго́в твої́х кро́ткими словеси́ отвраща́я, непра́вду суде́й ні єди́ним же сло́вом обличи́л єси́, но я́ко і́стинний раб Христа́ Бо́га, послі́довал єси́ Влади́ці твоєму́, і́же укоря́єм проти́ву не укоря́ше, стражда́ не преща́ше, Єму́же, судії́ всіх і мздовоздаятелю, і вопія́л єси́: Аллилуя."]},{"h":"Ікос 9","ps":["Виті́ї многовіща́нния невозмогуть ізрещи́ вели́каго страда́нія твоєго́, страстоте́рпче: отславше бо вразі́ твої́ дру́ги твоя́ і при́сния, кла́ду ве́лію на ви́ю твою́ возложи́ша, і недово́льни су́ще, я́ко тягото́ю кла́ди, гла́дом, жа́ждею і хожде́нієм мно́гим за ханом днем до істоща́нія тя ізнуряху, но́щію ру́ці і но́зі твої́ в кла́ду забиваху, да нікоєя́ же осла́би імі́єши членом твої́м. Ті́мже, помина́юще по́двиги твоя́, вопіє́м ті:","Ра́дуйся, за ві́ру і оте́чество твоє́ безче́стіє претерпі́вий;","Ра́дуйся, бос і гладен, свя́зан і поругаєм всі́ми, я́ко плі́нник, за ханом влеко́мий.","Ра́дуйся, псалмопеній ра́ди всено́щних очесе́м твої́м сна і ві́ждома дрема́нія не да́вий;","Ра́дуйся, в ско́рбі твоє́й і злострада́ніях плачущия боля́ри і дру́ги твоя́ уті́шивий.","Ра́дуйся, твоє́ утіше́ніє в єди́ном Го́споді і моленіях Єму́ положи́вий;","Ра́дуйся, за гряду́щая страда́нія і лю́тую смерть, ї́хже прови́діл єси́, Бо́га благодаривий.","Ра́дуйся, благові́рний кня́же Михаї́ле, Тверськи́й пресла́вний чудотво́рче."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ ду́шу твою́, я́ко христия́нин і́стинний к сме́рті себі́ приуготовил єси́. Ві́дий бо, я́ко близ єсть смерть, при две́ріх, покая́нієм те́плим і сле́зним пред отце́м духо́вним ду́шу очи́стил єси́ і, приобще́нієм ті́ла і кро́ве Христо́ви соєдини́вся Христу́, воспіва́л єси́ Єму́, всім да́рующему живо́т ві́чний: Аллилуя."]},{"h":"Ікос 10","ps":["Царя́ нечести́ваго повелі́ніє іспроси́вше, вразі́ твої́ посла́ша во́їни уби́ти тя, і я́ко во́лці хи́щници, я́ко тигри, жа́ждущії кро́ве, нападо́ша злі́ї на тя, а́гнця незло́биваго, і кладою терзаху ви́ю твою́, і главо́ю тя о вежу уда́риша, і на зе́млю пове́ргше, п'ястьми́ тя бія́ху неща́дно, до́ндеже люті́йший всіх Романець ноже́м уда́ри в ре́бра твоя́ і істо́рже любвеобильноє се́рдце твоє́. Ті́мже тебі́, я́ко а́гнця, за Христа́ закланного, похваля́юще, вопіє́м:","Ра́дуйся, я́ко А́велю, за́вистію бра́тнею погубленному, уподо́бился єси́;","Ра́дуйся, я́ко віне́ць твой княжеський кро́вними ка́плями, я́ко ка́менієм чу́дним, украси́л єси́.","Ра́дуйся, я́ко ру́бище твоє́, в не́мже убіє́н бил єси́, красні́йше багряни́ци ца́рськия златотканния соді́лал єси́;","Ра́дуйся, я́ко се́рдце твоє́ чи́сто і смире́нно в же́ртву Христу́, за ни пострада́вшему, прине́сл єси́.","Ра́дуйся, я́ко му́чеником подража́вий, ли́ку їх сопричтен єси́;","Ра́дуйся, за Христа́ смерть приє́мий, со Христо́м ві́чно жи́ти сподо́бился єси́.","Ра́дуйся, благові́рний кня́же Михаї́ле, Тверськи́й пресла́вний чудотво́рче."]},{"h":"Кондак 11","ps":["Пі́ніє благода́рственноє Го́споду прино́сим о тебі́ чту́щії тя, святи́й благові́рний кня́же Михаї́ле, я́ко дарова́ Госпо́дь нетлі́нноє ті́ло твоє́ Тверськой о́бласти во утіше́ніє і огражде́ніє, гра́ду Тве́рі в сла́ву і защище́ніє, скорб'я́щим во утіше́ніє, бедствующим во отра́ду і по́мощ, боля́щим во істо́чник ісціле́ній, і всім, ві́рою притекающим к тебі́, во спасе́ніє. Ті́мже Бо́гу, ди́вному во святи́х, вопіє́м: Аллилуя."]},{"h":"Ікос 11","ps":["Сві́та невече́рняго прича́стника яви́ тя Госпо́дь а́біє по преставле́нії твоє́м, блаже́нне: о́блаки бо сві́тлими ті́ло твоє́, лежа́щеє на землі́, огради́в от звіре́й ди́віїх, столпо́м о́гненним показа́ тя всім столпа́ би́вша ві́ри і пра́вди, і ті́ло твоє́ нетлі́нно сохрани́в, чудеси́ просла́ви тя. Ті́мже вопіє́м ті:","Ра́дуйся, сто́лпе ві́ри, к землі́ обітова́нія путь нам показу́яй;","Ра́дуйся, о́блаче духо́вний, от бід і напа́стей лю́ди твоя́ покрива́яй.","Ра́дуйся, сосу́де благода́ті, со́нми ві́рних на поклоне́ніє моще́м твої́м привлека́яй;","Ра́дуйся, істо́чниче неоску́дний, всім приходящим с ві́рою ісціле́нія подава́яй.","Ра́дуйся, воєво́до непобіди́мий, я́коже в животі́, і по сме́рті враги́ на́ша от нас прогоня́яй;","Ра́дуйся, сла́во і упова́ніє гра́да Тве́рі, в моли́твах твої́х ви́ну нас помина́яй.","Ра́дуйся, благові́рний кня́же Михаї́ле, Тверськи́й пресла́вний чудотво́рче."]},{"h":"Кондак 12","ps":["Благода́ть, да́нную ті от Бо́га, ві́дуще, лю́діє гра́да твоєго́, і помина́юще, я́ко возлюби́л єси́ їх в животі́ твоє́м да́же до сме́рти, ви́ну к тебі́, я́ко ско́рому і крі́пкому помо́щнику во обстоя́ніїх і ско́рбіх, находя́щих на град, притека́ху. І не посрами́л єси́ упова́нія їх, ско́ро от бід избавля́я моли́твами твої́ми. Ті́мже Бо́гу, спасавшему і спаса́ющему тебе́ ра́ди нас недосто́йних, вопіє́м: Аллилуя."]},{"h":"Ікос 12","ps":["Пою́ще страда́нія твоя́, ублажа́єм святу́ю па́м'ять твою́, с ві́рою і любо́вію притека́єм к ра́ці моще́й твої́х, і я́ко предстоя́ща с ли́ки а́нгел і со всі́ми святи́ми Животворя́щей Тро́йці, смире́нно мо́лим тя: не забу́ди, кня́же благові́рний, лю́ди твоя́, спаса́й град твой і ве́сі твоя́, я́коже і пре́жде, да́руй всім, притекающим к тебі́, я́же к житію́ вре́менному, па́че же к жи́зні ві́чній благопотре́бная. Ми́лостив бу́ди нам, восхваляющим тя недосто́йними усти́ і пою́щим:","Ра́дуйся, го́рняго гра́да дости́гнувий і град свой земни́й любо́вію назираяй;","Ра́дуйся, мно́гажди град Твер от смертоно́сния я́зви ди́вно спасавий.","Ра́дуйся, со а́нгели сликовству́яй і лю́ди твоя́ в ско́рбіх їх не забива́яй;","Ра́дуйся, с пра́ведними Бо́гу сла́ви предстоя́й і нас грі́шних, моля́щихся ті, не презира́яй.","Ра́дуйся, благами ві́чними і неізрече́нними наслажда́яйся і ле́пту вдови́ці, тебі́ зді приноси́мую, любе́зно приє́мляй;","Ра́дуйся, на землі́ і на небесі́ от Бо́га просла́вленний і на́ша недосто́йная хвале́нія не отверга́яй.","Ра́дуйся, благові́рний кня́же Михаї́ле, Тверськи́й пресла́вний чудотво́рче."]},{"h":"Кондак 13","ps":["О преди́вний во страда́льціх, святи́й благові́рний вели́кий кня́же Михаї́ле! При́зри ми́лостивно на смире́нния раби́ твоя́ і умоли́ Го́спода Бо́га, да сохрани́ть град твой і лю́ди твоя́, і вся гра́ди і ве́сі христия́нськия от гла́да, губи́тельства, тру́са, пото́па, огня́ і вся́каго зла, і да́руєть всім нам во́льних і нево́льних гріхо́в оставле́ніє, да просла́вльшему тебі́ Бо́гу поє́м: Аллилуя.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов і всея́ тва́рі Созда́тель, ангелонравна тя прови́дів і воітеля за Христа́ непобіди́ма, архистрати́гу небе́сних во́їнств тезоіме́нне тебі́ нарещи́ся благоустро́ї. Ті́мже сла́в'яще Бо́жиє о тебі́ промишле́ніє, я́ко ізбра́нну сосу́ду Христо́ви благода́ті, вопіє́м ті:","Ра́дуйся, равноапо́стольнаго Влади́мира благослове́нная о́трасле;","Ра́дуйся, благові́рних і благочести́вих Яросла́ва і Ксе́нії ча́до.","Ра́дуйся, я́ко во утро́бі ма́тере осиротев, всіх Бо́га во отця́ мі́сто обрі́л єси́;","Ра́дуйся, я́ко под кро́вом крил Єго́ прему́дростію і во́зрастом преспіва́л єси́.","Ра́дуйся, я́ко отроча́ доброумно і благонра́вно бил єси́;","Ра́дуйся, я́ко от ю́ности твоєя́ па́че вся́каго сокро́вища Христа́ возлюби́л єси́.","Ра́дуйся, я́ко от Бо́га і челові́к досто́йні возлю́блен бил єси́;","Ра́дуйся, благові́рний кня́же Михаї́ле, Тверськи́й пресла́вний чудотво́рче."]},{"h":"Кондак 1","ps":["Ізбра́нний Бо́гом із земни́х князе́й в небе́сноє пресві́тлоє му́ченичеськоє во́їнство, от земни́я сея́ юдо́лі в Ца́рство Небе́сноє пресели́лся єси́: положи́л бо єси́ ду́шу твою́ за лю́ди твоя́. Ті́мже, я́ко імі́яй дерзнове́ніє ко Го́споду, моли́ за держа́ву Россі́йськую, за град твой і лю́ди, тебі́ зову́щия:","Ра́дуйся, благові́рний кня́же Михаї́ле, Тверськи́й пресла́вний чудотво́рче."]},{"h":"Молитва","ps":["Ди́вний во страда́льціх святи́й благові́рний вели́кий кня́же Михаї́ле! Ве́лія по́двиги і труди́ твоя́, я́же за правові́ріє, за Це́рков Бо́жию і за оте́чество твоє́ град Твер положи́л єси́. Ти, возжела́во ви́шніх, оста́вил єси́ тлі́нную сла́ву земну́ю, і ревну́я подви́жником Христо́вим, до́блественно противуста́л єси́ я́рости царя́ нечести́ваго і преще́нію зломи́шленнаго єго́ воєво́ди. Ти, приє́м непра́ведноє осужде́ніє і заколе́ніє, восприя́л єси́ Небе́сноє Ца́рствіє, і кро́вними ка́плями, я́ко пречу́дним ка́менем, украси́в на главі́ своє́й віне́ць, предстої́ши ни́ні на Небесі́х Престо́лу всіх Влади́ки с ли́ки А́нгел і со всі́ми святи́ми Єго́. Сего́ ра́ди, притека́юще к ра́ці моще́й твої́х, лобиза́єм о́ния серде́чними устна́ми і уми́льно к тебі́ взива́єм: о тезоімені́те небе́сному воєво́ді ви́шніх сил, вели́кий кня́же Михаї́ле! Моли́ся непреста́нно Христу́ Бо́гу за град твой, за лю́ди і за вся правосла́вния христия́ни. Бу́ди спобо́рник крі́пок на враго́в правосла́вія Це́ркві Христо́вой. Бу́ди і нам помо́щник улучи́ти вся, к по́льзі на́шей і ко спасе́нію благопотре́бная, охраня́й нас от іскуше́ній і напа́стей, приходя́щих во вре́менній жи́зні, і не лиши́ нас хода́тайства твоєго́ ко Христу́ Бо́гу, во є́же получи́ти нам прегріше́ній проще́ніє і сподо́битися Небе́снаго селе́нія со ізбра́нними Єго́, я́ко да і в сем сла́виться пречестно́є і великолі́поє і́м'я Єго́ во ві́ки. Амі́нь."]},{"h":"Тропар, глас 8","ps":["Возви́сив ум твой к Бо́гу, / і житія́ со А́нгели возжелі́л єси́, / тлі́нную сла́ву земну́ю оста́вил єси́, блаже́нне, / і положи́л єси́ ду́шу твою́ за лю́ди твоя́, / восприя́л єси́ віне́ць проти́ву трудо́в твої́х, Богому́дре Михаї́ле, // моли́ Христа́ Бо́га о чту́щих любо́вію святу́ю па́м'ять твою́."]},{"h":"Кондак, глас 2","ps":["Ви́шніх іща́ і земну́ю сла́ву презрі́в, / Це́рков Бо́жию обагри́л єси́ твоє́ю кро́вію, / за Ню́же і пострада́л єси́, свя́те Михаї́ле, / заколе́ніє непра́ведноє приє́м веселя́ся. / Ті́мже со А́нгели предстоя́ Христу́ Бо́гу, // моли́ непреста́нно за вся ни."]},{"h":"Величання","ps":["Велича́єм тя, / святи́й благові́рний кня́же Михаї́ле, / і чтим святу́ю па́м'ять твою́, / ти бо мо́лиши за нас / Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст праведному Іову Многостраждальному","e":"Akathist to the Righteous Job the Long-suffering","secs":[{"h":"Кондак 1","ps":["Ізбра́нному Го́сподем вели́кому Ве́тхаго Заві́та пра́веднику, п'я́тому от Авраа́ма Іса́вових сино́в си́нові, І́ову Многострада́льному похва́льноє воспоє́м пі́ніє: я́ко свої́ми ди́вними доброді́тельми і всім свої́м житіє́м учи́телем всей вселе́нній яви́вшемуся. Ти же, пра́ведний І́ове, прийми́ сію́ похвалу́, с любо́вію тебі́ приноси́мую, согрі́й на́ша се́рдця жела́нієм подража́ти твої́м по́двигом, да єдиноду́шно зове́м ті:","Ра́дуйся, І́ове Многострада́льний, всему́ ми́ру учи́телю преди́вний."]},{"h":"Ікос 1","ps":["А́нгели Бо́жії в день ні́кий предста́ша Го́сподеві, хвалу́ Єму́ вознося́ще. С ни́ми же і дия́вол при́йде. Сей послі́дній, вопрошенний Го́сподем об І́ове, нача́ть клевета́ти на пра́ведника, я́ко той чтить Го́спода земни́х ра́ди благ, і́миже Бог єго́ награди. Ми же, злу́ю дия́вольськую клевету́ на вели́каго пра́ведника с горечію воспомина́юще, та́ко І́ова восхваля́єм:","Ра́дуйся, І́ове, я́ко сам Госпо́дь найменова́ тя челові́ка непоро́чна і благочести́ва.","Ра́дуйся, от Го́спода вся бла́га земна́я приє́мий.","Ра́дуйся, мно́жество слуг імі́вий і стада́ своя́ ти́сящами ісчитивавий.","Ра́дуйся, Го́сподем дарова́нних тебі́ сино́в і дще́рей во вели́ком благоче́стії воспита́вий.","Ра́дуйся, я́ко о ча́діх свої́х вели́коє попече́ніє явля́л єси́.","Ра́дуйся, я́ко ні к чему́ же от земни́х благ се́рдцем не прилеплялся єси́.","Ра́дуйся, я́ко му́дростію своє́ю над всі́ми висо́ко стоя́л єси́.","Ра́дуйся, я́ко цар посреді́ хра́брих бил єси́.","Ра́дуйся, я́ко бил єси́ благоро́днійший су́щих от восто́к со́лнця.","Ра́дуйся, всесла́вне, Бо́жий уго́дниче і́стинний.","Ра́дуйся, вели́кая діла́ блага́я соверши́вий.","Ра́дуйся, в терпі́нії своє́м мир просвіти́вий.","Ра́дуйся, І́ове Многострада́льний, всему́ ми́ру учи́телю преди́вний."]},{"h":"Кондак 2","ps":["Ві́дая ві́ру несокрушимую і ве́лію преданость во́лі Бо́жії раба́ своєго́, даде́ Госпо́дь власть дия́волу вся бла́га земна́я у І́ова от'яти і чад єго́ погуби́ти. Ми же, сему́ особому ізволе́нію Бо́жию див'я́щеся, вопіє́м Прему́дрому Бо́гу: Аллилу́я!"]},{"h":"Ікос 2","ps":["Ра́зумом свої́м злим зіло́ обра́довася дия́вол, таково́є ізволе́ніє Бо́жиє получи́вий. Во єди́н день, єгда́ вся ча́да І́овля єдиноду́шно в до́мі старі́йшаго бра́та своєго́ трапе́зою наслаждахуся, посла́ дия́вол ісполни́тели зли́є во́лі своєя́, і все імущество І́овле погуби́, і десятерицю чад єго́ сме́рті предаде́. Бу́ря неча́янних іскуше́ній не поколеба́ сего́ ди́внаго столпа́, і із уст єго́ ізидо́ша сицева́я му́драя словеса́: Наг ізидо́х аз от чре́ва ма́тере моєя́, наг і отиду та́мо: Госпо́дь даде́, Госпо́дь от'ят: я́ко Го́сподеві ізво́лися, та́ко бисть. Бу́ди І́м'я Госпо́днє благослове́нно во ві́ки! Чту́ще такову́ю пре́данность во́лі Бо́жії пра́ведника, ми в похвалу́ І́ова си́це глаго́лем:","Ра́дуйся, І́ове, ничи́мже пред Го́сподем согріши́вий.","Ра́дуйся, Многострада́льне, і устна́ма свої́ма безу́мія Бо́гу не да́вий.","Ра́дуйся, я́ко две́рі до́ма твоєго́ ви́ну отве́рсти бя́ху вся́кому мимошедшему.","Ра́дуйся, я́ко стра́нник вні до́ма твоєго́ не остава́шеся.","Ра́дуйся, я́ко ти вдови́ча сле́знаго о́ка не презрі́л єси́.","Ра́дуйся, о́ко сліпи́м, нога́ же хроми́х бил єси́.","Ра́дуйся, я́ко хліб свой ніколи́же єди́н вкуша́л, си́рим же оби́льно дава́л єси́.","Ра́дуйся, я́ко всі немощні́ї, чесого́ тре́бующії, вся от тебе́ ра́достно получа́ли суть.","Ра́дуйся, я́ко о вся́ком немощні́м ти пла́кал єси́.","Ра́дуйся, я́ко ви́дя му́жа в ско́рбіх, тя́жко вздихал єси́.","Ра́дуйся, во вся́кой ну́жді і печа́лі ско́рий помо́щниче.","Ра́дуйся, і́щущим предста́тельства твоєго́ неуси́пний засту́пниче.","Ра́дуйся, І́ове Многострада́льний, всему́ ми́ру учи́телю преди́вний."]},{"h":"Кондак 3","ps":["На си́лу свою́ полага́яся, сатана́ па́ки клеве́щеть на І́ова і Бо́гу глаго́леть: Посли́ ру́ку Твою́ і косни́ся косте́м єго́ і пло́ті єго́, а́ще не в ли́ці Тя благослови́ть? І па́ки Госпо́дь предає́ть ди́внаго І́ова в ру́ці беззако́нника. Сі́ятель же зла, ви́шед от лиця́ Госпо́дня, злорадно порази́ І́ова гно́єм лю́тим от но́гу да́же до глави́ єго́. І сідя́ше пра́ведник вні гра́да на гно́їщі, взем чрепок, да острога́єть гной свой. Ми же, благослов'я́ще Бо́га, допустивша навести́ прока́зу лю́тую на І́ова непоро́чнаго, прославле́нія ра́ди раба́ Своєго́, вопіє́м Го́споду: Аллилу́я!"]},{"h":"Ікос 3","ps":["Воі́стину терпі́ніє па́че челові́чеськаго ім'я́ше Многострада́льний І́ов. Болі́знь в прокаже́ннім тілесі́ умножа́шеся. Жена́ же пра́ведника, зря́щи страда́нія му́жа своєго́ і сатано́ю научаєма, даде́ сові́т І́ову: Рци глаго́л ні́кий ко Го́споду і умри́. Он же, воззрі́в, рече́ к ней: Вску́ю я́ко єди́на от безу́мних жен возглаго́лала єси́? А́ще блага́я прия́хом руки́ Госпо́дні, злих ли не стерпи́м? Во всіх сих приключи́вшихся єму́, ничи́мже согріши́ І́ов устна́ма пред Бо́гом і не даде́ безу́мія Бо́гу. Отку́ду кто возмо́жеть обрісти́ глаго́ли, прославля́ющия пра́ведника новолепне? Оба́че ми, любо́вію к І́ову побіжда́єми, Іовлими же словеси́ прославля́єм Многострада́льнаго си́це:","Ра́дуйся, я́ко ко́сті твоя́ но́щію см'ято́шася і жи́ли твоя́ в разслабле́ніє прийдо́ша.","Ра́дуйся, я́ко ко́жа твоя́ вельми́ помрачи́ся.","Ра́дуйся, я́ко і соста́ви тілесе́ твоєго́ от гно́я сгорі́ша.","Ра́дуйся, я́ко іспо́лнен бил єси́ болі́знію от ве́чера до у́тра.","Ра́дуйся, я́ко ті́ло твоє́ в гної́ черве́й пребива́ше.","Ра́дуйся, я́ко бра́шна твоя́ смра́дом преіспо́лнена би́ша.","Ра́дуйся, я́ко гнуша́хуся тебі́ і воставаху на тя видевший тя.","Ра́дуйся, І́ове, всі́ми прило́ги лука́ваго непреклоненний.","Ра́дуйся, і до сме́рти Го́споду пре́данний.","Ра́дуйся, безу́мная словеса́ жени́ своєя́ обличи́вий.","Ра́дуйся, сто́лпе до́бльственний, в тя́жких болі́зніх свої́х ніка́коже уни́нію преда́вийся.","Ра́дуйся, в ско́рбіх свої́х Бо́га благослови́вий.","Ра́дуйся, І́ове Многострада́льний, всему́ ми́ру учи́телю преди́вний."]},{"h":"Кондак 4","ps":["Мно́жество вели́ких смуще́ній на́йде на пра́ведника, єгда́ прийдо́ша к нему́ три дру́зі єго́. Сі́ї іздале́ча на прокаже́ннаго воззрі́вше, не позна́ша єго́, і возопи́вше гла́сом ве́ліїм, воспла́кашася, разтерзавше ри́зи своя́ і поси́павше пе́рстію глави́ своя́: сідя́ху при нем седьм дній і седьм ноще́й, і нікто́же от них возгагола к нему́ словесе́ утіше́нія. Зря такови́я дру́ги своя́, всім се́рдцем устреми́ся невинний страда́лець к Бо́гу, на Него́ Єдиного упова́я і взива́я Єму́: Аллилу́я!"]},{"h":"Ікос 4","ps":["Сли́ша глас ве́лій і вопль друго́в свої́х, уразумі́л єси́, Многострада́льне, я́ко ті́ї не даду́ть тебі́ утіше́нія. В го́ресті же душе́вній, пред лице́м Го́спода, отве́рзл єси́ уста́ своя́, І́ове, наче́н глаго́лати, я́ко лу́чше тебі́ не роди́тися, не́жели жи́ти кромі́ бли́зости к Бо́гу. Сострадающе пра́веднику в неізреченном єго́ горі́, в похвалу́ вели́кия єго́ преданности Го́споду, глаго́лем І́ову сицева́я:","Ра́дуйся, ве́лій Ветхозаветний пра́ведниче, все блаже́нство своє́ в бли́зости к Бо́гу полага́вий.","Ра́дуйся, страх от Бо́га отверженну тебі́ би́ти в низпосланних іскуше́ніїх іспита́вий.","Ра́дуйся, смерть предпочитавий, не́жели жи́ти тебі́ оставленну от Бо́га.","Ра́дуйся, ча́янієм утіше́нія Бо́жия ско́рби своя́ тве́рдо претерпі́вий.","Ра́дуйся, я́ко о безконе́чной загробной жи́зні віща́л єси́.","Ра́дуйся, я́ко в сме́рті ві́чний поко́й полага́л єси́.","Ра́дуйся, ско́рби земни́я я́ко предуготовле́ніє к жи́зні бу́дущей разумевий.","Ра́дуйся, ві́чния ра́дости прозорли́вий прови́дче.","Ра́дуйся, о безсме́ртнім блаже́нстві ко Го́споду взивавий.","Ра́дуйся, в земни́х благах то́кмо с Го́сподем бла́го ви́дівий.","Ра́дуйся, я́ко красоти́ зри́маго не́ба без Бо́га за нічто́же почита́л єси́.","Ра́дуйся, я́ко но́ваго не́ба і но́вия землі́ все́ю душе́ю ожида́л єси́.","Ра́дуйся, І́ове Многострада́льний, всему́ ми́ру учи́телю преди́вний."]},{"h":"Кондак 5","ps":["Всецелия Го́споду преданности пра́ведника три дру́зі єго́ в словесі́х І́овлих не разуміва́ху, то́кмо же ро́пот єго́ на Бо́га ви́дяху: сего́ ра́ди внушаху І́ову к Бо́гу обрати́тися с моли́твою і покая́нієм о грісі́х свої́х. Невинний же страда́лець о єди́нім моля́ше Бо́га, да дасть єму́ Госпо́дь си́лу невинних страда́ній свої́х уразумі́ти. К Бо́гу, істо́чнику прему́дрості і ра́зума, от се́рдця своєго́ сокруше́ннаго пра́ведник вопія́ше: Аллилу́я!"]},{"h":"Ікос 5","ps":["Хотя́ указати на неісповіди́мия путі́ Госпо́дні, об уразуменії ки́їх і до́лжно єсть челові́ку Бо́га умоля́ти, ти дру́ги своя́, І́ове, жи́ти во во́лі Бо́жії наставля́л єси́. Ми же, му́дрия рі́чі стра́ждущаго пра́ведника чту́ще, прино́сим єму́ сія́ похвали́:","Ра́дуйся, я́ко непра́вди на Бо́га уста́ твоя́ не ізреко́ша.","Ра́дуйся, лож друго́в свої́х му́дро обличи́вий.","Ра́дуйся, о непостижимости про́мисла Бо́жия смиренномудро віща́вий.","Ра́дуйся, жизнь пра́ведников во Ве́тсім Заві́те уясни́ти возжела́вий.","Ра́дуйся, погруже́нна себе́ от природи во вся́кую скве́рну ви́дівий.","Ра́дуйся, ну́жду в хода́таї между́ Бо́гом і людьми́ свої́м благочести́вим се́рдцем прозревавий.","Ра́дуйся, любве́ О́тчі от Бо́га возжада́вий.","Ра́дуйся, я́ко сле́зно умоля́л єси́ Го́спода, да не удалить Он от тебе́ страх Свой.","Ра́дуйся, я́ко іскуше́нія своя́ от Бо́га по́сланная почита́л єси́.","Ра́дуйся, я́ко гряду́щую смерть ізба́вительницю себе́ от земни́х скорбе́й полага́л єси́.","Ра́дуйся, му́дрий із'яснителю путе́й Боже́ственних.","Ра́дуйся, благи́й руководи́телю к Ца́рствію Небе́сному.","Ра́дуйся, І́ове Многострада́льний, всему́ ми́ру учи́телю преди́вний."]},{"h":"Кондак 6","ps":["Пропові́дник непостижимости глуби́н Бо́жиїх, Бо́жия прему́дрості і ра́зума яви́лся єси́, Многострада́льне, єгда́ облича́л єси́ своя́ лицемерствующия дру́ги, мня́щия себі́ путі́ прему́дрости Бо́жия разумеюща. Смире́нно ви́дя себі́ не́мощна про́мисл Бо́жий ві́діти, возжелаше пра́ведник на суд пред Бо́гом ста́ти і у Того́ осо́бия ми́лости проси́ти, даби́ Госпо́дь грозную ру́ку Свою́ от'ял і стра́хом Свої́м єго́ не ужасал. Нося́ в се́рдці своє́м смире́нную мольбу́ ко Го́споду, со умиле́нієм І́ов к Єди́ному Судії́ і Бо́гу взива́ше: Аллилу́я!"]},{"h":"Ікос 6","ps":["Возсія́ в душі́ твоє́й, пра́ведне, благода́тний луч Боже́ственний, єгда́ во вели́цій го́рести своє́й приближеніє к сме́рті ожида́л єси́, і к невозвратному ше́ствію в неві́домую страну́ мра́ка і тьми ві́чния гото́вился єси́. Все́ю бо душе́ю люб'я́ Го́спода, по призиву Бо́жию в загробний мир іти́ гото́в бил єси́, І́ове, оба́че наде́жди жи́зні но́вия в бли́зости к Бо́гу в се́рдці своє́м не отривал єси́. Ра́дующеся таково́му сві́тлому ча́янію стра́ждущаго пра́ведника, с любо́вію поє́м єму́:","Ра́дуйся, смире́нний, Богому́дрий, невинний страда́льче.","Ра́дуйся, о бли́зости сме́ртній непреста́нно помишля́вий.","Ра́дуйся, день і час кончи́ни челові́ка в премудрой во́лі Бо́жії полага́вий.","Ра́дуйся, ра́бе Христо́в нелицемі́рний.","Ра́дуйся, я́ко чи́стим се́рдцем свої́м Бо́га узрі́ти возжела́л єси́.","Ра́дуйся, я́ко в своє́й глубо́кой Го́споду преданности дерзнове́нно Того́ вопроша́л єси́.","Ра́дуйся, я́ко от пра́вди своєя́ ніка́коже отступи́л єси́.","Ра́дуйся, я́ко у Бо́га і́стинния прему́дрости іска́л єси́.","Ра́дуйся, дру́ги своя́ врачи непра́ведния іменова́вий.","Ра́дуйся, в словесі́х їх лесть пред Бо́гом ви́дівий.","Ра́дуйся, ду́шу свою́ чи́сту і непоро́чну сохрани́вий.","Ра́дуйся, безбоя́зненно пред Го́сподем на суді́ стоя́ти восхоті́вий.","Ра́дуйся, І́ове Многострада́льний, всему́ ми́ру учи́телю преди́вний."]},{"h":"Кондак 7","ps":["Хотя́щим і́стинную му́дрость в словесі́х твої́х уразумі́ти, помози́ нам, уго́дниче Бо́жий. Ло́жния дру́ги своя́ облича́я, указа́л єси́ їм, І́ове, я́ко бла́га земна́я і го́рести людські́я суть в рука́х Бо́жиїх. Госпо́дь раздає́ть їх прему́дро: отню́дуже і пра́ведний лю́ті страждаєть і нечести́вий благоденствуєть. Та́йни мироправленія Бо́жия челові́к пе́рстний ві́діти не мо́жеть, за вся же до́лжен єсть благодари́ти Го́спода і, восхваля́я Єго́, пі́ти Єму́: Аллилу́я!"]},{"h":"Ікос 7","ps":["Ди́вния рі́чі сли́шим ми із уст Ветхозаветнаго пра́ведника. Лицемерствующії же дру́зі єго́ утіше́нія І́ову не дава́ху, найпа́че же но́вия ско́рби се́рдцю єго́ причиняху. Пра́ведник же то́кмо ко Го́споду мисль свою́ устремляше, на Єди́наго Засту́пника і Нелицепрятнаго Судію́ Бо́га упова́ше, от Него́ Єди́наго утіше́нія ча́я. Ви́дяще таково́є превиспренноє устремле́ніє Многострада́льнаго, велича́єм єго́ си́це:","Ра́дуйся, лицемі́рія му́дрий обличи́телю.","Ра́дуйся, дру́ги своя́ зли́я уті́шители іменова́вий.","Ра́дуйся, ви́дівий дру́ги, покивающих глава́ми над вели́кими страда́ньми дру́га своєго́.","Ра́дуйся, то́кмо от Го́спода се́рдцю своєму́ облегче́нія іска́вий.","Ра́дуйся, то́кмо на небесі́х І́стиннаго Засту́пника себі́ ви́дівий.","Ра́дуйся, я́ко у́жаси пред Бо́гом преісполняшеся се́рдце твоє́.","Ра́дуйся, я́ко чи́стою моли́твою своє́ю к Бо́гу приближался єси́.","Ра́дуйся, я́ко на пра́вду свою́ крі́пко упова́л єси́.","Ра́дуйся, в смире́нії своє́м, бесі́довати с Бо́гом недосто́йна себі́ почитавий.","Ра́дуйся, то́кмо умоля́ти Бо́га Судію́ своєго́ жела́вий.","Ра́дуйся, невиновность свою́ пред всім ми́ром свиді́тельствуяй.","Ра́дуйся, я́ко о́ко твоє́ благода́тними слеза́ми преіспо́лнено бі.","Ра́дуйся, І́ове Многострада́льний, всему́ ми́ру учи́телю преди́вний."]},{"h":"Кондак 8","ps":["Стра́нно єсть нам, сино́м Заві́та Но́ваго, кро́вію Си́на Бо́жия іскупле́нним і Єва́нгеліє Христо́во іму́щим, дерзнове́нная словеса́ Ветхозаветнаго пра́ведника сли́шати. Вели́кия та́йни загробнаго ми́ра Многострада́льному не ведо́ми бя́ху, свої́м же преда́нним Бо́гу се́рдцем І́ов моля́шеся, да озари́ть єго́ Су́щий на небесі́ Свиді́тель і засту́пник такови́х та́їн ві́дінієм. Ко Го́споду слези́ть о́ко Многострада́льнаго і с умиле́нієм поє́ть пра́ведник Бо́гу: Аллилу́я!"]},{"h":"Ікос 8","ps":["Ча́я приближе́нія кончи́ни своєя́, терп'я́ на землі́ страда́нія тя́жкая, в благода́тних озареніїх свої́х глаго́лаше пра́ведник, я́ко а́ще в ско́рбіх на землі́ ність облегче́нія, да скри́єть єго́ Госпо́дь в преіспо́дніх до вре́мені. Єгда́ же преста́неть гнів Бо́жий, гріси́ і беззако́нія людська́я покри́ються, тогда́ Госпо́дь по ми́лості своє́й дасть пра́веднику близьким к Нему́ би́ти. Ми же, таково́є сві́тлоє упова́ніє стра́ждущаго зря́ще, в особую єму́ похвалу́ глаго́лем си́це:","Ра́дуйся, прозорли́вче Богому́дрий і просвіще́нний.","Ра́дуйся, святи́й і вели́кий страда́льче.","Ра́дуйся, пло́тію постарадавий і гріха́ свободи́вийся.","Ра́дуйся, любо́вію ко Го́споду дух уни́нія препобіди́вий.","Ра́дуйся, я́ко сві́тлия наде́жди жи́зні бу́дущия преіспо́лнен бил єси́.","Ра́дуйся, я́ко все́ю душе́ю в любо́в безконе́чную Бо́жию ві́ровал єси́.","Ра́дуйся, та́йни загробнаго ми́ра уві́діти возжада́вий.","Ра́дуйся, в мра́чних удо́ліїх а́дових ми́лости Бо́жия ожидавий.","Ра́дуйся, упова́нієм на сві́тлую жизнь за гробо́м Дави́ду, Іса́її, Ієзекі́їлю і іни́м проро́ком ра́вний.","Ра́дуйся, я́ко сим упова́нієм стал єси́ на єди́ний путь с вели́кими Ветхозаветними пра́ведники.","Ра́дуйся, всім пра́ведником ра́дость сві́тлаго битія́ за гробо́м пропові́давий.","Ра́дуйся, Єва́нгельських Христо́вих і́стин прозорли́вий іспові́дниче.","Ра́дуйся, І́ове Многострада́льний, всему́ ми́ру учи́телю преди́вний."]},{"h":"Кондак 9","ps":["Вся́кими вели́кими іскуше́ньми і скорбми́ духо́вно возраста́л єси́, І́ове. Госпо́дь же особими открове́нії услаждаше ду́шу твою́, Многострада́льне. Благода́тно озаре́нний Бо́гом, ти, ізбра́нниче Бо́жий, віща́л єси́: Вім, я́ко жив Іскупи́тель мой, І́же в день послі́дній распадающуюся ко́жу мою́ сію́ із пра́ха воскреси́ть, аз же во пло́ті моє́й узрю́ Бо́га. Воспринимающе сердця́ми на́шими сію́ ві́ру во воскреше́ніє пло́тію, ми, такови́ми открове́нії пра́ведника вразумля́ємі, вопіє́м Бо́гу: Аллилу́я!"]},{"h":"Ікос 9","ps":["Віті́я воі́стину непра́ведния яви́шася многоречивії дру́зі твої́, І́ове. Ложнії сі́ї уті́шителіє возжелаша тя, стра́ждущаго дру́га своєго́, укоря́ти, глаго́люще, я́ко ти а́лчущих не пита́л єси́, ни́щих не одевал єси́, вдови́ць і си́рих обижал єси́, і жа́жду бли́жніх не утоля́л єси́. О вели́коє долготерпі́ніє великого страда́льця! Восхваля́юще таково́є долготерпі́ніє і чи́стоє доброді́тельноє І́овле житіє́, воспіва́єм єму́ сицева́я:","Ра́дуйся, я́ко поноше́нія от друго́в свої́х смире́нно претерпіва́л єси́.","Ра́дуйся, я́ко і посмія́нія ма́лих діте́й благоду́шно прийма́л єси́.","Ра́дуйся, я́ко і раби́ твої́ любо́в твою́ к ним заби́ша.","Ра́дуйся, я́ко і жена́ твоя́ лука́вому сові́ту неразу́мно внима́ше.","Ра́дуйся, я́ко злий сатана́, разтерзав столп тілесе́, сокро́вища ду́ха твоєго́ не укра́де.","Ра́дуйся, ве́лій борче, вся ко́зні вражия препобіди́вий.","Ра́дуйся, я́ко Єди́наго Бо́га і Го́спода на землі́ зрі́ти хоті́л єси́.","Ра́дуйся, я́ко своє́ю преданностію Го́споду просла́вился єси́.","Ра́дуйся, висото́ю по́двигов свої́х всіх удиви́вий.","Ра́дуйся, просвіще́нія духо́внаго указа́телю.","Ра́дуйся, всіх люде́й вели́коє утіше́ніє.","Ра́дуйся, я́ко мно́гим в ми́рі сем тобо́ю спасе́ніє яви́ся.","Ра́дуйся, І́ове Многострада́льний, всему́ ми́ру учи́телю преди́вний."]},{"h":"Кондак 10","ps":["Спасе́нія себі́ то́кмо от Го́спода ча́я, і сві́тлую наде́жду на обновленную жизнь за гробо́м імі́я, Многострада́льний І́ов, і́же пра́ведник Ве́тхаго Заві́та бив, утверди́тися в озареніїх свої́х не дерза́ше, в ми́сліх же і чувствіїх свої́х сумняшеся і го́ресть ні́кую в душі́ претерпіва́ше. Ми же, пра́веднику в сей го́рести сострадающе і Святі́й во́лі Бо́жії преклоня́ющеся, возопії́м Любвеобильному і Прему́дрому Бо́гу: Аллилу́я!"]},{"h":"Ікос 10","ps":["Стіна́ крі́пкая в преданности Го́споду всему́ ми́ру яви́лся єси́, Многострада́льне, єгда́ тве́рдо о непоро́чности своє́й і лицемі́рії друго́в свої́х віща́л єси́. Іму́ще се́рдця, іспо́лненная сострада́нієм к неви́нно стра́ждущему пра́веднику, єди́ними усти́ на́шими со умиленнем зове́м єму́ та́ко:","Ра́дуйся, вели́кий пра́ведниче, в стра́шних іскуше́ніїх всеці́ло пре́данность Го́споду сохрани́вий.","Ра́дуйся, ні от кого́же от люде́й до́браго утіше́нія ви́дівий.","Ра́дуйся, о лише́нії чад і пропавшем бога́тстві уни́нію ніка́коже преда́вийся.","Ра́дуйся, я́ко всіх нас побіжда́ти іскуше́нія сребролю́бія наставля́єши.","Ра́дуйся, я́ко ізміне́нія в небе́сних светиліх му́дро разумі́л єси́.","Ра́дуйся, я́ко ні єди́ния же приснопребива́ющия ра́дости в ми́рі сем ви́діл єси́.","Ра́дуйся, то́кмо во Єди́нім Бо́зі ра́дость і і́стину ви́ну созерца́вий.","Ра́дуйся, вели́кая і́стинная открове́нія от Бо́га прия́ти сподо́бивийся.","Ра́дуйся, я́ко лож друго́в і укоре́нія бли́жніх крі́постію ду́ха своєго́ превозмогал єси́.","Ра́дуйся, я́ко вся́кая безслове́сная похоті́нія чистото́ю се́рдця своєго́ препобеждал єси́.","Ра́дуйся, во всіх свої́х сві́тлих упованіїх ніка́коже посрами́вийся.","Ра́дуйся, я́ко в та́йни загробнаго ми́ра углублялся єси́ веянієм Ду́ха Свята́го.","Ра́дуйся, І́ове Многострада́льний, всему́ ми́ру учи́телю преди́вний."]},{"h":"Кондак 11","ps":["Пі́ніє всеумиле́нноє воспоє́м Многострада́льному, невиновность свою́ видевшему і неіскупленную греховность лю́дськую ведавшему. Зря на себі́ десни́цю Боже́ственния во́лі, в про́мисл Бо́жий о челові́ці ві́роваше пра́ведний, до́браго ча́я конця́. Разділя́юще несокрушимую сві́тлую ві́ру єго́ і упова́ніє на Бо́га, могу́щаго тя́жкую І́овлю скорб облегчи́ти, ми ку́пно с ним вопіє́м Всеблаго́му Го́споду: Аллилу́я!"]},{"h":"Ікос 11","ps":["Сві́тла озаре́нія Многострада́льнаго, сві́тла і упова́нія єго́. Вре́мені же мину́вшу умолча́ І́ов словеси́. Умолча́ша же і три дру́зі єго́ ктому́ прерікова́ти І́ову, бі бо І́ов пра́веден пред ни́ми. Глаго́леть к нему́ но́вий собесі́дник Єліу́с, єго́же рі́чі благожелательней вне́млеть пра́ведний. Не могу́щу же І́ову уразумі́ти вся словеса́ сія́ но́вая, се Госпо́дь Сам яви́ся рабу́ Своєму́ і глаго́лаше к І́ову сквозі́ бу́рю і бурния о́блаки, облича́я, і наставля́я, і ісціля́я єго́. Той же с тре́петом благогові́йним, вне́мля словесе́м Бо́жиїм, безмо́лвні мно́жицею себі́ укоря́ше, найпа́че же познава́ше, я́ко нічто́же єсть пред лице́м Бо́жиїм: і а́біє іспо́лнися душа́ пра́веднича смире́нія благода́тнаго. Ви́дяще таково́є глубо́коє пред Го́сподем смире́ніє, ра́достно поє́м І́ову сицева́я:","Ра́дуйся, вели́кий в чистоті́ речей свої́х пред Го́сподем.","Ра́дуйся, вели́кий в безмернем пред Го́сподем смире́нії.","Ра́дуйся, нічто́жество своє́ позна́вий, на уста́ же своя́ ру́ку положи́вий.","Ра́дуйся, подо́бно Авраа́му, земля́ і пе́пел себі́ іменова́вий.","Ра́дуйся, велемудре, судьби́ челові́ка в ми́рі до Христа́ на себі́ іспита́вий.","Ра́дуйся, ві́рний слуго́ Госпо́день, о своє́й му́дрости глаго́лати не дерзавий.","Ра́дуйся, ні єди́ним же словесе́м о речіх друго́в свої́х обмолвивийся.","Ра́дуйся, я́ко благогові́йно вислушал єси́ Го́спода о ди́вних ді́ліх всемогу́щества Бо́жия.","Ра́дуйся, в недомислії пред Бо́гом сокруше́нно себі́ обличи́вий.","Ра́дуйся, пред прему́дростію Єди́наго Бо́га все́ю душе́ю преклонивийся.","Ра́дуйся, в смире́нії своє́м, обличавшему тя Го́споду ра́достно внимавий.","Ра́дуйся, всіх смелих речей свої́х пред Го́сподем отреки́йся і в пра́хі і пепле раскаявийся.","Ра́дуйся, І́ове Многострада́льний, всему́ ми́ру учи́телю преди́вний."]},{"h":"Кондак 12","ps":["Благода́тная ве́лія ра́дость в се́рдці твоє́, Многострада́льне, сни́де. Ти в бу́рі і о́блаці Го́спода своєго́ ви́діл єси́. Ти облича́ющеє тебі́ сло́во Го́спода, і гні́вноє сло́во Єго́ к неві́рним друго́м твої́м сли́шал єси́. Прока́за стра́шная сойде с тебі́, І́ове, і ти вся́кая бла́га земна́я в сугу́бом числі́ от Го́спода прия́л єси́. В награ́ду за ско́рби своя́ долголі́тіє, по ми́лості Бо́жії, стяжа́л єси́, і но́вую десятерицю чад свої́х ра́достно созерца́л єси́. Воскресе́ніє со всі́ми ізбра́нними свої́ми Госпо́дь, тебі́ обітова́. Презира́я вся ско́рбі своя́, пра́ведник і ми ку́пно с ним всім се́рдцем ра́достно вопіє́м Го́споду: Аллилу́я!"]},{"h":"Ікос 12","ps":["Безмі́рния ско́рби претерпі́в і всеці́лую пре́данность всесвяті́й во́лі Бо́жії показа́в, живи́й проо́браз скорбе́й Го́спода, крестними страда́нії дия́вола побіди́вшаго, яви́лся єси́, І́ове. Пою́ще твоє́ чу́дноє житіє́, восхваля́юще безмі́рноє долготерпі́ніє твоє́, Многострада́льне, словеси́ Самого́ Го́спода, Єго́ проро́ков і апо́столов, і церко́вними словеси́ восхваля́єм тебі́ си́це:","Ра́дуйся, пра́ведниче, усти́ Бо́жиїми на всю вселе́нную хвали́мий.","Ра́дуйся, і́стину во словесі́х о Бо́зі, не я́коже твої́ лжеречивії дру́зі, яви́вий.","Ра́дуйся, я́ко Госпо́дь показа́ тя єди́на моли́твенника за дру́ги своя́.","Ра́дуйся, я́ко гріхи́ такови́ми Госпо́дь отпусти́ за моли́тви твоя́.","Ра́дуйся, Самі́м Го́сподем не єдинажди і́стинний раб Бо́жий нарече́нний.","Ра́дуйся, вели́кий Ветхозаветний моли́твенниче в ря́ду с Но́єм і Данії́лом.","Ра́дуйся, я́ко брат Госпо́день найменова́ тя о́браз злострада́нія і долготерпі́нія.","Ра́дуйся, я́ко той же апо́стол Іа́ков восхвали́ в твоє́м житії́ сла́вную кончи́ну Госпо́дню.","Ра́дуйся, я́ко Це́рков Христо́ва святу́ю кни́гу твою́ повелі́ прочитивати во дні страстни́я седьми́ці.","Ра́дуйся, прообразе страсте́й безгрі́шнаго Го́спода.","Ра́дуйся, я́ко Святи́й Златоу́ст призва́ нас о́бразом страда́ній твої́х к подража́нію твої́м по́двигом.","Ра́дуйся, я́ко в Це́ркві Святі́й і́м'я твоє́ сла́вно, досточестно і препросла́влено.","Ра́дуйся, І́ове Многострада́льний, всему́ ми́ру учи́телю преди́вний."]},{"h":"Кондак 13","ps":["О вели́кий пра́ведниче Ве́тхаго Заві́та, І́ове Многострада́льне, прийми́ на́ше поси́льноє хвале́ніє твої́х безмі́рних во сла́ву Бо́га по́двигов. Твої́ми си́льними у престо́ла Бо́жия моли́твами пода́ждь по́мощ нам, преклоняющим колі́на на́ша пред твої́ми многолетніми тя́жкими страда́ньми, тве́рдими в іскуше́ніїх і злострада́ніїх би́ти, во ві́чную загробную жизнь несокрушимо ві́ровати, на получе́ніє, по ми́лості Бо́жії, вінце́в пра́ведних на стра́шнім суді́ Христо́ві, тве́рдо наді́ятися, да і ми в обновленней пло́ті на́шей, с тобо́ю і со всі́ми святи́ми, сподо́бимся Іскупи́теля і Го́спода на́шего зрі́ти і ві́чно єму́ воспіва́ти: Аллилу́я! Аллилу́я! Аллилу́я!","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгели Бо́жії в день ні́кий предста́ша Го́сподеві, хвалу́ Єму́ вознося́ще. С ни́ми же і дия́вол при́йде. Сей послі́дній, вопрошенний Го́сподем об І́ове, нача́ть клевета́ти на пра́ведника, я́ко той чтить Го́спода земни́х ра́ди благ, і́миже Бог єго́ награди. Ми же, злу́ю дия́вольськую клевету́ на вели́каго пра́ведника с горечію воспомина́юще, та́ко І́ова восхваля́єм:","Ра́дуйся, І́ове, я́ко сам Госпо́дь найменова́ тя челові́ка непоро́чна і благочести́ва.","Ра́дуйся, от Го́спода вся бла́га земна́я приє́мий.","Ра́дуйся, мно́жество слуг імі́вий і стада́ своя́ ти́сящами ісчитивавий.","Ра́дуйся, Го́сподем дарова́нних тебі́ сино́в і дще́рей во вели́ком благоче́стії воспита́вий.","Ра́дуйся, я́ко о ча́діх свої́х вели́коє попече́ніє явля́л єси́.","Ра́дуйся, я́ко ні к чему́ же от земни́х благ се́рдцем не прилеплялся єси́.","Ра́дуйся, я́ко му́дростію своє́ю над всі́ми висо́ко стоя́л єси́.","Ра́дуйся, я́ко цар посреді́ хра́брих бил єси́.","Ра́дуйся, я́ко бил єси́ благоро́днійший су́щих от восто́к со́лнця.","Ра́дуйся, всесла́вне, Бо́жий уго́дниче і́стинний.","Ра́дуйся, вели́кая діла́ блага́я соверши́вий.","Ра́дуйся, в терпі́нії своє́м мир просвіти́вий.","Ра́дуйся, І́ове Многострада́льний, всему́ ми́ру учи́телю преди́вний."]},{"h":"Кондак 1","ps":["Ізбра́нному Го́сподем вели́кому Ве́тхаго Заві́та пра́веднику, п'я́тому от Авраа́ма Іса́вових сино́в си́нові, І́ову Многострада́льному похва́льноє воспоє́м пі́ніє: я́ко свої́ми ди́вними доброді́тельми і всім свої́м житіє́м учи́телем всей вселе́нній яви́вшемуся. Ти же, пра́ведний І́ове, прийми́ сію́ похвалу́, с любо́вію тебі́ приноси́мую, согрі́й на́ша се́рдця жела́нієм подража́ти твої́м по́двигом, да єдиноду́шно зове́м ті:","Ра́дуйся, І́ове Многострада́льний, всему́ ми́ру учи́телю преди́вний."]},{"h":"Молитва","ps":["О, вели́кий пра́ведниче, І́ове Многострада́льне, чи́стим житіє́м свої́м і свято́ю бли́зостію к Бо́гу просія́вий. Ти до Моїсе́я і Христа́ на землі́ пожи́л єси́, вся же за́повіді Бо́жия, нося́ їх в се́рдці своє́м, ісполня́л єси́. Явле́нния ми́ру чрез Христа́ і Єго́ Святи́х апо́столов та́йни, глубо́кими свої́ми открове́нії уразумі́в, прича́стник ве́яній Ду́ха Свя́та би́ти сподо́бился єси́. Вся́кия ко́зні дия́вольськия, в по́сланних тебі́ от Го́спода осо́бих іскуше́ніїх, і́стинним смире́нієм свої́м препобіди́в, о́браз злострада́нія і долготерпі́нія всей вселе́нній яви́лся єси́. Любо́во ве́лію к Бо́гу і ко всім лю́дем в безмі́рних свої́х ско́рбіх сохрани́в, чи́стим се́рдцем за гро́бом єдине́нія с Го́сподем ра́достно ожида́л єси́. Ни́ні же в селе́ніїх пра́ведних пребива́єши і Престо́лу Бо́жию предстої́ши. Усли́ши нас грі́шних і непотре́бних, пред свято́ю іко́ною твоє́ю предстоя́щих і усе́рдно ко хода́тайству твоєму́ прибіга́ющих. Моли́ Человіколю́бця Бо́га, да к ві́рі крі́пцій, непоро́чній і неруши́мій нас утверди́ть, от вся́каго зла враг ви́димих і неви́димих защити́ть, в ско́рбіх і іскуше́ніїх нам крі́пость пода́сть, в сердця́х на́ших па́м'ять сме́ртную при́сно сохрани́ть, в долготерпі́нії і братолю́бії укріпи́ть, і сподо́бит нас на стра́шнім суді́ Христо́ві до́брий отві́т да́ти і во воскреше́нней пло́ті на́шей Трієди́наго Бо́га созерца́ти і сла́ву Єму́ со всі́ми святи́ми воспіва́ти во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 1","ps":["Бога́тство ви́дів доброді́телей І́овлих, / укра́сти ко́знствоваше пра́ведних враг, / і, разтерза́в столп тілесе́, / сокро́вище не укра́де ду́ха, / обрі́те бо вооруже́ну непоро́чнаго ду́шу, / мене́ же і, обнажи́в, пліни́, / предвари́в у́бо м'я пре́жде конця́, // ізба́ви м'я льсти́ваго, Спа́се, і спаси́ м'я."]},{"h":"Кондак, глас 8","ps":["Я́ко і́стинен і пра́веден, Богочести́в і непоро́чен, / освяще́н же я́влься всесла́вне, Бо́жий уго́дниче і́стинний, / просвіти́л єси́ мир в терпі́нії твоє́м, терпіли́війший і до́блійший. // Ті́мже всі, Богому́дре, па́м'ять твою́ воспіва́єм."]},{"h":"Величання","ps":["Велича́єм тя, / святи́й пра́ведний І́ове многострада́льний, / і чтим святу́ю па́м'ять твою́, / ти бо мо́лиши за нас / Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст преподобному Іллі Макеєвському","e":"Akathist to our Venerable Father Elijah of Makeyevo","secs":[{"h":"Кондак 1","ps":["Ізбра́нний чудотво́рче і ізря́дний уго́дниче Христо́в, о́тче Іліє́ преподо́бне, всім, прибегающим к тебі́, моли́твенноє заступле́ніє. Прославля́я Го́спода, просла́вльшаго тя, со умиле́нієм похва́льная тебі́ прино́сим пі́нія:","Ра́дуйся, Іліє́ преподо́бне, те́плий моли́твенниче о душа́х на́ших."]},{"h":"Ікос 1","ps":["Вели́ка Сові́та А́нгел і ми́ра Творе́ць ізбра́ тя от літ о́трочеських на служе́ніє Себі́; ти же, послуша́ніє і́стинноє Бо́гу явля́я, на Горі́ Афо́нстій во смире́нії і і́ночестім по́двизі преби́л єси́, ми же, промишле́нію Єго́ о тебі́ див'я́щеся, с ві́рою зове́м:","Ра́дуйся, лози́ Христо́ви і́стинная поросле.","Ра́дуйся, ізмла́да путь спасе́нія ізбра́вий.","Ра́дуйся, пра́вил ві́ри ізря́дний рачи́телю.","Ра́дуйся, Ми́ра Го́рняго умильний яснозрителю.","Ра́дуйся, і́ноков пресла́вноє украше́ніє.","Ра́дуйся, в ми́ру су́щим і́стинноє поможе́ніє.","Ра́дуйся, притека́ющих к тебі́ ско́роє утіше́ніє.","Ра́дуйся, землі́ Донецькия украше́ніє.","Ра́дуйся, Іліє́ преподо́бне, те́плий моли́твенниче о душа́х на́ших."]},{"h":"Кондак 2","ps":["Ви́дя Цар Небе́сний і́стинноє жела́ніє твоє́ спасе́ніє обрісти́, приведе́ тя в сад ди́вний Бо́жієй Ма́тері — на Го́ру Афо́нськую: та́мо бо, в по́двизі смире́нія, послуша́нія, терпі́нія духо́вно возраста́я, Го́сподеві піл єси́: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум небе́сний в дар от Бо́га приї́м, оста́вил єси́ дом о́тчий і вся пре́лести ми́ра Ца́рствія ра́ди Бо́жия і пра́вди Єго́. Сего́ ра́ди, похва́льная глаго́люще, зове́м ті:","Ра́дуйся, ча́до Це́ркви Христо́ви ві́рноє.","Ра́дуйся, о́бразе кро́тости духо́вния.","Ра́дуйся, я́ко к докродетелі от ю́ности нави́кл єси́.","Ра́дуйся, я́ко в зако́ні Госпо́дні поуча́лся єси́ день і нощ.","Ра́дуйся, я́ко, оте́чество земно́є оста́вив, к небе́сному устреми́лся єси́.","Ра́дуйся, ю́ность свою́ в дар Го́сподеві принеси́й.","Ра́дуйся, от Го́спода по́мощ і прозрі́ніє духо́вноє восприє́мий.","Ра́дуйся, благодатниє да́ри, данниє тебі́, преумноживий.","Ра́дуйся, Іліє́ Преподо́бне, те́плий моли́твенниче о душа́х на́ших."]},{"h":"Кондак 3","ps":["Си́лою Ви́шняго осіне́нний, і́ночеськоє по́прище проходя́, духо́вним ві́дінієм лю́ту годи́ну во оте́чествії твоє́м прозревая, мно́гия лю́ди ко угожде́нію Бо́гу наста́вил єси́. Ми же, к заступле́нію твоєму́ притека́юще, зове́м: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я в се́рдці твоє́м і́стинную любо́в ко Творцю́ всіх, до́брим по́двигом потруди́вся, равноа́нгельськоє житіє́ стяжа́л єси́. Ми же во умиле́нії і ра́дости глаго́лем си́це:","Ра́дуйся, смире́нієм і послуша́нієм Христу́ подража́вий.","Ра́дуйся, небе́сния дарова́нія стяжа́вий.","Ра́дуйся, бді́нія і слу́жби церко́вния ревни́телю.","Ра́дуйся, бли́жнім я́ко самому́ Го́споду послужи́вий.","Ра́дуйся, а́лчущия і жаждущия духо́вно наси́тивий.","Ра́дуйся, я́ко скорб'я́щим бил єси́ утіше́ніє.","Ра́дуйся, я́ко боля́щим бил єси́ отра́да.","Ра́дуйся, о тя́жко тружда́ющихся в ні́дріх земни́х пред Бо́гом хода́таю.","Ра́дуйся, Іліє́ преподо́бне, те́плий моли́твенниче о душа́х на́ших."]},{"h":"Кондак 4","ps":["Бу́ри іскуше́ній і напа́стей, во Оте́чествії твоє́м, от нечести́вих гони́телей на Це́рков воздвиза́ємия не устраши́вся: прише́л єси́ во град Макеєвку, і світи́льник во тьмі сідя́щим яви́лся єси́. Оби́телі Го́рнія явля́яся і́стинний граждани́н, с Ви́шніми си́лами поя́ Бо́гові: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шав ско́рби і тяготу́ наро́да Бо́жия, оста́вив тишину́ безмо́лвія, любо́вію Христо́вою уязвляєм, на Него́ же все упова́ніє твоє́ возложи́л єси́: моли́ дарова́ти і нам, немощни́м, ми́лости Христа́ Бо́га, да согла́сно поє́м ті:","Ра́дуйся, і́го Христо́во на себі́ восприя́вий.","Ра́дуйся, во уді́лі Бо́жієй Ма́тері ра́бе благи́й і ві́рний.","Ра́дуйся, плоть твою́ ду́хові покори́вий.","Ра́дуйся, в со́нмі Афо́нських преподо́бних просія́вий.","Ра́дуйся, я́ко і во оте́чествії твоє́м преди́вний чудотво́рець яви́лся єси́.","Ра́дуйся, смире́нієм Го́сподеві угоди́вий.","Ра́дуйся, сосу́д, сокро́вищ доброді́телей, собо́ю яви́вий.","Ра́дуйся, в по́двизіх твої́х Царя́ Небе́снаго просла́вивий.","Ра́дуйся, Ца́рство Небе́сноє в себі́ єще́ в земні́м житії́ носи́вий.","Ра́дуйся, Іліє́ преподо́бне, те́плий моли́твенниче о душа́х на́ших."]},{"h":"Кондак 5","ps":["Богосві́тлоє світи́ло яви́ тя Госпо́дь: іску́сний бо ді́латель у́мния моли́тви явля́яся, істо́чник приснотеку́щия благода́ті обрі́лся єси́; і душі́ отча́янних, сві́том і́стинния ві́ри озари́в, ко Христу́ приве́л єси́; поя́ Тому́ піснь: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше лю́діє тя, о́тче Іліє́, ве́лія моли́твенника, со тща́нієм притека́ху к тебі́, я́ко же дре́вле наро́д Ізра́їля ко проро́ку Бо́жию Ілії́; ти же, си́лу ду́ха пророча в себі́ нося́й, ві́рноє заступле́ніє ча́дом Це́ркві бил єси́; не оста́ви і нас, грі́шних, вопію́щих ті такова́я:","Ра́дуйся, моли́твенниче о нас дерзнове́нний.","Ра́дуйся, си́лою моли́тви дре́внему проро́ку подо́бний.","Ра́дуйся, ізря́дним смире́нієм твої́м духо́в зло́би посрами́вий.","Ра́дуйся, незло́бієм твої́м мно́гія кро́тости научи́вий.","Ра́дуйся, денно і но́щно псалмопі́нієм благоухавий.","Ра́дуйся, чистоти́ духо́вния і тіле́сния усе́рдний храни́телю.","Ра́дуйся, Пусти́ні Афо́нськия я́ко ши́пок благово́нний украше́ніє.","Ра́дуйся, я́ко вся проси́моє от Го́спода получи́вий.","Ра́дуйся, Іліє́ преподо́бне, те́плий моли́твенниче о душа́х на́ших."]},{"h":"Кондак 6","ps":["Віща́єть цві́тник духо́вний - Гора́ Свята́я труди́ і по́двиги твоя́, духоно́сне о́тче наш Іліє́; бді́нієм бо, поще́нієм, самоуничиженієм, ве́тхаго в себі́ побіжда́я, си́лою Ду́ха Свята́го обле́клся єси́, я́ко же Єлисей ми́лотію Ільиною, і со А́нгели воспіва́єши: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ в се́рдці твоє́м світ любве́ Боже́ственния, Богови́дцю Мойсе́ю уподобля́яся, во оте́чество твоє́ прише́л єси́, да лю́ди ко Оте́честву Небе́сному направиши; ми же, упова́я на заступле́ніє твоє́, взива́єм си́це:","Ра́дуйся, храм нерукотво́рний в се́рдці твоє́м возведи́й.","Ра́дуйся, мно́жество хра́мов рукотворних во гра́ді твоє́м предрекий.","Ра́дуйся, смире́нієм облеки́йся я́ко ри́зою нетлі́нною.","Ра́дуйся, во оби́телі проро́ка Ілії́ житіє́м твої́м просія́вий.","Ра́дуйся, во́лю свою́ во́лі Христо́вой поработи́вий.","Ра́дуйся, не іми́й гді глави́ преклони́ти, мно́гія духо́вно обогати́вий.","Ра́дуйся, по сло́ву Христо́ву, люби́ти враго́в научи́вий.","Ра́дуйся, я́ко се́рдця гоня́щих тя кро́тостію твоє́ю ум'ягчивий.","Ра́дуйся, Іліє́ преподо́бне, те́плий моли́твенниче о душа́х на́ших."]},{"h":"Кондак 7","ps":["Хотя́й Человіколю́бець Госпо́дь всім спасти́ся і в ра́зум і́стини прийти́, яви́ тя світи́льника землі́ на́шея; научи́л бо мно́гія любві́ Бо́жієй і благоче́стію; ті́мже і нас си́рих, во тьмі гріхо́вній блужда́ющих, не оста́ви, но моли́ за ни Христа́ Бо́га, да поє́м Єму́: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́ваго тя ізбра́нника Бо́жия ви́дяще: немощни́я ісціля́юща, утіше́ніє і моли́твенноє предста́тельство малоду́шним подаю́ща; ті́мже і за преді́ли гра́да твоєго́ ізи́де віща́ніє чуде́с твої́х; ми же, ча́да твоя́, хвалу́ тебі́ принося́, та́ко рцем:","Ра́дуйся, наста́вниче наш прелюбе́зний.","Ра́дуйся, прозорли́вий ціли́телю неду́гов душе́вних і тіле́сних.","Ра́дуйся, помо́щниче ско́рий в біда́х су́щим.","Ра́дуйся, гряду́щая, я́ко настоя́щая, віща́вий.","Ра́дуйся, а́нгелов собесі́дниче пресла́вний.","Ра́дуйся, тьмо́ю безбо́жия осліпле́нния сві́том ісполне́нія Єва́нгельських за́повідей просвіти́вий.","Ра́дуйся, житіє́м твої́м милосе́рдія і доброді́телі пречу́дний пропові́дниче.","Ра́дуйся, моли́твенному ді́ланію мно́гія научи́вий.","Ра́дуйся, Іліє́ преподо́бне, те́плий моли́твенниче о душа́х на́ших."]},{"h":"Кондак 8","ps":["Стра́нноє явле́ніє ви́дяще, Іліє́ преподо́бне, притекшу тебі́ ве́тхим ста́рцем во оте́чествіє твоє́, да лю́дем послу́жиши, желі́зними бо око́ви взор твой на мир сей затвори́вий; среди́ жите́йськаго мо́ря, я́ко в безмо́лвній пусти́ні, преби́л єси́, путі́ ко Го́рнему Ієрусали́му взиску́я, в нем же предстоя́, с весе́лієм поє́ши: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь єси́ жела́нієм небе́сним іспо́лненний, не оста́ви і нас, моли́твою твоє́ю ограждаємих, ми же, наде́ждою обле́кшеся о заступле́нії твоє́м пред Влади́кою всіх, с любо́вію і ра́достію велича́єм тя, зову́ще:","Ра́дуйся, зрі́нієм ума́ херуви́мом уподобившийся.","Ра́дуйся, серафи́мом, пламенеющим се́рдцем ко Го́споду, подо́бен би́вий.","Ра́дуйся, усе́рдно чту́щих тя хода́таю непости́дний.","Ра́дуйся, мглу страсте́й душевре́дних по́мощію Бо́жиєю побіди́вий.","Ра́дуйся, правові́рним во́їном духо́вний спобо́рниче.","Ра́дуйся, супоста́ти моли́твою твоє́ю посяцяяй.","Ра́дуйся, ми́лость Всеви́шняго к ча́дом твої́м приклони́вий.","Ра́дуйся, і о всем ми́рі хода́таю неуси́пний.","Ра́дуйся, Іліє́ преподо́бне, те́плий моли́твенниче о душа́х на́ших."]},{"h":"Кондак 9","ps":["Вся́коє єстество́ челові́чеськоє диви́ться, преподо́бне Іліє́: ка́ко нощними бді́ніями пусти́ню озаря́я, в по́двизі же моли́твенном не ослабен до конця́ претруднаго твоєго́ житія́ преби́л єси́: умоли́ Го́спода Сил стяжа́ти доброді́тель сію́ і нам недосто́йним, пою́щим Єму́: Аллилу́я."]},{"h":"Ікос 9","ps":["Вити́йство вся́коє не мо́жеть ізрещи́ любо́в твою́; мно́гим бо, притекающим к тебі́ в недоумі́нії, благи́й сові́т по́дал єси́, мно́гія заблуждающаяся кро́тко вразуми́л єси́, боля́щим врач явля́яся, і по сме́рті прибіга́ющих к твоєму́ хода́тайству не оставля́єши; ми же с упова́нієм зове́м ті:","Ра́дуйся, в доброді́телі дре́внім отцям подража́вий.","Ра́дуйся, на су́єтний мир єди́ним то́кмо о́ком взиравий.","Ра́дуйся, к Ми́ру Го́рнему у́мний твой взор впери́вий.","Ра́дуйся, сві́том Бо́жієй Благода́ті осія́нний.","Ра́дуйся, око́вами смире́нія доброді́телі твоя́ сокри́вий.","Ра́дуйся, по сло́ву Христо́ву: \"я́ко нічто́же єсть та́йно і́же не ста́неть я́вним\", на себі́ яви́вий.","Ра́дуйся, жертвенною любо́вію к бли́жнему Небе́сния Оби́телі унаслі́довавий.","Ра́дуйся, житіє́м твої́м Го́сподеві угоди́вий.","Ра́дуйся, Іліє́ преподо́бне, те́плий моли́твенниче о душа́х на́ших."]},{"h":"Кондак 10","ps":["Спасти́ся хотя́щим путь і́стинний приме́ром твої́м яви́вий; отрешатися суєти́ ми́ра сего́ і нам помози́: обурева́ємим проти́ву ко́знем дия́вольским ста́ти і ум свой, подо́бно тебі́, вмі́сто суєтного ми́ра ко Го́рнім Оби́телем возвісти́, іді́же со всі́ми святи́ми поє́ши хвале́бную піснь: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ несокруши́мая яви́лся єси́, о́тче Іліє́ преподо́бне, необори́мим бо засту́пником предстої́ши у Престо́ла Го́спода Сла́ви с Пречи́стой Госпоже́ю Богоро́дицею і всі́ми святи́ми, за ни моля́ся: Ми же, к ра́ці с моща́ми твої́ми притека́юще, уми́льно глаго́лем ті такова́я:","Ра́дуйся, при жи́зні нікого́же із приходя́щих к по́мощі твоє́й не отри́нувий.","Ра́дуйся, і по преставле́нії твоє́м нас не оставля́ющий.","Ра́дуйся, ізнемога́ющим духо́вно помошниче ско́рий.","Ра́дуйся, страждующим тіле́сно ціли́телю неотложний.","Ра́дуйся, свя́занним ду́хом зло́би поднебесной ско́роє свобожде́ніє.","Ра́дуйся, жертвенною любо́вію іспо́лненний.","Ра́дуйся, фимія́м моли́тв твої́х за ни пред Престо́лом Бо́жиїм воскуряющий.","Ра́дуйся, сосу́де Благода́ті Бо́жієй.","Ра́дуйся, Іліє́ преподо́бне, те́плий моли́твенниче о душа́х на́ших."]},{"h":"Кондак 11","ps":["Піснь достохва́льную Пресвяті́й Тро́йце житіє́м твої́м прине́сл єси́; і во вре́м'я отше́ствія твоєго́ дух твой в ру́ці Бо́га Жива́го с моли́твою на усті́х пре́дал єси́, о́тче преподо́бне; от ю́ности бо твоєя́ Го́сподеві нелі́ностно потруди́вся, віне́ць нетлі́нний стяжа́в, во оби́теліх небе́сних всели́лся єси́, іді́же со а́нгели поє́ши: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоно́сний світи́льник зрим тя, преподо́бне о́тче, равноа́нгельно бо на землі́ пожи́л єси́, і по отше́ствії твоє́м моли́твенно с на́ми пребива́єши; ми же, взира́я на труди́ і по́двиги твоя́, похва́льная тебі́ прино́сим пі́нія:","Ра́дуйся, віне́ць безсме́ртія от Всеблага́го Бо́га восприя́вий.","Ра́дуйся, цільби́ по моли́твам твої́м подаю́щий.","Ра́дуйся, ізлія́нная пучи́но благода́тних даро́в.","Ра́дуйся, моли́твенно призива́ющих тя ско́ро посіща́яй.","Ра́дуйся, ди́вная при жи́зні твоє́й яви́вий.","Ра́дуйся, і по преставле́нії твоє́м неоску́дную по́мощ нам от Бо́га подаю́щий.","Ра́дуйся, со А́нгели у престо́ла Бо́жия за ни предстоя́щий.","Ра́дуйся, нетлі́ніє стяжа́вий і нам сві́тлий путь ко спасе́нію указу́ющий.","Ра́дуйся, Іліє́ преподо́бне, те́плий моли́твенниче о душа́х на́ших."]},{"h":"Кондак 12","ps":["Благода́ть Пресвята́го Ду́ха іспроси́ нам, уго́дниче Христо́в Іліє́ достохва́льне, ві́ми бо я́ко мно́го мо́жеть моли́тва пра́веднаго ко благосе́рдію Влади́ки; да небезплодно в нас бу́деть сі́м'я Святи́я Ві́ри. Умоли́ Человіколю́бця Бо́га дарова́ти нам і́стинний плод покая́нія, с упова́нієм зовущим: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще твоє́ прославле́ніє от Го́спода, ублажа́єм тя і ми, преподо́бне о́тче Іліє́; со умиле́нієм взира́юще, ка́ко обріто́хом тя многомо́щна моли́твенника і хода́тая о нас недосто́йних; сла́в'яще ми́лость Всесвята́го Бо́га, к нам явле́нную, прино́сим ті такова́я:","Ра́дуйся, Восто́ка Незаходи́маго заре́ присносіяющая.","Ра́дуйся, даро́в Єго́ сокро́вище многоразли́чноє.","Ра́дуйся, си́лою Бо́жиєю мно́гія чудеса́ соді́лавий.","Ра́дуйся, щедро́т і ми́лости Єго́ струє́ неізсяка́ємая.","Ра́дуйся, сострада́нія і любве́ явле́ніє пресла́вноє.","Ра́дуйся, сві́тлий у́ме, озаре́нний Сві́том Невече́рнім.","Ра́дуйся, ленящаяся на угожде́ніє Бо́гу нра́вом твої́м на ісправле́ніє подви́гнувий.","Ра́дуйся, на путь ісполне́нія за́повідей Христо́вих мно́гія наста́вивий.","Ра́дуйся, Іліє́ преподо́бне, те́плий моли́твенниче о душа́х на́ших."]},{"h":"Кондак 13","ps":["О преди́вний і пречу́дний о́тче наш Іліє́, прими́ сіє́ с любо́вію приноси́моє тебі́ ма́лоє пі́ніє, і, моли́твами твої́ми неду́г душе́вних і тіле́сних нас свобожда́я, гряду́щих ві́чних мук ізба́ви, да с тобо́ю непреста́нно воспіва́єм: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["Вели́ка Сові́та А́нгел і ми́ра Творе́ць ізбра́ тя от літ о́трочеських на служе́ніє Себі́; ти же, послуша́ніє і́стинноє Бо́гу явля́я, на Горі́ Афо́нстій во смире́нії і і́ночестім по́двизі преби́л єси́, ми же, промишле́нію Єго́ о тебі́ див'я́щеся, с ві́рою зове́м:","Ра́дуйся, лози́ Христо́ви і́стинная поросле.","Ра́дуйся, ізмла́да путь спасе́нія ізбра́вий.","Ра́дуйся, пра́вил ві́ри ізря́дний рачи́телю.","Ра́дуйся, Ми́ра Го́рняго умильний яснозрителю.","Ра́дуйся, і́ноков пресла́вноє украше́ніє.","Ра́дуйся, в ми́ру су́щим і́стинноє поможе́ніє.","Ра́дуйся, притека́ющих к тебі́ ско́роє утіше́ніє.","Ра́дуйся, землі́ Донецькия украше́ніє.","Ра́дуйся, Іліє́ преподо́бне, те́плий моли́твенниче о душа́х на́ших."]},{"h":"Кондак 1","ps":["Ізбра́нний чудотво́рче і ізря́дний уго́дниче Христо́в, о́тче Іліє́ преподо́бне, всім, прибегающим к тебі́, моли́твенноє заступле́ніє. Прославля́я Го́спода, просла́вльшаго тя, со умиле́нієм похва́льная тебі́ прино́сим пі́нія:","Ра́дуйся, Іліє́ преподо́бне, те́плий моли́твенниче о душа́х на́ших."]},{"h":"Молитва","ps":["О свяще́нная главо́, о́тче Іліє́ преподо́бне, уго́дниче преізря́дний Госпо́день, те́плий моли́твенниче о всіх, к по́мощі твоє́й с ві́рою прибіга́ющих, малоду́шних уті́шителю і всім, в ско́рбіх і болі́зніх пребива́ющим, ско́рий помо́щниче і засту́пниче.","Помози́ нам, грі́шним і уни́лим, бу́рею сомні́ній в суєті́ жите́йськаго мо́ря потопля́ємим, дости́гнути ти́хаго приста́нища - Небе́снаго Ца́рствія.","Умоли́ Го́спода, вся́чеських благ Пода́теля, получи́ти проще́ніє мно́гих на́ших гріхо́в. Наста́ви нас, мно́гими соблазнами ми́ра сего́ іскуша́ємих, На путь смире́нія, терпі́нія, чистоти́ духо́вния і тіле́сния і іскренней любві́ к Бо́гу і бли́жнім, да не поги́бнем лю́ті без покая́нія.","Свя́тче Бо́жий, подо́бні древлему проро́ку, тезоімени́тому Ілії́, ре́вностію об'ятий по Го́споді Бо́зі Вседержителе, да́руй І нам разсла́бленним дух ре́вности ко спасе́нію, укріпи́ се́рдця на́ша в пра́вой ві́рі, Це́рков Святу́ю сохрани́ от вся́каго м'яте́жа і раско́ла. Град твой, Оте́чество на́ше і вся́кую страну́ христия́нськую огради́ і сохрани́ моли́твами твої́ми от гла́да, пото́па, наше́ствія іноплеме́нних і междоусо́бния бра́ні; ста́рость поддержи́, ю́ность уцілому́дри, младе́нці воспита́й, на вся́кую доброді́тель нас грі́шних наста́ви; кончи́ну житія́ на́шего прича́стну Святи́х Та́їн Христо́вих би́ти сподо́би, да с ві́рою і любо́вію просла́вим со а́нгельськими си́лами во Ца́рствії Небе́снім, іді́же і ти пребива́єши, Бо́га, в Тро́йці сла́вимаго Отця́, і Си́на, і Свята́го Ду́ха, во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["От ю́ности ми́ра суєту́ оста́вив, / на Афо́нськую го́ру прише́л єси́, / іді́же а́нгельськоє житіє́ явля́я, / Бо́гу нелі́ностно служа́ше, / да́ри благода́тния от Него́ восприя́в. / Во оте́чество же своє́ прише́дши, / мно́гим путь во спасе́ніє бил єси́, / чудотво́рець преди́вний і уті́шитель малоду́шних явля́яся, / гра́ду Макеєвке похвало́ і утвержде́ніє, / Іліє́ преподо́бне, / моли́ Христа́ Бо́га / о ві́рою і любо́вію чту́щих тя."]},{"h":"Кондак, глас 4","ps":["Днесь сві́тло лику́єть град твой, / о́тче Іліє́ преподо́бне, / соверша́юще свяще́нную па́м'ять твою́. / Ми же, ча́да твоя́, / умиле́нно принадающе к моще́м твої́м, / взива́єм сипе: / моли́ся, уго́дниче Христо́в, / мир Це́ркві і Оте́честву на́шему дарова́ти / і душа́м на́шим вел ію ми́лость."]},{"h":"Величання","ps":["Ублажа́єм тя, / преподо́бне о́тче наш Іліє́, / і чтим святу́ю па́м'ять твою́, / наста́вниче мона́хов / і собесі́дниче а́нгелов."]}],"notes":[]},{"u":"Акафіст праведній Іуліанії Лазаревській, Муромській","e":"Akathist to the Righteous Juliana of Lazarevo, of Murom","secs":[{"h":"Кондак 1","ps":["Ізбра́нная Бо́гом, пра́ведная і ми́лостивая Іулія́ніє, в землі́ Муромстей я́ко звізда́ пресві́тлая возсія́вшая, ни́щих пита́тельнице і о лю́діх ко Христу́ Бо́гу моли́твеннице, прославля́юще просла́вльшаго тя Го́спода, похва́льними пі́сньми воспої́м тя, о́браз по́двига духо́внаго всім жена́м ру́ським показа́вшую. Ти же, я́ко іму́щая дерзнове́ніє ко Го́споду, моли́твами твої́ми от вся́ких бід свободи́ нас, с любо́вію зову́щих:","Ра́дуйся, ми́лостивая Іулія́ніє, жен ру́ських похвало́ і украше́ніє."]},{"h":"Ікос 1","ps":["А́нгельськоє і́ночеськоє житіє́ от ю́ности возлюби́ла єси́, блаже́нная Іулія́ніє, і Бо́гу єди́ному порабо́тати всім се́рдцем возжела́ла єси́. Оба́че смотре́нієм Свої́м ін путь спасе́нія предуста́ви тебі́ Госпо́дь, є́же в бра́ці честні́м святи́м житіє́м Єму́ угоди́ти. Сего́ ра́ди, єгда́ дости́гла єси́ во́зраста бра́чна, вдана́ била́ єси́ му́жу добродетельну і бога́ту, і́менем Гео́ргію, і вінча́ни би́сте в це́ркві пра́веднаго Ла́заря. Тогда́ всі сро́дниці супру́га дивля́хуся ра́зуму твоєму́, смире́нію і послуша́нію. Ми же таково́му чу́дному про́мислу Бо́жию див'я́щеся, ра́достно взива́єм ті:","Ра́дуйся, роди́телей нищелюбивих Іусти́на і Стефани́ди ча́до благослове́нноє.","Ра́дуйся, ма́тере лиши́вшися, вні кро́ва оте́чеськаго во ві́рі і благоче́стії воспитанная.","Ра́дуйся, звіздо́ пресві́тлая, в селе́нії Ла́зареві Бо́гом возжже́нная.","Ра́дуйся, лиліє благоуха́нная, в тишині́ лісо́в му́ромських возращенная.","Ра́дуйся, сверстником твої́м о́браз благонра́вія показа́вшая.","Ра́дуйся, а́гнице чи́стая, і́ночеськаго чи́на ізмла́да іска́вшая.","Ра́дуйся, послушнице кро́ткая, Бо́жиєю во́лею му́жу вруче́нная.","Ра́дуйся, во смире́нії і доброді́ланії жизнь свою́ проводившая.","Ра́дуйся, любо́в нелицемі́рную к Бо́гу і бли́жнім яви́вшая.","Ра́дуйся, Пресвято́ю Богоро́дицею возлю́бленная.","Ра́дуйся, а́нгельськи на землі́ пожи́вшая.","Ра́дуйся, я́ко ни́ні со А́нгели лику́єши в оби́теліх небе́сних.","Ра́дуйся, ми́лостивая Іулія́ніє, жен ру́ських похвало́ і украше́ніє."]},{"h":"Кондак 2","ps":["Ви́дя враг ро́да христия́нськаго твоя́ благотворе́нія, всено́щная бді́нія і поще́нія, возжела́ ду́шу твою́ смути́ти страхованії. Ти же, ма́ти Іулія́ніє, всю наде́жду на Бо́га і Пречи́стую Єго́ Ма́тер возложи́вши, призвала́ єси́ на по́мощ святи́теля Никола́я Чудотво́рця. І яви́ся святи́й Нико́ла, держа́ кни́гу вели́ку, разгна́ бі́си, благослови́ тя і рече́: «Дщи моя́, мужа́йся і кріпи́ся, Христо́с бо мні повелі́ тя соблюда́ти от бісо́в і злих челові́к». Ті́мже Бо́га благодаря́щи, ра́достно пі́ла єси́ а́нгельськую піснь: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум челові́чеський недоуміва́єть, ка́ко ти, блаже́нная ма́ти, в суєті́ жите́йстей пребива́ющи, душе́ю в черто́зіх небе́сних нем'яте́жно обита́ла єси́, і бога́тство ізоби́льноє іму́щи, я́ко чужде́є і Бо́гом тебі́ вруче́нноє восприймала єси́; в бра́ці же честні́м крест свой поне́сши, висоту́ доброді́телей показа́ла єси́ і ча́да своя́ во ві́рі і благоче́стії воспита́ла єси́. Ми же, такову́ю тебі́ от Бо́га да́нную благода́ть чту́ще, с любо́вію велича́єм тя:","Ра́дуйся, с супру́гом твої́м в любві́ і благоче́стії пожи́вшая.","Ра́дуйся, моли́твою і кро́тостію му́жа твоєго́ спасавшая.","Ра́дуйся, чад твої́х в ді́ланії добра́ утверди́вшая.","Ра́дуйся, богому́дрими глаго́ли їх просвіти́вшая.","Ра́дуйся, госпоже́ ми́лостивая, слуга́м свої́м єва́нгельськи послужи́вшая.","Ра́дуйся, пра́ведная ма́ти, в ми́рі пожи́вши, свя́тости удостоєнная.","Ра́дуйся, явле́нієм святи́теля Никола́я обра́дованная.","Ра́дуйся, от духо́в нечи́стих їм спасе́нная.","Ра́дуйся, бісо́вськая наважде́нія му́жественно претерпі́вшая.","Ра́дуйся, наві́ти і ко́зні лука́ваго разорившая.","Ра́дуйся, моли́тви умиле́нния, я́ко кади́ло благово́нноє, Бо́гу приносившая.","Ра́дуйся, в ми́рі живу́щим ко спасе́нію путеводи́тельнице.","Ра́дуйся, ми́лостивая Іулія́ніє, жен ру́ських похвало́ і украше́ніє."]},{"h":"Кондак 3","ps":["Си́ла Всеви́шняго дарова́ тебі́ крі́пость в терпі́нії тя́жкий свой крест понести́, єгда́ чи́стия душі́ чети́ріх сино́в і двух дще́рей твої́х, во младе́нчестві, я́ко пти́ці небе́сния к Бо́гу возлеті́ша. Ти же, о богому́драя ма́ти, сама́ я́ко го́рлиця Бо́жия, к селеніям ра́йським душе́ю устремляющися, за вся благодарила єси́ Бо́га і оста́вшихся в живи́х чад твої́х любо́вію і моли́твою назидала єси́, о усо́пших же с І́овом пра́ведним уми́льні глаго́лющи: «Госпо́дь даде́, Госпо́дь от'я. Ни́ні же ча́дця моя́ ма́лая Бо́га со А́нгели сла́в'ять, о свої́х же роди́теліх те́плі Єго́ умоля́ють, от чи́стих усте́н принося́щи серафи́мськую піснь: Аллилу́я»."]},{"h":"Ікос 3","ps":["Імі́ющи се́рдце всіх милующеє, благода́тния любве́ преісполненноє, воі́стину ма́ти ми́лостивая, Іулія́ніє, яви́лася єси́ во дні Бо́жия посіще́нія страни́ Ру́ськия тя́жким гла́дом. Ти бо, сама́ в ну́жді пребива́ющи, все імі́ніє своє́ раздала́ єси́, хлі́бом а́лчущих пита́ющи і ми́лостині їм даю́щи, і всім стра́ждущим била́ єси́ покро́в і утіше́ніє. Ті́мже і ми, ми́лості і заступле́нія твоєго́ прося́ще в ну́ждах і печа́ліх на́ших, вопіє́м із глубини́ серде́чния:","Ра́дуйся, я́ко зла́то в горни́лі, огне́м скорбе́й і іскуше́ній іспитанная.","Ра́дуйся, крест твой с терпі́нієм і ра́достію поне́сшая.","Ра́дуйся, успе́ніє близьких, я́ко разлуче́ніє кра́ткоє приє́млющая.","Ра́дуйся, Ца́рства Небе́снаго от Го́спода їм просившая.","Ра́дуйся, во дні гла́да сві́том любве́ твоєя́ зе́млю Ру́ськую озари́вшая.","Ра́дуйся, хлі́бом пита́ющи а́лчущих, от сме́рти і мук їх ізбавлявшая.","Ра́дуйся, ми́лості і любве́ к стра́ждущим лю́дем преісполненная.","Ра́дуйся, во о́бразі нищія бра́тії ми́лость Христу́ Бо́гу на́шему сотворившая.","Ра́дуйся, сокро́вище ми́лости неістощи́моє.","Ра́дуйся, я́ко імі́ніє твоє́ разда́вши, обріла́ єси́ бога́тство небе́сноє.","Ра́дуйся, пи́ще і отра́до а́лчущих і жа́ждущих.","Ра́дуйся, спасе́нія мно́гих душ челові́чеських вино́внице.","Ра́дуйся, ми́лостивая Іулія́ніє, жен ру́ських похвало́ і украше́ніє."]},{"h":"Кондак 4","ps":["Бу́рею бід і напа́стей іспо́лнися оте́чество на́ше, єгда́ по гріхо́м свої́м лю́діє я́звою сме́ртною нака́зани би́ша і оттого мно́зі в домі́х запирахуся, і уя́звленних сро́дников к себі́ не пущаху, і ри́зам їх не прикаса́хуся. Ти же, блаже́нная ма́ти, боля́щих свої́ма рука́ма в ба́ні омива́ющи, молила єси́ Бо́га об ісціле́нії їх, і а́ще кто умира́ше, во ві́чний поко́й їх провожда́ющи, на погребе́ніє сре́бреники давала єси́ і мно́гу ми́лостині і сорокоусти по ним твори́ла єси́. Ни́ні же, приє́мши от Бо́га благослове́нноє ца́рство, іді́же ність болі́знь, ні печа́ль, ні воздиха́ніє, непреста́нно поє́ши Єму́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шащи о люті́йшем уби́йстві си́на твоєго́, уязви́лася єси́ ма́тернім се́рдцем, богому́драя Іулія́ніє. Оба́че не та́ко сме́ртію єго́ огорчилася єси́, коли́ко о внезапней кончи́ні опечалилася єси́; єще́ о уби́йці єго́ зіло́ сокрушилася єси́. Єгда́ же і други́й син твой возлю́бленний убіє́н бисть в служе́нії ратнем, со слеза́ми умиле́нними воспомина́ющи страда́нія Самаго́ Христа́, в моли́твах те́плих к Нему́ укреплялася єси́ і скорб свою́ ра́достію растворяла єси́, я́ко би́ти тебі́, по сло́ву Апо́стола, во о́браз всім ві́рующим. Ми же, ві́рі твоє́й смире́нній див'я́щеся, с любо́вію велича́єм тя:","Ра́дуйся, ма́ти многострада́льная, чад твої́х усо́пших в ру́ці Го́спода вручившая.","Ра́дуйся, уби́йцю си́на твоєго́, я́коже Христо́с расп'явших Єго́, прости́вшая.","Ра́дуйся, і́го Христо́во ле́гкоє і благо́є на себі́ носи́вшая.","Ра́дуйся, бли́жнія твоя́ па́че себі́ возлюби́вшая.","Ра́дуйся, мно́гі ско́рбі с благодаре́нієм Бо́гу претерпі́вшая.","Ра́дуйся, скорб'я́щих ра́досте і утіше́ніє.","Ра́дуйся, терпі́нієм і моли́твою ми́ра сего́ зло́бу побеждавшая.","Ра́дуйся, во єди́нім Го́споді утіше́ніє обрі́тшая.","Ра́дуйся, посіти́тельнице в не́мощіх лежа́щих.","Ра́дуйся, прибі́жище на́ше в ско́рбіх і болі́зніх.","Ра́дуйся, єле́й утіше́нія всім пла́чущим і нуждающимся показа́вшая.","Ра́дуйся, і сама́ в ско́рбіх на́ших сострада́ти нам могу́щая.","Ра́дуйся, ми́лостивая Іулія́ніє, жен ру́ських похвало́ і украше́ніє."]},{"h":"Кондак 5","ps":["Боготе́чній звізді́ яви́лася єси́ подо́бна, град Му́ром і всю зе́млю на́шу благода́тію озаря́ющей, пра́ведная Іулія́ніє, і світи́ши всім, і наставля́єши всіх ча́ющих спасе́ніє душі́ в ми́рі многом'яте́жнім обрісти́. Сего́ ра́ди і нас поуча́єши, я́ко єди́н єсть і́стинний путь ко спасе́нію в ми́рі сем, є́же вся с ві́рою, наде́ждою і любо́вію терпі́ти Христа́ ра́ди, воспіва́я Єму́ піснь: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дя супру́г твой, я́ко жаждеши скри́тися от ми́ра в оби́телі іночестей, умоляше тя не оставля́ти єго́ с п'ятери́цею чад. Ти же, кро́ткая а́гнице, во́лю свою́ смире́нно отсіка́ющи, послушливо рекла́ єси́: «Во́ля Госпо́дня да бу́деть», і па́ки восприя́вши да́нний ті от Бо́га крест по́двига в сою́зі брачнем, па́че умно́жила єси́ бді́нія, пости́ і моли́тви, в це́рков ходя́щи к заутрени і к литургі́ї, і дом свой держа́щи, і вдова́м і сирота́м помога́ющи. Ми же, помина́юще доброді́телі твоя́, со умиле́нієм взива́єм ті:","Ра́дуйся, любо́в твою́ к Бо́гу любо́вію к бли́жнім показа́вшая.","Ра́дуйся, в неустанней моли́тві дні і нощі́ проводившая.","Ра́дуйся, роди́телей супру́га твоєго́ любо́вію і послуша́нієм почтившая.","Ра́дуйся, ча́дом твої́м ма́ти любвеоби́льная.","Ра́дуйся, о́бразе і́стиннаго бра́ка христия́нськаго с супру́гом твої́м яви́вшая.","Ра́дуйся, благочести́вим семейством ми́ра і бла́га пода́тельнице.","Ра́дуйся, воздержа́нія і чистоти́ і́стинная храни́тельнице.","Ра́дуйся, доброді́тельному і пра́ведному житію́ наста́внице.","Ра́дуйся, я́ко свя́то і богоуго́дно на землі́ пожила́ єси́.","Ра́дуйся, я́ко мног плод доброді́телей Бо́гу принесла́ єси́.","Ра́дуйся, о всіх і́м'я твоє́ призива́ющих дерзнове́нная предста́тельнице.","Ра́дуйся, оте́честву твоєму́ пресві́тлий світи́льниче.","Ра́дуйся, ми́лостивая Іулія́ніє, жен ру́ських похвало́ і украше́ніє."]},{"h":"Кондак 6","ps":["Пропові́дник житія́ твоєго́ многоско́рбнаго яви́ся твой син Каллистра́ть, і́же пові́да ми́ру та́йний і ди́вний по́двиг твой, ка́ко ти по преставле́нії супру́га твоєго́ вся я́же в ми́рі отве́ргши, єди́ному Бо́гу возжелі́ла єси́ угожда́ти, і постя́щися і ми́лостиню безмі́рну творя́щи, сама́ без те́плия оде́жди зимо́ю ходи́ла єси́, в сапоги́ боси́ма нога́ма обувающися. Ті́мже о тебі́, пра́ведная Іулія́ніє, ра́дується град Му́ром і сві́тло торжеству́єть Це́рков Бо́жия, воспіва́юще Подвигополо́жнику Бо́гу піснь: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ благода́ть в се́рдці твоє́м сві́том до́брих діл, о ма́ти свята́я. «Не мо́жеть град укри́тися, верху́ гори́ стоя́», та́ко і ти, до́брим по́двигом подвиза́ющися, вмі́сто бога́тства ізбра́вши нищету́, вмі́сто поко́я труд, моли́тву і нощна́я бді́нія; ті́мже і в черто́ги небе́сния с му́дрими ді́вами прия́та би́ти сподо́билася єси́, іді́же не престає́ши моли́тися о всіх чту́щих па́м'ять твою́ і вопію́щих тебі́ та́ко:","Ра́дуйся, заре́ тихокрилая, Му́ромський край осіявшая.","Ра́дуйся, ві́си Ла́заревськия покро́ве богодарова́нний.","Ра́дуйся, с му́дрими ді́вами єле́й до́брих діл собра́вшая.","Ра́дуйся, любо́в небе́сную в себі́ поі́стині показа́вшая.","Ра́дуйся, плоть твою́ ду́хові покорившая.","Ра́дуйся, нестяжа́нія о́браз нам яви́вшая.","Ра́дуйся, мно́гими доброді́тельми ду́шу свою́ украси́вшая.","Ра́дуйся, лю́б'ящих тя неізрече́нния ра́дости ісполня́ющая.","Ра́дуйся, Бо́жия ізбраннице, на висоту́ соверше́нства возше́дшая.","Ра́дуйся, кро́ткая голуби́це, к небе́сній висоті́ возлетевшая.","Ра́дуйся, ми́лости вели́кия і сострада́нія храни́тельнице.","Ра́дуйся, усе́рдная і благоприя́тная о душа́х на́ших моли́твеннице.","Ра́дуйся, ми́лостивая Іулія́ніє, жен ру́ських похвало́ і украше́ніє."]},{"h":"Кондак 7","ps":["Хотя́щи по кончи́ні супру́га твоєго́ все́ю душе́ю Бо́гу послужи́ти, а́нгельському житію́ поревнова́ла єси́, пра́ведная Іулія́ніє, по́двиги к по́двигом прилагала єси́, па́че же Христу́ подража́ющи, во смире́нії, любві́ і кро́тости подвиза́лася єси́, ше́ствующи путе́м спасе́нія, ко го́рнему Небе́сному оте́честву ві́дущему, воспіва́ющи непреста́нно а́нгельськую піснь: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́воє зна́меніє висоти́ житія́ твоєго́ показа́ всіх творе́ць і Влади́ка Госпо́дь: оде́жди бо те́плия ни́щим разда́вши, зимо́ю студеною в це́рков ходи́ти преста́ла єси́, но в до́му возносила єси́ моли́тви к Бо́гу. Во єди́но же у́тро прише́дий в храм пра́веднаго Ла́заря ієре́й усли́ша глас от іко́ни Бо́жия Ма́тере: «Шед, рци ми́лостивій Іуліяні́ї: что в це́рков не хо́дить на моли́тву? І домовная єя́ моли́тва благоприя́тна, но не я́ко церко́вная; ви же почита́йте ю, уже́ бо она́ не ме́ньши шести́десяти літ і Дух Святи́й на ней почива́єть». Ти же, ми́лостивая ма́ти, в храм Бо́жий направила єси́ стопи́ твоя́, с те́плими моли́твами лобиза́ющи іко́ну Богома́тере і пі́нія моле́бная вознося́щи. Сего́ ра́ди лю́діє ві́рни, ра́дующеся, я́ко Сама́ Цари́ця Небе́сная та́ко тебі́ возлюби́, прославля́ху тя си́це:","Ра́дуйся, Пресвято́ю Ді́вою Богоро́дицею возлю́бленная.","Ра́дуйся, Покро́вом Єя́ осіне́нная.","Ра́дуйся, от Бо́жия Ма́тере ми́лостивою нарече́нная.","Ра́дуйся, не от челові́к, но от Са́мия Богома́тере сла́ву прия́вшая.","Ра́дуйся, Засту́пниці Усе́рдния благогові́йная почитательнице.","Ра́дуйся, Бо́жия Ма́тере ізбраннице.","Ра́дуйся, пред іко́ною Богома́тере моли́тви те́плия возносившая.","Ра́дуйся, я́ко роса́ небе́сная, благода́тією Бо́жиєю напоє́нная.","Ра́дуйся, Ду́ха Свята́го жили́ще.","Ра́дуйся, по Бо́зі і Богоро́дице крі́пкоє на́ше упова́ніє.","Ра́дуйся, моли́твами і ми́лостинями Бо́гу угоди́вшая.","Ра́дуйся, ве́ліє дерзнове́ніє к Нему́ стяжа́вшая.","Ра́дуйся, ми́лостивая Іулія́ніє, жен ру́ських похвало́ і украше́ніє."]},{"h":"Кондак 8","ps":["Стра́нницю і пришелицю в ми́рі сем помишля́ла єси́ себе́ би́ти, ма́ти Іулія́ніє, ті́мже о бога́тстві земні́м вся́коє попече́ніє отложи́вши і сестра́м Ла́заря пра́веднаго подража́ющи, мно́гих ни́щих, неду́жних і си́рих пита́ла єси́, в ї́хже лице́ Самому́ Христу́ служи́ла єси́, я́ко Ма́рфа о них пеку́щися, ду́хом же Марі́їну часть возлюби́ла єси́. Ни́ні же обита́єши со А́нгели во сла́ві ві́чній і поє́ши во гла́сі ра́дованія побі́дную піснь Христу́ Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Вся страна́ Ру́ськая ско́рби і пла́ча іспо́лнися во времена́ гла́да вели́каго, і мно́жество люде́й неісче́тно гла́дом ізомро́ша. Ти же, ми́лостивая Іулія́ніє, все імі́ніє твоє́ распродавши на жи́то, ми́лостиню давала єси́, і ні єди́наго от прося́щих не отпусти́ла єси́ тща. Єгда́ же іссяче зе́рно в до́му твоє́м, повелі́ла єси́ слуга́м твої́м собира́ти лебеду і кору́ древ'я́ную, хлі́би із них творя́щи, і моли́твами твої́ми бисть хліб сла́док. Сего́ ра́ди с любо́вію велича́єм тя:","Ра́дуйся, стра́ннице, го́рняго Оте́чества іска́вшая.","Ра́дуйся, ско́рби мно́гія благоду́шно претерпі́вшая.","Ра́дуйся, бедствующим ско́рая помо́щнице.","Ра́дуйся, ни́щим і убо́гим благосе́рдая попечи́тельнице.","Ра́дуйся, вся імі́нія своя́, по сло́ву Го́спода, раздавшая.","Ра́дуйся, бли́жнім і да́льним ми́лостивно благотворившая.","Ра́дуйся, сосу́де честни́й, єле́й ми́лости Бо́жия в нем храня́й.","Ра́дуйся, теплото́ю любве́ твоєя́ нас согріва́ющая.","Ра́дуйся, призива́ющим тя усе́рдная засту́пнице.","Ра́дуйся, в печа́ліх і злострада́ніїх су́щим незри́мая предста́тельнице.","Ра́дуйся, ми́лостинею і по́двиги духо́вними Небе́сноє Ца́рствіє стяжа́вшая.","Ра́дуйся, ми́лостиню твори́ти і нас науча́ющая.","Ра́дуйся, ми́лостивая Іулія́ніє, жен ру́ських похвало́ і украше́ніє."]},{"h":"Кондак 9","ps":["Вся́коє єстество́ челові́чеськоє і а́нгельськоє удиви́ся вели́ким твої́м по́двигом, пра́ведная Іулія́ніє, я́ко на землі́ равноа́нгельноє житіє́ показа́ла єси́, дом Ду́ха Свята́го била́ єси́ і ми́лостинями мно́гими благода́ть обріла́ єси́ у Бо́га, ре́кшаго: «Блаже́нні ми́лостивії, я́ко ті́ї поми́ловані бу́дуть». Ті́мже ни́ні сві́тлая твоя́ душа́ со А́нгели водворя́ється, воспіва́ющи укріпи́вшему тя Бо́гу благода́рную піснь: Аллилу́я."]},{"h":"Ікос 9","ps":["Ві́тіії многовіща́ннії недоумі́ють по достоя́нію восхвали́ти діла́ твоя́, я́же твори́ла єси́ на землі́. Єгда́ же прибли́жися преставле́ніє твоє́, тогда́ призвала́ єси́, ма́ти блаже́нная, чад твої́х, наказу́ющи їх і глаго́лющи: «Ча́да, подвиза́йтеся і любо́в імі́йте между́ собо́ю, я́коже Христо́с возлюби́ нас»; і обвивши четки вокру́г руки́ своєя́, рекла́ єси́: «Сла́ва Бо́гу всіх ра́ди, в ру́ці Твої́, Го́споди, предаю́ дух мой», - і предала́ єси́ святу́ю свою́ ду́шу в ру́ці Бо́жії, і всі собра́вшіїся ви́діша у глави́ твоєя́ круг злат, я́ко на іко́нах святи́х пи́шеться. Ми же, почита́юще блаже́нную твою́ кончи́ну, воспіва́єм тя:","Ра́дуйся, от ю́ности твоєя́ Го́спода всім се́рдцем возлюби́вшая.","Ра́дуйся, ві́рность Єму́ до конця́ сохранившая.","Ра́дуйся, посреді́ ми́ра богоуго́дно пожи́вшая.","Ра́дуйся, ми́лостинями і моли́твами Бо́гу угоди́вшая.","Ра́дуйся, свя́то і преподо́бно жизнь земну́ю сконча́вшая.","Ра́дуйся, віне́ць безсме́ртія от Го́спода прия́вшая.","Ра́дуйся, преселившаяся от землі́ к оби́телем небе́сним.","Ра́дуйся, к ли́ку святи́х жен та́мо приобщившаяся.","Ра́дуйся, уго́днице Бо́жия, ди́вним житіє́м твої́м я́ко со́лнце сія́ющая.","Ра́дуйся, чудеси́ твої́ми от Бо́га просла́вленная.","Ра́дуйся, я́ко предста́тельством твої́м у Христа́ Бо́га ві́чноє спасе́ніє нам подає́ши.","Ра́дуйся, я́ко фиміа́м моли́тв твої́х о всіх ді́вах і жена́х ру́ських Єму́ прино́сиши.","Ра́дуйся, ми́лостивая Іулія́ніє, жен ру́ських похвало́ і украше́ніє."]},{"h":"Кондак 10","ps":["Спасти́ хотя́щи ду́шу твою́, ми́лостивая Іулія́ніє, ше́ствовала єси́ путе́м у́зьким і приско́рбним, і та́ко Ца́рствіє Небе́сноє унаследовала єси́ і сконча́лася єси́ я́ко і́стинная учениця Христа́ Бо́га, за́повіді Єго́ іспо́лнивши: с пла́чущими в покая́нії утіше́ніє себі́ обріла́ єси́, кро́тостію ко всім зе́млю кро́тких наслі́довала єси́, нищелю́бієм і ми́лостинями поми́лованіє от Го́спода получи́ла єси́, чистото́ю се́рдця Бо́га зрі́ти сподо́билася єси́, Єму́же со всі́ми святи́ми ни́ні поє́ши побі́дную піснь: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ необори́мая яви́лася єси́ ві́рним, к ско́рому твоєму́ предста́тельству прибегающим, єгда́ обрі́тени би́ша честни́я мо́щі твоя́, свята́я Іулія́ніє. І ви́діша лю́діє гроб твой полн ми́ра благоуха́ннаго, і мно́зі, пома́завшеся ми́ром тім, от разли́чних неду́г ісціле́нія прийма́ху. Ті́мже і ми, грі́шнії, к ра́ці моще́й твої́х ни́ні притека́юще, мо́лим: заступи́ і сохрани́ нас моли́твами твої́ми от іскуше́ній і скорбе́й, бід і напа́стей, да взива́єм ті:","Ра́дуйся, нетлі́нієм моще́й твої́х от Бо́га просла́вленная.","Ра́дуйся, зе́млю на́шу сія́нієм чуде́с твої́х облиста́вшая.","Ра́дуйся, єва́нгельських за́повідей ві́рная ісполнительнице.","Ра́дуйся, ві́чния ра́дости со Христо́м прича́стнице.","Ра́дуйся, нището́ю духо́вною во вертогра́ді небе́снім водвори́вшаяся.","Ра́дуйся, умиле́нними слеза́ми утіше́ніє ві́чноє прия́вшая.","Ра́дуйся, алкавшая і жаждавшая пра́вди, ни́ні же ра́йськаго блаже́нства наслажда́ющаяся.","Ра́дуйся, ду́хом кро́тости зе́млю обітова́нія наследовавшая.","Ра́дуйся, я́ко милосе́рдія діла́ми ми́лостивих блаже́нство от Го́спода получи́ла єси́.","Ра́дуйся, я́ко чи́стим се́рдцем Бо́га ни́ні лице́м к лицю́ зри́ши.","Ра́дуйся, терпі́нієм пра́вди ра́ди в Ца́рство Небе́сноє вше́дшая.","Ра́дуйся, я́ко мзда твоя́ мно́га на Небесі́.","Ра́дуйся, ми́лостивая Іулія́ніє, жен ру́ських похвало́ і украше́ніє."]},{"h":"Кондак 11","ps":["Пі́ніє всеумиле́нноє с ві́рою і любо́вію прино́сим ті, пра́ведная Іулія́ніє, сла́вим і велича́єм просла́вльшаго тя і ди́внаго во святи́х Свої́х Бо́га на́шего, дарова́вшаго нам такову́ю ми́лостивую предста́тельницю і ціли́тельницю неду́гов, і мо́лимся тебі́: сохрани́ во вся́ком благополу́чії і чистоті́ лю́ди ру́ськия і соблюди́ нас от вся́каго зла́го обстоя́нія, да ми́рно і безм'яте́жно в держа́ві на́шей жи́тельствующе, благода́рні воспіва́єм Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Возсія́ла єси́, я́ко світи́льник, поста́вленний не под спу́дом, но на сві́щниці, іспо́лнен єле́я ві́ри, наде́жди і любве́, найпа́че же христия́нськаго терпі́нія, милосе́рдія і воздержа́нія, не то́чію в землі́ Муромстей, но і всю богоспаса́ємую Русь освіти́ла єси́ луча́ми твоєго́ богоуго́днаго житія́ і мно́гими чудеси́ ісціле́нія істоча́єши от нетлі́нних моще́й твої́х, утешающи і ра́дость да́рующи всім ві́рним, вопію́щим тебі́ такова́я:","Ра́дуйся, звіздо́ небосві́тлая, в землі́ Ру́сстій воссіявшая.","Ра́дуйся, світоза́рноє світи́ло, всю страну́ на́шу осветившеє.","Ра́дуйся, гра́да Му́рома духо́вноє сокро́вище.","Ра́дуйся, ві́си Лазоревськия неотсту́пная храни́тельнице.","Ра́дуйся, світи́льниче сві́та небе́снаго, путь к Ца́рствію Бо́жию нам указу́яй.","Ра́дуйся, сві́тлостію чуде́с твої́х мрак душ на́ших озаря́ющая.","Ра́дуйся, во тьмі неві́рія блуждающим путеводи́тельнице.","Ра́дуйся, я́ко і нас благода́тним сві́том просвіща́єши.","Ра́дуйся, душі́ і тілеса́ на́ша благода́тію Бо́жиєю ісціля́ющая.","Ра́дуйся, засту́пнице ми́лостивая і неусипа́ющая храни́тельнице на́ша.","Ра́дуйся, свіще́ неугаси́мая, любо́вію к Бо́гу возжже́нная.","Ра́дуйся, лю́б'ящим і чту́щим тя сугу́бо любо́вію воздаю́щая.","Ра́дуйся, ми́лостивая Іулія́ніє, жен ру́ських похвало́ і украше́ніє."]},{"h":"Кондак 12","ps":["Благода́ть, да́нная ті от Бо́га ціли́ти неду́ги душе́вния і тіле́сния, созива́єть ві́рних к ра́ці моще́й твої́х, пред ни́ми бо ма́лоє моле́ніє принося́ще, ве́лію благода́ть от Го́спода получа́єм. Ті́мже мо́лим тя: проле́й ни́ні те́плую моли́тву ко Го́споду, да укріпи́ть Це́рков Святу́ю, да утверди́ть страну́ на́шу і ві́ру Правосла́вную в ней сохрани́ть; умоли́ Христа́ Бо́га на́шего, да возгоря́ться світи́льници на́ші от єле́я до́брих діл, і помози́ всім ді́вам і жена́м отчизни на́шея срі́сти Го́спода і удосто́їтися одесну́ю Него́ стоя́ти і сла́вити Єго́ во ві́ки а́нгельською пі́снію: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще і превознося́ще Всеми́лостиваго Бо́га, дарова́вшаго нам тебе́, ми́лостивая ма́ти Іулія́ніє, прославля́єм діла́ милосе́рдія і по́двиги твоя́, ї́миже Го́спода на землі́ просла́вила єси́, хва́лим ре́вность твою́ по Бо́гу, любо́в к Пречи́стій Єго́ Ма́тері, ублажа́єм служе́ніє твоє́ ни́щим, боля́щим і убо́гим, сла́вим кро́тость твою́, велича́єм смиренному́дріє твоє́ і почита́єм святу́ю па́м'ять твою́, со умиле́нієм воспіва́юще тебі́ та́ко:","Ра́дуйся, во ви́шніх Престо́лу Бо́жию со А́нгели предстоя́щая.","Ра́дуйся, я́ко со ізбра́нними Єго́ во оби́теліх ра́йських торжеству́єши.","Ра́дуйся, с преподо́бними і пра́ведними вінце́м безсме́ртія увінча́нная.","Ра́дуйся, всего́ богосві́тлаго ли́ка святи́х жен ру́ських собесі́днице.","Ра́дуйся, Це́ркве Христо́ви сла́во і украше́ніє.","Ра́дуйся, цві́те благоуха́нний Ру́ськия землі́.","Ра́дуйся, во сві́ті невече́рнім обита́ющая.","Ра́дуйся, душетлі́нних неду́гов тьму отгоня́ющая.","Ра́дуйся, безнаде́жних страда́льцев богодарова́нная ціли́тельнице.","Ра́дуйся, бесноватих от наси́лія дия́вола свободи́тельнице.","Ра́дуйся, і́стинния любве́ к Бо́гу наста́внице.","Ра́дуйся, всім христия́ном землі́ на́шея благода́тноє утіше́ніє.","Ра́дуйся, ми́лостивая Іулія́ніє, жен ру́ських похвало́ і украше́ніє."]},{"h":"Кондак 13","ps":["О пречу́дная і ми́лостивая голуби́це, свята́я пра́ведная Іулія́ніє, прийми́ ни́ні ма́лоє сіє́ моле́ніє на́ше і вознеси́ єго́ ко Христу́ Бо́гу на́шему; іспроси́ нам у Всеми́лостиваго Спа́са утвержде́ніє во ві́рі і до́брих ді́ліх, ізбавле́ніє от всіх бід і напа́стей в жи́зні сей, во успе́нії же на́шем благу́ю наде́жду на спасе́ніє, да сподо́бимся в ра́дості ві́чній воспіва́ти Єму́: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгельськоє і́ночеськоє житіє́ от ю́ности возлюби́ла єси́, блаже́нная Іулія́ніє, і Бо́гу єди́ному порабо́тати всім се́рдцем возжела́ла єси́. Оба́че смотре́нієм Свої́м ін путь спасе́нія предуста́ви тебі́ Госпо́дь, є́же в бра́ці честні́м святи́м житіє́м Єму́ угоди́ти. Сего́ ра́ди, єгда́ дости́гла єси́ во́зраста бра́чна, вдана́ била́ єси́ му́жу добродетельну і бога́ту, і́менем Гео́ргію, і вінча́ни би́сте в це́ркві пра́веднаго Ла́заря. Тогда́ всі сро́дниці супру́га дивля́хуся ра́зуму твоєму́, смире́нію і послуша́нію. Ми же таково́му чу́дному про́мислу Бо́жию див'я́щеся, ра́достно взива́єм ті:","Ра́дуйся, роди́телей нищелюбивих Іусти́на і Стефани́ди ча́до благослове́нноє.","Ра́дуйся, ма́тере лиши́вшися, вні кро́ва оте́чеськаго во ві́рі і благоче́стії воспитанная.","Ра́дуйся, звіздо́ пресві́тлая, в селе́нії Ла́зареві Бо́гом возжже́нная.","Ра́дуйся, лиліє благоуха́нная, в тишині́ лісо́в му́ромських возращенная.","Ра́дуйся, сверстником твої́м о́браз благонра́вія показа́вшая.","Ра́дуйся, а́гнице чи́стая, і́ночеськаго чи́на ізмла́да іска́вшая.","Ра́дуйся, послушнице кро́ткая, Бо́жиєю во́лею му́жу вруче́нная.","Ра́дуйся, во смире́нії і доброді́ланії жизнь свою́ проводившая.","Ра́дуйся, любо́в нелицемі́рную к Бо́гу і бли́жнім яви́вшая.","Ра́дуйся, Пресвято́ю Богоро́дицею возлю́бленная.","Ра́дуйся, а́нгельськи на землі́ пожи́вшая.","Ра́дуйся, я́ко ни́ні со А́нгели лику́єши в оби́теліх небе́сних.","Ра́дуйся, ми́лостивая Іулія́ніє, жен ру́ських похвало́ і украше́ніє."]},{"h":"Кондак 1","ps":["Ізбра́нная Бо́гом, пра́ведная і ми́лостивая Іулія́ніє, в землі́ Муромстей я́ко звізда́ пресві́тлая возсія́вшая, ни́щих пита́тельнице і о лю́діх ко Христу́ Бо́гу моли́твеннице, прославля́юще просла́вльшаго тя Го́спода, похва́льними пі́сньми воспої́м тя, о́браз по́двига духо́внаго всім жена́м ру́ським показа́вшую. Ти же, я́ко іму́щая дерзнове́ніє ко Го́споду, моли́твами твої́ми от вся́ких бід свободи́ нас, с любо́вію зову́щих:","Ра́дуйся, ми́лостивая Іулія́ніє, жен ру́ських похвало́ і украше́ніє."]},{"h":"Молитва","ps":["Утіше́ніє на́ше і похвало́, Іулія́ніє, голуби́це богому́драя, я́ко фі́нікс пресла́вно процві́тшая, крилі́ доброді́телей свяще́нне і посре́бренні іму́щая, і́миже на висоту́ Ца́рствія Небе́снаго возлеті́ла єси́! Похва́льная пі́нія па́м'яті твоє́й ра́достно днесь прино́сим, поне́же Христо́с нетлі́нієм чуде́сним тя увінча́ і благода́тію ісціле́ній тебі́ просла́ви. Зане́ любо́вію Христо́вою уязви́вшися, от мла́дости чистоту́ душе́вную і тіле́сную хранила єси́, пост же і воздержа́ніє возлюби́ла єси́, і́миже помогающей ті благода́ті, вся стра́сті ми́ра сего́ попра́ла єси́, і, я́ко пчела́, му́дро цвіт доброді́телей ізискавши, пресла́дкий мед Свята́го Ду́ха в се́рдці своє́ всели́ла єси́ і, єще́ во пло́ті би́вши, посіще́нія Богома́тере сподо́билася єси́. Прилі́жно у́бо тя мо́лим: моли́ся, госпоже́, да пода́сть нам в Тро́йці сла́вимий Бог твої́ми моли́твами многолі́тно здра́віє же і спасе́ніє, тишину́ і ізоби́ліє плодо́в земни́х і на враги́ побі́ди і одолі́нія. Сохрани́ предста́тельством твої́м, преподо́бная ма́ти, страну́ Ру́ськую і град сей і вся гра́ди і страни́ христия́нськия неврежде́нни от всіх наві́т і ко́зней вра́жиїх. Пом'яни́, госпоже́, убо́гія раби́ твоя́, днесь в моли́тві тебі́ предстоящия, чрез все житіє́ своє́ па́че всіх челові́к прегрешившия, оба́че те́плоє покая́ніє о сих принося́щия і твої́ми к Бо́гу моли́твами оставле́ніє гріхо́в получи́ти просящия, я́ко да гріхо́вних страсте́й свободи́вшеся, благода́рственноє пі́ніє тебі́ приноси́ти при́сно потщі́мся і просла́вим всіх благи́х Пода́теля Бо́га, Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Просвіти́вшися Боже́ственною благода́тію, / і по сме́рті сві́тлость житія́ твоєго́ я́вила єси́: / істоча́єши бо ми́ро благово́нноє всім боля́щим на ісціле́ніє, / с ві́рою приходя́щим к моще́м твої́м, / пра́ведная ма́ти Іуліяні́є, / Христа́ Бо́га моли́ / спасти́ся душа́м на́шим."]},{"h":"Інший тропар, глас 3","ps":["На ра́мо взе́мши крест свой, / послі́довала єси́ Христу́ ми́лостинею, посто́м і моли́твою, / всехва́льная Іуліяні́я ми́лостивая, / і всім, в ми́рі живу́щим, пра́вило яви́лася єси́ житія́, / ті́мже Ви́шнєє Ца́рствіє наслі́довавши, / непреста́нно моли́ / спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 8","ps":["Скоропослу́шливую помо́щницю всі, су́щії в біда́х і болі́зніх, / воспоє́м Іуліяні́ю святу́ю, / та бо в ми́рі богоуго́дно поживе́ / і ми́лостиню к ни́щим безмі́рну показа́, / сего́ ра́ди обрі́те благода́ть чуде́с Бо́жиїм ві́дінієм."]},{"h":"Величання","ps":["Велича́єм тя, / свята́я пра́ведная Іуліяні́є, / і чтим святу́ю па́м'ять твою́, / ти бо мо́лиши за нас // Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст святим праотцям Адаму і Єві","e":"Akathist to the Holy Forefathers Adam and Eve","secs":[{"h":"Кондак 1","ps":["Ізбра́нному творе́нію Бо́жию, Ада́му пе́рвому, прародителю на́шему, со Є́вою, я́же плоть от пло́ті і кость от косте́й єго́ єсть, воспої́м, ві́рнії, похва́льная словеса́. Ви же, а́ще і па́дшії іногда́ і рая́ лишеннії, оба́че по́двигом Но́ваго Ада́ма, Є́вою второ́ю в мир прише́дшаго, спасе́ннії і на небеса́ возведе́ннії, молі́теся о нас, ча́діх ва́ших, взива́ющих вам:","Ра́дуйтеся, Ада́ме і Є́во, ві́нче тва́рі і красото́ вселе́нния."]},{"h":"Ікос 1","ps":["А́нгели Бо́жії просла́виша Зижди́теля, шестію́ де́ньми вся сотво́ршаго і напослі́док дній тіх челові́ка созда́вшаго, поселившаго же сего́ во Єде́мі на восто́ці і да-ровавшаго єму́ жену́ помо́щницю, і глаго́лаша Ада́му с жено́ю:","Ра́дуйтеся, творе́ніє Бо́жиє соверше́нноє;","ра́дуйтеся украше́ніє поднебе́сния.","Ра́дуйтеся, по о́бразу Бо́жию созданнії;","ра́дуйтеся, по подо́бію Єго́ сотвореннії.","Ра́дуйтеся, влади́ки тва́рі;","ра́дуйтеся, повели́телі землі́.","Ра́дуйтеся, плоть перстную нося́щії;","ра́дуйтеся, ум небе́сний іму́щії.","Ра́дуйтеся, во Єде́мі пребива́ющії;","ра́дуйтеся, от дре́ва жи́зні питающіїся.","Ра́дуйтеся, за́повіді Бо́жії приявшії;","ра́дуйтеся, я́ко за́повіді Єго́ тя́жки не суть.","Ра́дуйтеся, Ада́ме і Є́во, ві́нче тва́рі і красото́ вселе́нния."]},{"h":"Кондак 2","ps":["Ви́дя Творе́ць творе́ніє Своє́, я́ко вся добра́ зіло́, почи́ в день седьми́й от діл Свої́х, не престає́ть оба́че і в о́ний день промишля́ти о вселе́нній, приймаєть же поклоне́ніє от а́нгел небе́сних і ро́да челові́ча, пою́щих Єму́: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум недоразуміва́ємий є́же челові́ков творе́нія разумі́ти Денни́ця іски́й, соблазнися о толи́цій сла́ві пе́рстнаго Ада́ма і помрачи́ся умо́м. Глаго́ляй пре́жде: «На не́бо взи́ду, ви́ше звізд небе́сних поста́влю престо́л мой, ся́ду на горі́ висо́ці, на гора́х висо́ких, я́же к сі́веру, взи́ду ви́ше о́блак, бу́ду подо́бен Ви́шнему», ни́ні дух зло́би бисть, і паде́ся с небесе́, бисть же паде́ніє єго́ вели́коє. Твар же вся, Прему́дрость О́тчую прославля́ющи, ко Ада́му і Є́ві взива́ху:","Ра́дуйтеся, Сві́та і́стиннаго прича́стници;","ра́дуйтеся, тьми в себі́ ніка́коже іму́щії.","Ра́дуйтеся, во дні с Бо́гом бесі́дующії;","ра́дуйтеся, і в нощі́ діла́ ру́ку Єго́ созерцающії.","Ра́дуйся, Ада́ме, світи́ло вели́коє;","ра́дуйся, Є́во, світи́ло ма́лоє.","Ра́дуйтеся, Творцом возлю́бленнії;","ра́дуйтеся, друг дру́га зіло́ лю́б'ящії.","Ра́дуйтеся, по землі́ ходя́щії;","ра́дуйтеся, ду́хом к не́бу вознося́щіїся.","Ра́дуйтеся, ца́ріє вся́каго диха́нія;","ра́дуйтеся, попече́ніє о вселе́нній іму́щії.","Ра́дуйтеся, Ада́ме і Є́во, ві́нче тва́рі і красото́ вселе́нния."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго всемощна єсть, не хотя́ше оба́че Творе́ць творе́нія Своєго́ разу́мнаго свободную во́лю утеснити, сего́ ра́ди попусти́ врагу́ ро́да челові́ча, зрак змі́я прия́вшему, іскуси́ти Є́ву, є́же не пі́ти єй: Аллилу́я."]},{"h":"Ікос 3","ps":["Іми́й мисль лука́вую, рече́ змій жені́: «Что я́ко рече́ Бог, да не я́сте от вся́каго дре́ва ра́йськаго?» І рече́ жена́ змію́: «От вся́каго дре́ва ра́йськаго я́сти бу́дем, от плода́ же дре́ва, є́же єсть посреді́ рая́, рече́ Бог, да не я́сте от него́, ніже́ прикосне́теся к нему́, да не у́мрете». І рече́ змій жені́: «Не сме́ртію у́мрете, оба́че вість Бог, я́ко во́ньже а́ще день сні́сте от него́, отве́рзуться о́чі ва́ші, і бу́дете, я́ко бо́зі, ві́дяще до́броє і лука́воє». Сія́ вся льсти́вия глаго́ли глаго́лаше змій жені́, вмі́сто є́же пі́ти єй і му́жеві єя́:","Ра́дуйтеся, ду́шу слове́сную іму́щії;","ра́дуйтеся, во́лею свобо́дною почтеннії.","Ра́дуйтеся, ві́дущії во́лю Бо́жию бла́го би́ти;","ра́дуйтеся, во́лі своє́й не і́щущії.","Ра́дуйтеся, от древе́сних плодо́в питающіїся;","ра́дуйтеся, за́повідь Зижди́теля храня́щії.","Ра́дуйтеся, назі́ї і не стидящіїся;","ра́дуйтеся, нічесо́же лишеннії.","Ра́дуйтеся, утомле́нія не зна́ющії;","ра́дуйтеся, сме́рті не причастнії.","Ра́дуйтеся, безсме́ртнаго Влади́ки ча́да;","ра́дуйтеся, ві́ру Сему́ іму́щії.","Ра́дуйтеся, Ада́ме і Є́во, ві́нче тва́рі і красото́ вселе́нния."]},{"h":"Кондак 4","ps":["Бу́рю помишле́ній сумни́тельних ім'я́ше внутр жена́, не ві́дящи, каково́ єсть сло́во сіє́. Ви́дящи же, я́ко добро́ дре́во в снідь і я́ко уго́дно очи́ма ви́діти і красно́ єсть, є́же разумі́ти, і взе́мши от плода́ єго́ яде́, і даде́ му́жу своєму́, і ядо́ста. І отверзо́шася о́чі обі́ма, і разумі́ша, я́ко на́зі бі́ша, і сши́ста ли́ствіє смоко́вноє, і сотвори́ста себі́ препоя́санія, Бо́гу же заби́ша пі́ти: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаста Ада́м со Є́вою глас Го́спода Бо́га, ходя́ща в раї́ по полу́дні, і скри́стася Ада́м і жена́ єго́ от лиця́ Го́спода Бо́га посреді́ древ ра́йських. І призва́ Госпо́дь Бог Ада́ма і рече́ єму́: «Ада́ме, гді єси́?» І рече́ Ада́м: «Глас сли́шах Тебі́, ходя́ща в раї́, і убоя́хся, я́ко наг єсьм, і скри́хся». І рече́ єму́ Бог: «Кто возвісти́ тебі́, я́ко наг єси́? Не ял ли єси́ от дре́ва, от него́же єди́наго запові́дах тебі́ не я́сти?» І рече́ Ада́м: «Жена́, ю́же дал мі єси́, та мі даде́ от плодо́в дре́ва, і ядо́х». І рече́ Госпо́дь Бог жені́: «Что сіє́ сотвори́ла єси́?» І рече́ жена́: «Змій прельсти́ м'я, і ядо́х». І про́клят Госпо́дь Бог змі́я і рече́ єму́: «Вражду́ положу́ между́ тобо́ю і между́ жено́ю, і между́ сі́менем твої́м і Сі́менем тоя́: Той сотре́ть главу́ твою́, і ти блюсти́ бу́деши Єго́ п'я́ту». Жені́ же рече́: «Умножа́я умно́жу печа́лі твоя́: в болі́зніх роди́ши ча́да, і к му́жу твоєму́ влече́ніє твоє́, і той тобо́ю облада́ти бу́деть». І Ада́му рече́: «Проклята́ земля́ в ді́ліх твої́х: те́рнія і волчці́ проізрасти́ть тебі́, в по́ті лиця́ твоєго́ сні́си хліб твой, до́ндеже возврати́шися в зе́млю, от нея́же взят єси́, я́ко земля́ єси́, і в зе́млю отидеши. І не і́маши сли́шати ктому́ ти, ніже́ жена́ твоя́, до́ндеже Ізба́витель при́йдеть, глаго́лов сих:","Ра́дуйтеся, в раї́ с Бо́гом бесі́дующії;","ра́дуйтеся, любве́ Єго́ наслажда́ющіїся.","Ра́дуйтеся, при істоці чети́ріх рек живу́щії;","ра́дуйтеся, чети́рми конці́ облада́ющії.","Ра́дуйся, Ада́ме, нареки́й звіре́м імена́;","ра́дуйся, Є́во, му́жеві помо́щниця і жена́.","Ра́дуйся, ро́да челові́ча нача́льниче;","ра́дуйся, ма́ти всіх живу́щих.","Ра́дуйтеся, зе́млю напо́лнити іму́щії;","ра́дуйтеся, траву́ в снідь приявшії.","Ра́дуйтеся, сме́рті ніколи́же ви́дівшії;","ра́дуйтеся, к животу́ безсме́ртному предуста́вленнії.","Ра́дуйтеся, Ада́ме і Є́во, ві́нче тва́рі і красото́ вселе́нния»."]},{"h":"Кондак 5","ps":["Богопоста́вленний херуви́м, держа́й ору́жіє пла́менноє обраща́ємоє, храня́ше дре́во жи́зні ра́йськоє, є́же ка́ко не би́ша пришли́ челові́ци согріши́вшії і я́ли от дре́ва того́ і жи́ли би́ша во ві́ки: ізгна́ бо Бог із рая́ сла́дости Ада́ма со Є́вою і даде́ їм ри́зи ко́жани, сим, і́же воспіва́ху іногда́ со а́нгели: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́ді Ада́м а́нгела ізри́нувша і затвори́вша боже́ственнаго са́да двер, воздохну́ вельми́, сі́де же пря́мо рая́ і свою́ наготу́ рида́я пла́каше: «Уви́ мні, пре́лестію лука́вою увіща́нну би́вшу і окра́дену і сла́ви удале́ну! Уви́ мні, простото́ю на́гу, ни́ні же недоумі́нну! Но, о раю́, ктому́ твоєя́ сла́дости не наслажду́ся, ктому́ не узрю́ Го́спода моєго́ і Созда́теля і не усли́шу званій сих:","Ра́дуйся, Ада́ме, жи́зні ра́йськия наслажда́яйся;","ра́дуйся, Ада́ме, попече́нія не іму́щий.","Ра́дуйся, Є́во, от ре́бра му́жня взя́тая;","ра́дуйся, Є́во, муже́м твої́м люби́мая.","Ра́дуйтеся, звіре́й не боя́щіїся;","ра́дуйтеся, і́мже зві́ріє повину́ються.","Ра́дуйтеся, красото́ю древ ра́йських услаждающіїся;","ра́дуйтеся, птиць єде́мських послу́шающії.","Ра́дуйтеся, к Бо́гу, я́ко к дру́гу, бесі́дующії;","ра́дуйтеся, от Творця́ нічесо́же таящії.","Ра́дуйтеся, возрастающії во благода́ті;","ра́дуйтеся, укрепевшії в до́брі.","Ра́дуйтеся, Ада́ме і Є́во, ві́нче тва́рі і красото́ вселе́нния»."]},{"h":"Кондак 6","ps":["Пропові́дници би́ша Ада́м со Є́вою ді́тем свої́м о іму́щем прийти́ Спаси́телі їх і Ізбавителе, І́же сотре́ть главу́ змі́єву і свободи́ть род челові́ч от вла́сті тлі́нія; Ка́їн же оба́че не умили́ся, но за́вистію і зло́бою побіжда́єм, умно́жи гріх в ми́рі, уби́в бра́та своєго́ А́веля, звіронра́вен сий і не ві́дий пі́ти: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ світ Є́ві, єгда́ роди́ тре́тіяго си́на своєго́ Си́фа, от него́же род благочести́в проізи́де: Єно́х, на не́бо пресе́льник, і Мафуса́л ста́рець, і ковчегоплаватель Ной. І рече́ жена́: «Воскреси́ мні Бог сі́м'я друго́є, вмі́сто А́веля, єго́же уби́ Ка́їн. Оба́че і́мам ли ублажа́єма би́ти пі́нії си́ми:","Ра́дуйся, Є́во, Бо́гу послу́шная;","ра́дуйся, же́но, му́жу повинующаяся.","Ра́дуйтеся, в по́ті лиця́ своєго́ тружда́ющіїся;","ра́дуйтеся, ча́да своя́ воспитующії.","Ра́дуйтеся, я́ко Ізба́витель от вас проізи́деть;","ра́дуйтеся, я́ко Сі́м'я жени́ сотре́ть главу́ змі́єву.","Ра́дуйтеся, наде́жду іму́щії;","ра́дуйтеся, на Бо́га упова́ніє возложи́вшії.","Ра́дуйся, Ада́ме, а́ще і ско́рбен єси́;","ра́дуйся, Ада́ме, о Потреби́телі тлі.","Ра́дуйся, Ада́ме, при́сно Бо́гу моля́щийся;","ра́дуйся, Є́во, к Сему́ ви́ну взивающая.","Ра́дуйтеся, Ада́ме і Є́во, ві́нче тва́рі і красото́ вселе́нния»?"]},{"h":"Кондак 7","ps":["Хотя́щу Созда́телю поми́ловати созда́ніє своє́, посла́ челові́ком Авраа́ма, Мойсе́я же і Дави́да, посліди́ же восхоті́ сам воплоти́тися от ізбра́нния Ді́ви наро́да ізбранного, да воспою́ть лю́діє: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вую показа́ твар, я́влься Зижди́тель нам от Него́ би́вшим, із безсі́менния прозя́б утро́би і сохрани́в Ю, я́коже бі, нетлі́нну. Ми же, Но́ваго Ада́ма от втори́я Є́ви прише́дшаго зря́ще, ве́тхаго помина́єм і глаго́лем к прароди́телем:","Ра́дуйтеся, я́ко спасе́ніє ва́ше прибли́жися;","ра́дуйтеся, се бо Сло́во воплоща́ється.","Ра́дуйтеся, обітова́ніє приявшії;","ра́дуйтеся, сего́ сбитіє́ созерцающії.","Ра́дуйся, Ада́ме, зря Ада́ма небе́снаго;","ра́дуйся, Ада́ме, Бо́гу же і Челові́ку.","Ра́дуйся, Є́во, послуша́нію Дще́ре твоєя́;","ра́дуйся, Є́во, смире́нію Єя́.","Ра́дуйтеся, Ра́дость бо при́йде;","ра́дуйтеся, я́ко ми́лостив Госпо́дь.","Ра́дуйтеся, рая́ взиску́ющії;","ра́дуйтеся, і́щущії сла́дости єго́.","Ра́дуйтеся, Ада́ме і Є́во, ві́нче тва́рі і красото́ вселе́нния."]},{"h":"Кондак 8","ps":["Стра́нноє рождество́ ви́дівше, устрані́мся ми́ра, ум на небеса́ прело́жше: сего́ бо ра́ди висо́кий Бог явля́ється смире́нний челові́к, хотя́й привлещи́ к висоті́ Тому́ вопію́щия: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь любо́вію к творе́нію своєму́ об'ят, посла́ Боже́ственноє Сло́во прароди́телем в страну́ печа́лі пропові́дника Своєго́ к ним прише́ствія, Іоа́нна Предте́чу, во є́же взива́ти тому́:","Ра́дуйтеся, Бо́гу возлю́бленнії;","ра́дуйтеся, Їм не отверженнії.","Ра́дуйтеся, Ізба́витель бо при́йде;","ра́дуйтеся, Спас бо ми́ру возсія́.","Ра́дуйтеся, Вну́ка Сифова ожидающії;","ра́дуйтеся, о Ча́ді Но́єві веселя́щіїся.","Ра́дуйтеся, я́ко Сі́м'я Авраа́мле безсі́менно ражда́ється;","ра́дуйтеся, я́ко Лев от Іу́ди прихо́дить.","Ра́дуйтеся от Ді́ви Воплоще́нному;","ра́дуйтеся Сохра́ншему Ю нетлі́нну.","Ра́дуйтеся всіх долго́в Ріши́телю;","ра́дуйтеся гріх ва́ших Іскупи́телю.","Ра́дуйтеся, Ада́ме і Є́во, ві́нче тва́рі і красото́ вселе́нния."]},{"h":"Кондак 9","ps":["Вся́коє єстество́ а́нгельськоє удиви́ся вели́кому Твоєго́ вочелові́ченія ді́лу: непресту́пнаго бо я́ко Бо́га, зря́ще всім присту́пнаго Челові́ка, нам у́бо спребива́юща, сли́шаща же от всіх: Аллилу́я."]},{"h":"Ікос 9","ps":["Ві́тіії суєму́дреннії глаго́лють де́рзостні челові́ки от безслове́сних проізведени би́ти; ми же, Ада́ма і Є́ву прароди́телі на́ша би́ти до́брі ві́дуще, к сим глаго́лем:","Ра́дуйтеся, о́тче наш і на́ша ма́ти;","ра́дуйтеся, от вас бо всяк челові́к проізи́де.","Ра́дуйтеся, афіне́йськая плете́нія растерзающії;","ра́дуйтеся, і́стину нам явля́ющії.","Ра́дуйся, Ада́ме, в день шести́й созда́нний;","ра́дуйся, Є́во, от ре́бра мужняго сотворе́нная.","Ра́дуйтеся, во Єде́мі жи́вшії;","ра́дуйтеся, ни́ні во Ца́рствії Небе́снім водворяющіїся.","Ра́дуйтеся, сві́тлостію ли́ка Боже́ственнаго па́ки наслажда́ющіїся;","ра́дуйтеся, ра́дости сея́ нікогда́же лиши́тися іму́щії.","Ра́дуйтеся, о нас моля́щіїся;","ра́дуйтеся, чад свої́х не оставля́ющії.","Ра́дуйтеся, Ада́ме і Є́во, ві́нче тва́рі і красото́ вселе́нния."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ мир, сни́де на зе́млю Сло́во Бо́жиє, сий в ло́ні О́тчі, от Ді́ви плоть прия́в, по нам бисть челові́к, і сме́ртію Своє́ю всему́ ро́ду челові́чу живо́т ві́чний дарова́; днесь Ада́м лику́єть і ра́дується Є́ва, і Спаси́телю согла́сно вопію́ть: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єсте́ ві́рним ча́дом ва́шим, догма́ти церко́вния любо́вію облобизающим, Ада́ме і Є́во; всім же во мра́ці ві́ка сего́ блуждающим і мнящим ми́ру же і челові́ку самосотворенним би́ти, живо́є обличе́ніє єсте́ і вразумле́ніє при́сноє. Сего́ ра́ди к вам взива́єм:","Ра́дуйтеся, творе́ніє Зижди́теля люби́моє;","ра́дуйтеся, от гріха́ Їм спасе́ннії.","Ра́дуйтеся, во сві́ті живу́щії;","ра́дуйтеся, тьми удали́вшіїся.","Ра́дуйтеся, зрі́нія та́їн Бо́жиїх сподо́бившіїся;","ра́дуйтеся, сим нас научающії.","Ра́дуйтеся, созерца́ти твар наставля́ющії;","ра́дуйтеся, от тва́рі ко Творцю́ ум наш возводя́щії.","Ра́дуйтеся, к Промисли́телю се́рдцем приліпи́вшіїся;","ра́дуйтеся, о Спаси́тели своє́м красующіїся.","Ра́дуйтеся, роди́теліє на́ші попечительнії;","ра́дуйтеся, ді́ти своя́ вразумляющії.","Ра́дуйтеся, Ада́ме і Є́во, ві́нче тва́рі і красото́ вселе́нния."]},{"h":"Кондак 11","ps":["Пі́ніє на́ше немощно́є не дово́льно єсть воспі́ти чу́дная діла́ Госпо́дня, І́же Ада́ма і Є́ву тлі сме́ртния ізба́ви, і на небеса́ возведе́, і соді́ла я у́ди ті́ла Своєго́, є́же єсть Це́рков, і нас, ча́да їх, в сію́ призва́, і научи́ вопи́ти немо́лчними гла́си: Аллилу́я."]},{"h":"Ікос 11","ps":["Светосіятельная світи́ла, от єди́наго і́стиннаго Сві́та світ приє́млющая, зрим вас, Ада́ме і Є́во, ві́рная ча́да ва́ша, світлостьми́ духо́вними незави́стно от вас освещаємії, і во весе́лії вам сві́тлі поє́м:","Ра́дуйтеся, ско́рби претерпі́вшії;","ра́дуйтеся, в терпі́нії преуспевшії.","Ра́дуйтеся, пропові́дници покая́нія;","ра́дуйтеся, учи́теліє упова́нія.","Ра́дуйтеся, наде́жду імі́вшії;","ра́дуйтеся, Обітова́ннаго чаявшії.","Ра́дуйтеся, Сло́вом спасе́ннії;","ра́дуйтеся, от Него́ освяще́ннії.","Ра́дуйтеся, благода́тію сія́ющії;","ра́дуйтеся, Сві́та невече́рняго прича́стници.","Ра́дуйтеся, во мра́ці пресветлем живу́щії;","ра́дуйтеся, Святу́ю Тро́йцю созерцающії.","Ра́дуйтеся, Ада́ме і Є́во, ві́нче тва́рі і красото́ вселе́нния."]},{"h":"Кондак 12","ps":["Благода́ть да́ти восхоті́в долго́в дре́вніх всіх долго́в Ріши́тель челові́ком, при́йде Собо́ю ко отшедшим Того́ благода́ті, і раздра́в рукописа́ніє, сли́шить от всіх і́же от Ада́ма: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще неізче́тния ми́лости Госпо́дні, ро́ду челові́чеському явле́нния, зрим прароди́телі на́ша, престо́лу Бо́жию в раї́ сла́дости предстоящия, і сим с несумні́нною наде́ждою і ра́достію духо́вною глаго́лем:","Ра́дуйтеся, Спа́су собеседующії;","ра́дуйтеся, о нас ходатайствующії.","Ра́дуйтеся, в тишині́ живу́щії;","ра́дуйтеся, за мир моля́щіїся.","Ра́дуйтеся, послуша́нія наста́вници;","ра́дуйтеся, трезві́нія учи́теліє.","Ра́дуйтеся, ле́сти змі́єви обличи́телі;","ра́дуйтеся ко́зней вра́жиїх разрушители.","Ра́дуйтеся, нас к небесі́ направляющії;","ра́дуйтеся го́рняя му́дрствовати научающії.","Ра́дуйтеся, упова́ніє на́ше;","ра́дуйтеся, на́ше дерзнове́ніє.","Ра́дуйтеся, Ада́ме і Є́во, ві́нче тва́рі і красото́ вселе́нния."]},{"h":"Кондак 13","ps":["О,святі́ї прароди́теліє на́ші Ада́ме і Є́во! Приймі́те ма́лоє сіє́ похвале́ніє на́ше і умолі́те Творця́ і Іскупи́теля, є́же би́ти нам с ва́ми во Ца́рствії Єго́ і со всі́ми святи́ми воспіва́ти Єму́: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгели Бо́жії просла́виша Зижди́теля, шестію́ де́ньми вся сотво́ршаго і напослі́док дній тіх челові́ка созда́вшаго, поселившаго же сего́ во Єде́мі на восто́ці і да-ровавшаго єму́ жену́ помо́щницю, і глаго́лаша Ада́му с жено́ю:","Ра́дуйтеся, творе́ніє Бо́жиє соверше́нноє;","ра́дуйтеся украше́ніє поднебе́сния.","Ра́дуйтеся, по о́бразу Бо́жию созданнії;","ра́дуйтеся, по подо́бію Єго́ сотвореннії.","Ра́дуйтеся, влади́ки тва́рі;","ра́дуйтеся, повели́телі землі́.","Ра́дуйтеся, плоть перстную нося́щії;","ра́дуйтеся, ум небе́сний іму́щії.","Ра́дуйтеся, во Єде́мі пребива́ющії;","ра́дуйтеся, от дре́ва жи́зні питающіїся.","Ра́дуйтеся, за́повіді Бо́жії приявшії;","ра́дуйтеся, я́ко за́повіді Єго́ тя́жки не суть.","Ра́дуйтеся, Ада́ме і Є́во, ві́нче тва́рі і красото́ вселе́нния."]},{"h":"Кондак 1","ps":["Ізбра́нному творе́нію Бо́жию, Ада́му пе́рвому, прародителю на́шему, со Є́вою, я́же плоть от пло́ті і кость от косте́й єго́ єсть, воспої́м, ві́рнії, похва́льная словеса́. Ви же, а́ще і па́дшії іногда́ і рая́ лишеннії, оба́че по́двигом Но́ваго Ада́ма, Є́вою второ́ю в мир прише́дшаго, спасе́ннії і на небеса́ возведе́ннії, молі́теся о нас, ча́діх ва́ших, взива́ющих вам:","Ра́дуйтеся, Ада́ме і Є́во, ві́нче тва́рі і красото́ вселе́нния."]},{"h":"Молитва","ps":["К вам, прароди́телем на́шим, о Ада́мі і Є́во, прибіга́єм ми, не́мощная ча́да ва́ша. Воззрі́те ми́лостивно на нас с висоти́ небе́сния ва́шея сла́ви і бу́діте нам помо́щници во іскуше́ніях і соблазнах, от врага́ ро́да челові́чеськаго нам прибива́ющих. А́ще і соблазнилися єсте́ дре́вле льстивними глаго́ли зміє́вими і лишилися рая́ сла́дости, преби́сте оба́че оста́ток земни́я жи́зні ва́шея в покая́нії і сокруше́нії о неразу́мії своє́м, і та́ко снидо́сте во оби́телі печа́лі. В послі́док же дній при́йде Обетованний, є́же сокруши́ти держа́ву кня́зя ми́ра сего́. Пред спаси́тельними же страда́ньми Свої́ми предпосла́ ко отшедшим живота́ сего́ пропові́дника покая́нія, і́же бисть предте́ча Єго́ на землі́ і в преіспо́дніх землі́. Ви же с ра́достію послу́шасте слове́с сего́, разуміва́юще, я́ко о Сі́мені ва́шем глаго́леть. По ма́лі же вре́мене потрясе́ся ад і огорчи́ся, сни́де бо Разруши́тель а́да. Огорчи́ся ад, і́бо упраздни́ся, огорчи́ся, і́бо пору́ган бисть, огорчи́ся, і́бо умертви́ся, огорчи́ся, і́бо связа́ся. Ви же возвесели́стеся і взиграсте ду́хом, зря́ще Іскупи́теля ва́шего, по пло́ті от вас проісшедшаго, Бо́га же су́ща безнача́льна і Отцю́ соприсносу́щна. Си́це у́бо і нас сподо́біте земно́є сіє́ і многоско́рбноє житіє́ в покая́нії прейти́, в бу́дущей же жи́зні зрі́ти ви́ну Спаси́теля душ на́ших і Го́спода на́шего Ісу́са Христа́, Єму́же со Отце́м і Ду́хом подоба́єть честь і поклоне́ніє ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Акафіст праведному Іоанну Кормянському","e":"Akathist to the Righteous John of Kormya","secs":[{"h":"Кондак 1","ps":["Ізбра́нний уго́дниче Христо́в, свя́те пра́ведне Іоа́нне, от чре́ва ма́тері на служе́ніє Бо́гу ізбра́нне і юро́дивим ста́рцем служи́телем Це́ркві Госпо́дней предрече́нне, житіє́м твої́м пра́ведником Бо́жиїм уподо́бивийся, ті́мже і Госпо́дь обогати́ тя да́ром прозрі́нія і ісціле́нія. Ми же, ча́да Це́ркві Правосла́вния, с любо́вію да зове́м ті:","Ра́дуйся, Іоа́нне пресви́тере, чудотво́рче і ціли́телю."]},{"h":"Ікос 1","ps":["А́нгельстії си́ли на небесе́ возра́довашася, а́ки предрече́нно єще́ во чре́ві ма́тері би́ти тебі́ служи́телем Це́ркві Бо́жієй, о́тче пра́ведне Іоа́нне. Ті́мже просла́ви тя Госпо́дь в житії́ твоє́м сла́вне, да́ром прозрі́нія обогати́ тя, істо́чник ісціле́ній соді́ла мо́щі твоя́ нетлі́нная. Ми же, ві́дуще сла́ву Бо́жию в тебі́ нам я́вльшуюся, да зове́м ті с ра́достію ве́лієй:","Ра́дуйся, Це́ркві Правосла́вния но́вая похвало́;","Ра́дуйся, Ца́рствія Бо́жия небожи́телю.","Ра́дуйся, да́ром прозрі́нія одаре́нний;","Ра́дуйся, да́ром ісціле́нія обогаще́нний.","Ра́дуйся, да́льняя а́ки бли́жняя предви́дівий;","Ра́дуйся, во́лю Бо́жию лю́дям віща́вий.","Ра́дуйся, служи́телем Це́ркві предрече́нний;","Ра́дуйся, Богоро́дицею просла́вленний.","Ра́дуйся, Іоа́нне пресви́тере, чудотво́рче і ціли́телю."]},{"h":"Кондак 2","ps":["Ви́ді оте́ць твой пресви́тер зна́меніє Бо́жиє в рождестві́ твоє́м, креща́я тя Іоа́нном нарече́ в честь апо́стола любве́, Го́споду же возгласи́ хвале́бную піснь со А́нгели: Аллилу́я."]},{"h":"Ікос 2","ps":["Бисть о́трочество твоє́ в хра́мі Покро́ва Богоро́диці прохожда́ємо, Єя́ же те́плим засту́пничеством і води́тельством охраня́ємо, а́ки птене́ць Бо́гу в же́ртву непоро́чну принесе́нний, та́ко і ти, Го́сподом возлю́бленний, ізмла́да служи́ти Єму́ ізбра́нне, похва́льную піснь прино́сим і ми тебі́ такову́ю:","Ра́дуйся, Бо́гом ізмла́да ізбра́нне;","Ра́дуйся, ста́рцю роди́телю послу́шен би́вий.","Ра́дуйся, моли́тви ма́тері твоєя́ плод до́брий яви́вий;","Ра́дуйся, житіє́ богоуго́дноє роди́телей твої́х возлюби́вий.","Ра́дуйся, плод моли́тви їх, а́ки цвіт расцве́тший;","Ра́дуйся, наде́ждо їх і весе́ліє.","Ра́дуйся, труди́ ста́рческиє їм облегчи́вий;","Ра́дуйся, ста́рость їх упоко́ївий.","Ра́дуйся, Іоа́нне пресви́тере, чудотво́рче і ціли́телю."]},{"h":"Кондак 3","ps":["Ізбра́ тя Госпо́дь на служе́ніє сла́вноє, ви́дя душі́ твоєя́ чистоту́, поста́ви тя па́стирем Це́ркві Бо́жієй і ста́до слове́сних ове́ць тебі́ вручи́, да пасе́ши єго́ со усе́рдієм, поя́ Го́споду піснь: Аллилу́я."]},{"h":"Ікос 3","ps":["Боже́ственная Благода́ть, немощна́я врачу́ющая і оскудіва́ющая восполня́ющая, воспо́лнися в тебі́, сосу́де ізбра́нний Ду́ха Свята́го, пра́ведне о́тче наш Іоа́нне. Поста́ви тя світи́льника верху́ гори́ висо́кия, ми же, ви́дяще ди́вниє діла́ Бо́жия, во умиле́нії зове́м ті та́ко:","Ра́дуйся, пресви́тере Бо́гом ізбра́нне;","Ра́дуйся, світи́льниче, во тьмі ві́ка возсія́вший.","Ра́дуйся, ста́до Христо́во от волко́в хи́щних упа́сший;","Ра́дуйся, ча́да духо́вния ко Христу́ приведи́й.","Ра́дуйся, па́стирю нелі́ностний;","Ра́дуйся, пра́ведному Іоа́нну Кроншта́дтському подража́вий.","Ра́дуйся, ду́ха зло́би от ста́да Христо́ва отгна́вий;","Ра́дуйся, заблу́ждшия о́вці взиска́вий.","Ра́дуйся, Іоа́нне пресви́тере, чудотво́рче і ціли́телю."]},{"h":"Кондак 4","ps":["Ди́вний моли́твенник яви́лся єси́, о́тче пра́ведне Іоа́нне: не то́кмо во дні, но і в но́щі предава́лся єси́ Го́сподеві в моли́тві, воспіва́я со а́нгели Єму́ хвале́бную піснь: Аллилу́я."]},{"h":"Ікос 4","ps":["Ви́дяще тя щедрода́теля ве́лія, си́рия і вдови́ці притека́ху к тебі́, о́тче, ти же одари́л єси́ їх дара́ми коєму́ждо на потре́бу, сме́рті гла́дния їх избавля́я, ті́мже і ми мо́лим тя: ізба́ви і нас от гла́да і нестроє́нія в битії́ земні́м сем: ми же благода́рно тебі́ воспоє́м:","Ра́дуйся, к земни́м бла́гам пристра́стія не імі́вий;","Ра́дуйся, вдови́цю со ча́ди єя́ от гла́дния сме́рті препита́вий.","Ра́дуйся, ни́щих одари́вий;","Ра́дуйся, си́рих защити́вий.","Ра́дуйся, стра́нников прия́вий;","Ра́дуйся, наги́х оді́явий.","Ра́дуйся, а́лчущих і жа́ждущих уті́шивий;","Ра́дуйся, я́ко в темни́ціх і больни́ціх отве́рженних посіти́вий.","Ра́дуйся, Іоа́нне пресви́тере, чудотво́рче і ціли́телю."]},{"h":"Кондак 5","ps":["Богото́чний істо́чник яви́лся єси́, о́тче Іоа́нне, си́лою моли́тви твоєя́ бі́си отгоня́я, боля́щия ісціля́я, от гріха́ на путь пра́вий заблу́ждшия наставля́я, не оста́ви і нас си́рих і убо́гих, но твої́ми моли́твами спаса́ємі, і ми воспої́м хвале́бную піснь в Тро́йці сла́вимому Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дяще по́двиги Твоя́ земна́я, пресви́тере сла́вне Іоа́нне, Христо́с да́ром ісціле́ній тя одари́, да і ми, ві́дуще в тебі́ сосу́д си́ли Бо́жієй, преіспо́лненний вся́кия цільби́ і благости́ні, зове́м ті си́це:","Ра́дуйся, істо́чниче ісціле́ній;","Ра́дуйся, сосу́де Бо́гом ізбра́нний.","Ра́дуйся, враче́м безме́здним уподо́бивийся;","Ра́дуйся, болі́зні неісці́льния ісціли́вий.","Ра́дуйся, врача́ми оста́вленних не оста́вивий;","Ра́дуйся, ті́лу моєму́ здра́віє дарова́вий.","Ра́дуйся, проще́ніє гріхо́в мої́х у Го́спода іспроси́вий;","Ра́дуйся, ду́шу мою́ от сна лі́ности воздви́гнувий.","Ра́дуйся, Іоа́нне пресви́тере, чудотво́рче і ціли́телю."]},{"h":"Кондак 6","ps":["Хотя́ уподо́битися стра́нником ми́ра сего́ в Ла́вру Ки́євськую послі́довал єси́, та́мо благослове́ніє от ста́рцев єя́ прия́л єси́, да житіє́м свої́м преподо́бним подража́я, воспіва́єши со пече́рськими святи́ми: Аллилу́я."]},{"h":"Ікос 6","ps":["Но́ваго не́ба і но́вия землі́ в обітова́нії Христо́ві ожида́л єси́, да і нас подража́ти тебі́ научи́л єси́: на всяк день Го́споду угожда́ти, в моли́тві нелі́ностно пребива́ти, в пості́ не разслабля́тися, в труді́ плоть умерщвля́ти і тебі́ воспіва́ти:","Ра́дуйся, моли́твою не́бо і зе́млю соєдини́вий;","Ра́дуйся, во виді́нії ру́ці ко Го́споду простира́вий.","Ра́дуйся, прише́ствіє Богоро́диці в хра́мі предви́дівий;","Ра́дуйся, храм в честь Покро́ва Єя́ сооруди́ти благослови́вий.","Ра́дуйся, мі́сто строї́тельства єго́ указа́вий;","Ра́дуйся, со пресві́тери єго́ освяти́вий.","Ра́дуйся, в нем же мі́сто сла́вно себі́ угото́вавий;","Ра́дуйся, я́ко і ни́ні тілесе́м нетлі́нним в нем почива́єши.","Ра́дуйся, Іоа́нне пресви́тере, чудотво́рче і ціли́телю."]},{"h":"Кондак 7","ps":["Провозві́стник гряду́щаго іспита́нія яви́лся єси́, землі́ Росси́йстій слеза́ми і кро́вію оми́тися возвіща́л єси́, сле́зи те́плиє пред Лице́м Бо́жиїм пролива́л єси́, да преміни́ть Госпо́дь гнів Свой на ми́лость над на́ми, воспіва́я Єму́ ві́чную піснь: Аллилу́я."]},{"h":"Ікос 7","ps":["Єгда́ приї́де скорб на зе́млю на́шу, ізба́ви тя Госпо́дь сего́ стра́шнаго виді́нія, призва́ тя в ра́йськия оби́телі, ти же завіща́л єси́ нам я́ко к живо́му к тебі́ приходи́ти і мольби́ своя́ ізлива́ти пред тобо́ю. Ми же, ісполня́я за́повідь твою́, во умиле́нії се́рдця зове́м ті та́ко:","Ра́дуйся, я́ко нетлі́нієм Госпо́дь тя просла́ви;","Ра́дуйся, я́ко душе́ю пред Творцо́м предстої́ши.","Ра́дуйся, я́ко тілесе́м с на́ми пребива́єши;","Ра́дуйся, я́ко ско́рбем і печа́лем на́шим вне́млеши.","Ра́дуйся, я́ко отра́ду боже́ственную нам подає́ши;","Ра́дуйся, я́ко і воздиха́ніє на́ше сли́шиши.","Ра́дуйся, я́ко ра́дованію на́шему сора́дуєшися;","Ра́дуйся, я́ко чад свої́х не оставля́єши.","Ра́дуйся, Іоа́нне пресви́тере, чудотво́рче і ціли́телю."]},{"h":"Кондак 8","ps":["Ди́вно просла́ви Госпо́дь тілесе́ твоє́, пра́ведне о́тче наш Іоа́нне. Гроб твой тлі́нію землі́ не предаде́ся і тілесе́ твоє́, я́ко адама́нт драгоці́нний, в нем сохрани́ся. Мно́гая лі́та па́м'ять твоя́ забве́на бисть, но Христо́с тя я́ко світи́льник на сві́щницю поста́ви, да мрак ми́ра сего́ озари́ши. Ми же Го́спода просла́вим пі́снію: Аллилу́я."]},{"h":"Ікос 8","ps":["Всяк во́зраст стар і млад просла́ви тя, о́тче Іоа́нне, єгда́ обрі́теся нетлі́нноє тілесе́ твоє́ і мно́гая зна́менія і чудеса́ соверша́шася, боля́щії ісцеля́шеся, сліпи́є прозрева́ша, хро́мії хожда́ше. Ми же, ви́дяще в тебі́ істо́чник ісціле́ній, со слеза́ми воспіва́єм ті си́це:","Ра́дуйся, пресви́терами сла́вно обрете́нний;","Ра́дуйся, наро́дом правосла́вним почита́ємий.","Ра́дуйся, сліпи́м прозрі́ніє подаю́щий;","Ра́дуйся, хроми́х ісціли́вий.","Ра́дуйся, рассла́бленних жи́лами укріпи́вий;","Ра́дуйся, то́ки кро́ве останови́вий.","Ра́дуйся, отча́янних во врачева́нії не оста́вивий;","Ра́дуйся, в ско́рбіх ду́шу мою́ уті́шивий.","Ра́дуйся, Іоа́нне пресви́тере, чудотво́рче і ціли́телю."]},{"h":"Кондак 9","ps":["Всіх приходя́щих ко гро́бу твоєму́ не оставля́єши, коєму́ждо на по́льзу душі́ подає́ши і Го́спода умоля́єши: да прише́дшії к тебі́ в ско́рбіх і печа́ліх істоще́нни не оти́дуть, но істо́чник утіше́нія в тебі́ обрету́ть, Спа́су душ на́ших воззову́ть: Аллилу́я."]},{"h":"Ікос 9","ps":["Віті́ї богохва́льнії не возмо́гуть досто́йно восхвали́ти пучи́ну чуде́с, чрез тя Бо́гом явле́нную. Во виді́ніях со́ніїх явля́єшися і ві́ру слабове́рних укріпля́єши, да с ра́достію і наде́ждою ко гро́бу твоєму́ притека́ють і се́рдцем чи́стим тебі́ зову́ть:","Ра́дуйся, я́ко ві́ра правосла́вная тобо́ю укріпи́ся;","Ра́дуйся, я́ко любо́в тобо́ю умно́жися.","Ра́дуйся, я́ко наде́жда на́ша оправда́ся;","Ра́дуйся, кри́не ра́йськаго прозябе́нія.","Ра́дуйся, кимва́ле восклиця́нія;","Ра́дуйся, гу́сли сладкозву́чниє.","Ра́дуйся, ковче́же позлаще́нний;","Ра́дуйся, ка́меню драгоці́нний.","Ра́дуйся, Іоа́нне пресви́тере, чудотво́рче і ціли́телю."]},{"h":"Кондак 10","ps":["Світ чуде́с но́вих ізлія́ Госпо́дь Вседержи́тель, єгда́ бисть обрі́теніє нетлі́ннаго тілесе́ твоєго́. Ди́вний огнь от іко́ни Цари́ці Небе́сния на гроб твой ізи́де, ми же, ви́дівше сла́вная чудеса́ сія́, ві́рою окре́пшею Отця́ Небе́снаго просла́виша: Аллилу́я."]},{"h":"Ікос 10","ps":["Світопода́тель Госпо́дь, жела́я спасе́нія вся́кой пло́ті челові́чеськой, проро́ки і апо́столи на про́повідь посила́я, му́ченики і святи́телі вінце́м нетлі́нним вінча́я. Та́ко і тя, о́тче наш Іоа́нне, с преподо́бними в ли́кі пра́ведних просла́ви, а нас научи́ тебі́ воспіва́ти:","Ра́дуйся, до́брая вітв виногра́да Христо́ва;","Ра́дуйся, лозо́ многоплодови́тая.","Ра́дуйся, ві́рния ко Христу́ приведи́й;","Ра́дуйся, заблу́ждшия не отри́нувий.","Ра́дуйся, мног плод духо́вний о Христі́ сотвори́вий;","Ра́дуйся, путь спасе́нія нам указа́вий.","Ра́дуйся, я́ко же і сам ко Христу́ путе́м ті́сним сле́довавий;","Ра́дуйся, я́ко і нас на стезю́ пра́вди наста́вивий.","Ра́дуйся, Іоа́нне пресви́тере, чудотво́рче і ціли́телю."]},{"h":"Кондак 11","ps":["Пі́ніє хвале́бноє прино́сять ті, о́тче пра́ведне Іоа́нне, обрі́тшії спасе́ніє твої́ми моли́твами от бід і скорбе́й і вся́ких напа́стей, да ку́пно с тобо́ю ра́достно пою́ть Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рним сві́том бисть житіє́ твоє́, о́тче пра́ведне Іоа́нне. Да і нам грі́шним путь ко спасе́нію указу́я, зарю́ о́бщаго воскресе́нія предвозвіща́я, малові́рния увіря́я, ві́рния подкріпля́я, ті́мже ку́пно да зове́м ті:","Ра́дуйся, па́стирю наш вселюби́мий;","Ра́дуйся, защи́тниче наш от враго́в спасе́нія непреобори́мий.","Ра́дуйся, ко́зні дия́вольськия моли́твою побіди́вий;","Ра́дуйся, Христа́ житіє́м твої́м просла́вивий.","Ра́дуйся, Богоро́диці ізбра́нниче нело́жний;","Ра́дуйся, сослуже́нія А́нгельськаго удосто́ївийся.","Ра́дуйся, в со́ніях на моли́тву ко хода́тайству твоєму́ призва́вий;","Ра́дуйся, я́ко і мене́ грі́шнаго Благода́ті Бо́жия не лиши́вий.","Ра́дуйся, Іоа́нне пресви́тере, чудотво́рче і ціли́телю."]},{"h":"Кондак 12","ps":["Благода́ть сви́ше ниспосли́ всім нам, притека́ющим с любо́вію к ра́ці моще́й твої́х, і іспроси́ у Го́спода проще́ніє согріше́ній на́ших, боля́щим же і стра́ждущим ісціле́ніє да́руй, да благода́рственно всі вопіє́м ди́вному во святи́х Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Житіє́ твоє́ сла́вно Госпо́дь просла́ви, челові́ка небе́снаго і а́нгела земна́го нам показа́вий. Ми же, ві́дуще мно́гая зна́менія у гро́ба твоєго́ проісходя́ща, мо́лим тя, о́тче наш Іоа́нне, да твої́ми моли́твами укріпи́ться в нас ві́ра правосла́вная, в ней же на́ше спасе́ніє, і тебі́ ми поє́м восхвале́ніє:","Ра́дуйся, фимія́м кади́льний Бо́гу прине́сший;","Ра́дуйся, во ієре́єх єму́ послужи́вий.","Ра́дуйся, тайнозри́телю Бо́жия благода́ті;","Ра́дуйся, покрови́телю сиро́т і вдов.","Ра́дуйся, єресе́й іскорени́телю;","Ра́дуйся, пра́вия ві́ри насади́телю.","Ра́дуйся, я́ко тобо́ю Госпо́дь просла́вися;","Ра́дуйся, я́ко тобо́ю Ві́ра Правосла́вная утверди́ся.","Ра́дуйся, Іоа́нне пресви́тере, чудотво́рче і ціли́телю."]},{"h":"Кондак 13","ps":["Опреблаги́й уго́дниче Бо́жий, святи́й пра́ведний о́тче наш Іоа́нне, прийми́ сіє́ ма́лоє моле́ніє на́ше а́ще недосто́йні тебі́ приноси́моє, но с любо́вію сино́внею припа́дающе вопіє́м ті: ізба́ви нас от неду́га душе́внаго і болі́зні тіле́сния, да і ми в покая́нії плод добр Го́сподеві принесе́м і с тобо́ю в Ца́рствії Небе́снім Єму́ воззове́м: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгельстії си́ли на небесе́ возра́довашася, а́ки предрече́нно єще́ во чре́ві ма́тері би́ти тебі́ служи́телем Це́ркві Бо́жієй, о́тче пра́ведне Іоа́нне. Ті́мже просла́ви тя Госпо́дь в житії́ твоє́м сла́вне, да́ром прозрі́нія обогати́ тя, істо́чник ісціле́ній соді́ла мо́щі твоя́ нетлі́нная. Ми же, ві́дуще сла́ву Бо́жию в тебі́ нам я́вльшуюся, да зове́м ті с ра́достію ве́лієй:","Ра́дуйся, Це́ркві Правосла́вния но́вая похвало́;","Ра́дуйся, Ца́рствія Бо́жия небожи́телю.","Ра́дуйся, да́ром прозрі́нія одаре́нний;","Ра́дуйся, да́ром ісціле́нія обогаще́нний.","Ра́дуйся, да́льняя а́ки бли́жняя предви́дівий;","Ра́дуйся, во́лю Бо́жию лю́дям віща́вий.","Ра́дуйся, служи́телем Це́ркві предрече́нний;","Ра́дуйся, Богоро́дицею просла́вленний.","Ра́дуйся, Іоа́нне пресви́тере, чудотво́рче і ціли́телю."]},{"h":"Кондак 1","ps":["Ізбра́нний уго́дниче Христо́в, свя́те пра́ведне Іоа́нне, от чре́ва ма́тері на служе́ніє Бо́гу ізбра́нне і юро́дивим ста́рцем служи́телем Це́ркві Госпо́дней предрече́нне, житіє́м твої́м пра́ведником Бо́жиїм уподо́бивийся, ті́мже і Госпо́дь обогати́ тя да́ром прозрі́нія і ісціле́нія. Ми же, ча́да Це́ркві Правосла́вния, с любо́вію да зове́м ті:","Ра́дуйся, Іоа́нне пресви́тере, чудотво́рче і ціли́телю."]},{"h":"Молитва","ps":["Опресла́вний уго́дниче Бо́жий, святи́й пра́ведний о́тче наш Іоа́нне! Ни́ні припа́дая к ра́ці с цільбоно́сними моща́ми твої́ми, із глубини́ душі́ тебі́ зове́м, о свя́тче Бо́жий, не отри́ни нас, си́рих і убо́гих, во грісі́х рожде́нних і плод досто́йний покая́нія не прине́сших. Тебі́, я́ко імі́ющему дерзнове́ніє пред Го́сподем, со слеза́ми взива́єм: ісціли́ болі́зні на́ша тіле́сния, укріпи́ ду́ші на́ша малові́рния. Умоли́ Го́спода дарова́ти нам ра́дость покая́нія і житія́ на́шего ісправле́ніє. Іспроси́ у Бо́га землі́ на́шей плодоро́діє, дожді́ ми́рни і возду́хи благорастворе́нни. Це́рков на́шу твої́ми моли́твами нези́блемо огради́ от єресе́й і раско́лов. Оби́тель сію́ і храм сей до сконча́нія ві́ка сохрани́, і по кончи́ні житія́ на́шего во оби́телі Отця́ Небе́снаго нас водвори́, да і ми та́мо ку́пно с тобо́ю і всі́ми святи́ми просла́вим в Тро́йці Єди́наго Бо́га Отця́, і Си́на, і Ду́ха Свята́го.","Амі́нь."]},{"h":"Тропар, глас 4","ps":["Свя́тче Бо́жий, о́тче наш пра́ведне Іоа́нне, / пресвитере сла́вне стада́ Христо́ва, / свя́то житіє́ твоє́ соверши́в, / да́ром прозрі́нія і ісціле́нія Госпо́дь тя одари́, / і ни́ні нетлі́нним тілесе́м с на́ми пребива́я, / моли́ Христа́ Бо́га на́шего, / да спасе́ть Госпо́дь душі́ на́ша, / почита́ющих, блаже́нне, святу́ю па́м'ять твою́."]},{"h":"Кондак, глас 6","ps":["От чре́ва ма́тері ди́вно прорече́нний, / ізбра́нник Бо́жий яви́лся єси́, / не то́кмо в житії́ Бо́гом просла́вленний, / но і по сме́рті нас не оста́вивий, / в дивном явле́нії ру́ці за род правосла́вний ко Христу́ простира́я, / моли́ся Влади́ці всіх царю́ / поми́ловати нас, чту́щих святу́ю па́м'ять твою́."]},{"h":"Величання","ps":["Велича́єм тя, святи́й пра́ведний о́тче наш Іоа́нне, / і чтим святу́ю па́м'ять твою́, / ти бо мо́лиши за нас Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст святим рівноапостольним царям Костянтину і Олені","e":"Akathist to the Holy Equal-to-the-Apostles Emperors Constantine and Helen","secs":[{"h":"Кондак 1","ps":["Ізбра́ннії предві́чним Царе́м, святі́ї равноапо́стольнії Константи́не і Єле́но, на всеми́рноє воздвиже́ніє Животворя́щаго і Спаси́тельнаго Креста́ Госпо́дня, і́мже соді́лася спасе́ніє ро́да челові́чеськаго, іскупленнаго кро́вію пригвожде́ннаго на нем А́гнця Бо́жия, да всі пра́веднії і грі́шнії благода́рственно взива́ють вам:","Ра́дуйтеся, святі́ї равноапо́стольнії Константи́не і Єле́но, обрі́тшії Крест Госпо́день, ору́жіє спаси́тельноє."]},{"h":"Ікос 1","ps":["А́нгельський собо́р на землі́ зря́ше ве́ліє чу́до — ка́ко обрі́теся Свято́є Дре́во, на мно́го літ в ні́дріх землі́ безду́шним ка́менієм храни́моє, ни́ні же рука́ми архієре́йськими возноси́моє, лю́діє же ви́дівше сіє́, ниць на зе́млю падо́ша, сле́зно вопія́: \"Го́споди, поми́луй! Го́споди, поми́луй! Го́споди, поми́луй!\" Вас же, святі́ї равноапо́стольнії Константи́не і Єле́но, смире́нно велича́ху:","Ра́дуйся, блаже́нная ма́ти, зіло́ возлюби́вшая Христа́;","ра́дуйся, боговінча́нний си́не, слуго́ Небе́снаго Царя́.","Ра́дуйтеся, земні́ї А́нгели і небе́снії челові́ци;","ра́дуйтеся, строї́теліє та́їн Бо́жиїх.","Ра́дуйтеся, я́ко ва́ми не́бо і земля́ духо́вно возра́довашася;","ра́дуйтеся, я́ко от всіх земноро́дних вку́пі просла́вишася.","Ра́дуйтеся, досто́йнії носи́теліє і́мене Христо́ва;","ра́дуйтеся, два світи́ла вели́кая во вселе́нній.","Ра́дуйтеся, святі́ї равноапо́стольнії Константи́не і Єле́но, обрі́тшії Крест Госпо́день, ору́жіє спаси́тельноє."]},{"h":"Кондак 2","ps":["Ви́дів сла́вний Константи́н во вре́м'я бра́ні с Максентієм в полу́дні Крест на не́бі, сві́том сія́ющий, і пи́сьмена \"Сим побіжда́й\", повелі́ оковати все ору́жіє і шле́ми бранниє, да до конця́ побіди́во врага́ по́мощію Кре́стною, воспою́ть расп'я́тому Христу́ побі́дную піснь: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум твой, не просвіще́н єще́ святи́м креще́нієм, царю́ Константи́не, просвіти́ Госпо́дь во сні но́щію, науча́я побіди́ти врага́ крестним зна́менієм, ми же, див'я́ся таково́му Про́мислу Бо́жию о тебі́, взива́єм си́це:","Ра́дуйся, двукратним виді́нієм Креста́ сви́ше озаре́нний;","ра́дуйся, па́че всіх царе́й земни́х превознесе́нний.","Ра́дуйся, сви́ше предизбранний на апо́стольськоє служе́ніє;","ра́дуйся, побіди́телю враго́во ви́димих і неви́димих.","Ра́дуйся, Крест Госпо́день зіло́ просла́вивий;","ра́дуйся, Це́ркві Христо́вой вся си́ли отда́вий.","Ра́дуйся, врага́ спасе́нія челові́чеськаго посрами́вий;","ра́дуйся, честни́м Кресто́м главу́ єго́ сокруши́вий.","Ра́дуйтеся, святі́ї равноапо́стольнії Константи́не і Єле́но, обрі́тшії Крест Госпо́день, ору́жіє спаси́тельноє."]},{"h":"Кондак 3","ps":["«Си́лою Креста́ во бра́ні, - ві́дал єси́, богому́дре Константи́не - Аз спасо́х град сей от враго́в, і се́рдце моє́ уя́звлено любо́вію расп'я́таго Христа́, Єго́же чту, Єму́же покланя́юся і не возбраняю лю́б'ящим Єго́ пі́ти блаже́нную піснь: Аллилу́я»."]},{"h":"Ікос 3","ps":["Імі́я в се́рдці чу́вство живи́я христия́нськия ві́ри, вели́кий Константи́н повелі́, да сокруша́ться і́доли і да сози́ждуться хра́ми, іді́же со́нми А́нгелов і ли́ки пра́ведних ви́ну мо́лять своєго́ Созда́теля. Ми же недосто́йнії, прося́ще о ми́рі ми́ра і добро́м отві́ті на Стра́шнім Суди́щі Христо́ві, зове́м вам:","Ра́дуйтеся, пе́рвії во христия́ніх ца́ріє;","ра́дуйтеся, милосе́рдієм і вла́стію укра́шеннії.","Ра́дуйтеся, любо́вію і пра́вдою одеяннії;","ра́дуйтеся, от вра́жиїх пре́лестей ізба́вленнії.","Ра́дуйтеся, уста́вов церко́вних храни́теліє;","ра́дуйтеся, ді́вства і цілому́дрія люби́теліє.","Ра́дуйтеся, язи́чеськия хра́ми на землі́ упразднившії;","ра́дуйтеся, день воскре́сний пра́здновати установившії.","Ра́дуйтеся, святі́ї равноапо́стольнії Константи́не і Єле́но, обрі́тшії Крест Госпо́день, ору́жіє спаси́тельноє."]},{"h":"Кондак 4","ps":["Бурния пото́ки христия́нськия кро́ве твої́м повелі́нієм, святи́й Константи́не, прия́ша коне́ць; су́щії в темниціх получи́ша осла́бу, кри́ющіїся во пеще́рах і гора́х всп'ять возвраща́хуся, і ча́да Це́ркве лобза́нієм святи́м во об'ятії встречаху друг дру́га, воспіва́я Бо́гу піснь хвали́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше му́ченици і страда́льці Христо́ви повелі́ніє твоє́, богоблаже́нне Константи́не, да свобо́дно іспові́дають ві́ру Христо́ву, возвесели́шася і со слеза́ми ра́дости воспіва́ху ті си́це:","Ра́дуйся, вели́каго Ри́ма украше́ніє;","ра́дуйся, у́зников Христо́вих свобожде́ніє.","Ра́дуйся, язи́чеськаго ми́ра упраздне́ніє;","ра́дуйся, і́долов і куми́ров сокруше́ніє.","Ра́дуйся, прав і зако́нов утвержде́ніє;","ра́дуйся, чар волше́бних і гада́ній карательноє запреще́ніє.","Ра́дуйся, о Це́ркві пеки́йся, а́ки чадолюби́вая ма́ти;","ра́дуйся, возбранивий осужде́нних на крестіх расп'я́тіє.","Ра́дуйтеся, святі́ї равноапо́стольнії Константи́не і Єле́но, обрі́тшії Крест Госпо́день, ору́жіє спаси́тельноє."]},{"h":"Кондак 5","ps":["Воскресе́ніє Христо́во ви́дівше, воспіва́ху лю́діє: се Крест, і́мже при́йде ра́дость всему́ ми́ру. Неві́домо бисть ми́ру ору́жіє, і́мже но́вий Дави́д побіди́ смерть, сокрито бисть от поклоне́нія ві́рних люді́й, А́нгели то́кмо охраняху честни́й Крест, немо́лчно воспіва́я: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дя осмидесятилетняя ста́риця, богому́драя ма́ти Єле́на, се́рдце твоє́, пречу́дне царю́ Константи́не, жела́нієм іспо́лнено к прославле́нію Свята́го Дре́ва, сама́ со тща́нієм приє́млеть труди́, да откри́єть сокро́вище на поклоне́ніє всім язи́ком, с любо́вію зову́щих вам такова́я:","Ра́дуйтеся, святі́ї равноапо́стольнії Константи́не і Єле́но, ца́ріє прему́дрії;","ра́дуйтеся, дво́їце свята́я, Бо́гом возлю́бленная.","Ра́дуйтеся, любо́вію к Нему́ а́ки Серафи́ми пламеневшії;","ра́дуйтеся, ре́вностію а́ки Апо́столи послужи́вшії.","Ра́дуйтеся, усе́рдієм ва́шим я́ко жени́ с ми́ри прише́дшії;","ра́дуйтеся, за по́двиги ва́ша от всіх земноро́дних славимиє.","Ра́дуйтеся, я́ко А́нгели с ва́ми лику́ють на небесі́;","ра́дуйтеся, я́ко челові́ци ви́ну восхваля́ють вас на землі́.","Ра́дуйтеся, святі́ї равноапо́стольнії Константи́не і Єле́но, обрі́тшії Крест Госпо́день, ору́жіє спаси́тельноє."]},{"h":"Кондак 6","ps":["Пропові́дником та́йни, іді́же бі треблаже́нноє Дре́во, бисть ні́кий Іу́да, і́же не хоті́ указати мі́сто сіє́, сего́ ра́ди ізнурен бисть гла́дом во глубині́ кладенця́ по повелі́нію свято́й цари́ці Єле́ни, є́йже Дух Святи́й откри́, да употреби́ть вся́коє уси́ліє для взиска́нія Креста́ Госпо́дня на ра́дость правосла́вним христия́ном, пою́щим Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ луч Боже́ственнаго сві́та в се́рдці Іу́ди, непреклоннаго досе́лі к проше́ніям і увещаніям богомудрой цари́ці Єле́ни, і́же, отве́рз уста́, глаго́лаше: \"Близ Голго́фи, в ка́пищі Венери, обря́щете Крест ва́шего Христа́\". Отто́лі начата іска́ти, мно́гі труди́ понесоша, не обрі́тше же сокро́вища, зіло́ ізнемо́гша. Єгда́ же ощути́ша ве́ліє благоуха́ніє із нідр землі́, усугубиша труди́ і обріто́ша три креста́, тогда́ ві́рнії лю́діє прославля́ху вас со слеза́ми:","Ра́дуйтеся, треблаже́ннаго Дре́ва усердниє іскателіє;","ра́дуйтеся, діла́ апо́стольськаго неленостниє продолжателіє.","Ра́дуйтеся, торжество́ ві́ри правосла́вния явившії;","ра́дуйтеся, лю́ди, чту́щії Крест Госпо́день, зіло́ возвеселившії.","Ра́дуйтеся, возду́х животво́рним зна́менієм освяти́вшії;","ра́дуйтеся, обрі́тенієм Креста́ оста́вившії лю́дем па́м'ять ві́чную.","Ра́дуйтеся, прине́сшії всему́ ми́ру ра́дость безконе́чную.","Ра́дуйтеся, святі́ї равноапо́стольнії Константи́не і Єле́но, обрі́тшії Крест Госпо́день, ору́жіє спаси́тельноє."]},{"h":"Кондак 7","ps":["Хотя́ тща́тельно уві́діти Крест, на не́мже принесе́ся Же́ртва Свята́я, да не воздадя́ть честь Креста́ іно́му, блаже́нний патріа́рх Мака́рій повелі́ возложи́ти крести́ на боля́щу і ме́ртва, сі́ї же ожи́ша і здра́ві бя́ху, тогда́ лю́діє, ви́дівше чу́до, падо́ша ниць до землі́, Животворя́щему Кресту́, побіди́телю сме́рти і а́да, пою́ще: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вий христия́нський храм созида́єть му́драя цари́ця Єле́на на Голго́фі для всеми́рнаго воздвиже́нія Животворя́щаго Креста́ Госпо́дня, безчи́сленноє же мно́жество люді́й моли́ша блаже́ннаго патріа́рха Мака́рія, да сподо́б'яться узрі́ти Госпо́день Крест. Он же, смире́нія сий іспо́лнен, с освяще́нним собо́ром висо́ко под'яша Крест, да ви́дять всі; зря́ще сіє́, племена́ і язи́ци с благогові́нієм і ра́достію восклиця́ху:","Ра́дуйся, Треблаже́нноє Дре́во, і́мже спасе́ся дво́їця первозда́нная;","ра́дуйся, Честно́є Дре́во, і́мже ад іспусти́ у́зники.","Ра́дуйся, Честно́є Дре́во, Арха́нгелами і А́нгелами храни́моє;","ра́дуйся, Честно́є Дре́во, проро́ками богоглаго́ливими предзримоє.","Ра́дуйся, Честно́є Дре́во, преподо́бних і пра́ведних весе́ліє;","ра́дуйся, Честно́є Дре́во, ка́ющихся грі́шников наде́ждо і спасе́ніє.","Ра́дуйтеся, святі́ї равноапо́стольнії Константи́не і Єле́но, обрі́тшії Крест Госпо́день, ору́жіє спаси́тельноє."]},{"h":"Кондак 8","ps":["Странствующему на землі́ на́шего ра́ди спасе́нія, І́же не імі́яше, гді глави́ подклони́ти, воздвиго́ша хра́ми, богому́дрії Константи́не і Єле́но, во Вифлеє́мі ро́ждшемуся, на Голго́фі, іді́же расп'я́ться, на горі́ Єлео́н, отоню́дуже вознесе́ся к Безнача́льному Отцю́, і у ду́ба Мамврі́йська, іді́же Авраа́м пригласи́ Єго́ стра́нна, да всі ві́рнії непреста́нно пою́ть Серафи́мськую піснь: Аллилу́я."]},{"h":"Ікос 8","ps":["Все ва́ше служе́ніє бисть во сла́ву Сладча́йшаго Го́спода і Єго́ Пречи́стия Ма́тере, Засту́пниці ми́ра. Кий язи́к ізрече́ть под'ятиє ва́ми труди́? Кий ра́зум пости́гнеть ра́дость, єгда́ обрі́теся ва́ми жела́ємий Крест Госпо́день? Сего́ ра́ди всі земноро́днії благода́рно взива́ють вам:","Ра́дуйтеся, А́нгельською чистото́ю пожи́вшії;","ра́дуйтеся, всім се́рдцем Го́спода возлюби́вшії.","Ра́дуйтеся, апо́стольською ре́вностію потрудившіїся;","ра́дуйтеся, христия́нським смире́нієм украси́вшіїся.","Ра́дуйтеся, вся доброді́телі в себі́ совокупившії;","ра́дуйтеся, блаже́нство ра́йськоє унаследовавшії.","Ра́дуйтеся, я́ко зрі́те всегда́ Творця́ і Го́спода;","ра́дуйтеся, я́ко мзда ва́ша мно́га на небесі́х.","Ра́дуйтеся, святі́ї равноапо́стольнії Константи́не і Єле́но, обрі́тшії Крест Госпо́день, ору́жіє спаси́тельноє."]},{"h":"Кондак 9","ps":["Вся́коє єрети́чеськоє уче́ніє отве́ргше, богому́дрії отці́ і учи́теліє, собра́вшіїся повелі́нієм твої́м, царю́ Константи́не, на пе́рвом Вселе́нстім собо́ре, А́рія отгна́ша і єго́ посо́бников, і я́ко гром возгремі́ во вся конці́ піснь: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́ї сладковещаннії, богоно́снії отці́, святи́телі і учи́тели на собо́рі Нике́йстім, Никола́й Мирликі́йський, Спиридо́н Тримифу́нтський, Пафну́тій Фиваїдський, Па́вел Неокесарійський, Афана́сій Александрі́йський і прочіє іспові́дниці Христо́ви, і́же, сви́ше умудрившеся, ізложи́ша та́мо Симво́л ві́ри і всей Це́ркві узако́ниша пі́ти Тро́йцю Єдиносу́щную, прине́сше піснь благодаре́нія Верхо́вному Влади́ці всіх Бо́гу і сослужи́телю своєму́ взива́я:","Ра́дуйся, досто́йний си́не ма́тере своєя́ богому́дрия Єле́ни;","ра́дуйся, подража́вий єй во смире́нії неізрече́нно.","Ра́дуйся, царю́, превосходя́й му́дрость Соломо́на;","ра́дуйся, стяжа́вий ві́ру пра́отця Авраа́ма.","Ра́дуйся, зако́нов і вла́сті висо́кий архитектоне;","ра́дуйся, но́вий Апо́столе вели́каго гра́да Константинополя.","Ра́дуйся, ми́лостивий і кро́ткий повели́телю;","ра́дуйся, пе́рваго Никейськаго собо́ра му́дрий предсіда́телю.","Ра́дуйтеся, святі́ї равноапо́стольнії Константи́не і Єле́но, обрі́тшії Крест Госпо́день, ору́жіє спаси́тельноє."]},{"h":"Кондак 10","ps":["Спасти́ся хотя́щим в побдвизі ді́вства не возбраня́л єси́, вели́кий Константи́не, да чи́стим се́рдцем возно́сять моли́тви Єди́ному Бо́гу о ми́рі всего́ ми́ра і, отрешеннії молви́ жите́йськія, я́ко А́нгели пою́ть: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́, покро́в і защи́та бисть тебі́ во всем Сама́ Пречи́стая Ді́ва, Влади́чиця не́ба і землі́. Є́йже вручи́л єси́ но́вий град твой на брега́х Босфора, да всі лю́діє, укріпля́ємі Єя́ милосе́рдим заступле́нієм, воспомина́юще ві́ру і по́двиги твоя́, прехва́льне Константи́не, благоумиле́нно взива́ють:","Ра́дуйся, но́вую столицю Византі́ї освяти́вий;","ра́дуйся, заступле́нію і покровительству Ма́тере Бо́жієй ю вручивий.","Ра́дуйся, храм Бо́жий во і́м'я Єя́ созда́вий;","ра́дуйся, горячія моли́тви в нем возславий.","Ра́дуйся, я́ко раб разу́мний тала́нти своя́ умно́живий;","ра́дуйся, во́лю свою́ во во́лю Бо́жию преда́вий.","Ра́дуйся, хра́мов святи́х украше́ніє;","ра́дуйся, па́стирей Це́ркве Христо́ви вразумле́ніє.","Ра́дуйтеся, святі́ї равноапо́стольнії Константи́не і Єле́но, обрі́тшії Крест Госпо́день, ору́жіє спаси́тельноє."]},{"h":"Кондак 11","ps":["Пі́нія і усе́рдния моли́тви принося́ще ни́ні во хра́мі ва́шем, святі́ї равноапо́стольнії ца́ріє Константи́не і Єле́но, про́сим со слеза́ми: воздіжі́те блаже́ннії ва́ші ру́ці, і́миже прия́сте Крест Святи́й, і молі́те расп'я́таго на нем Го́спода, да в покая́нії непреста́нно зове́м Єму́: Аллилу́я."]},{"h":"Ікос 11","ps":["Сві́тла і ра́достна кончи́на ва́ша, святі́ї равноапо́стольнії Константи́не і Єле́но, ви бо побідоно́сноє зна́меніє в об'ятіях свої́х держа́ще, показу́єте сим, да во́зьметь ки́йждо крест свой і, во смире́нії ше́ствуя путь земна́го стра́нствія, сподо́биться получить безболі́зненную кончи́ну і Боже́ственних Та́їн причаще́нія, со слеза́ми взива́я вам:","Ра́дуйтеся, я́ко поєте́ Єму́ со А́нгели Трисвято́є пі́ніє;","ра́дуйтеся, я́ко с собо́ром Апо́столов Єму́ предстоїте́.","Ра́дуйтеся, я́ко вку́пі со всі́ми святи́ми ра́йськая селе́нія зрі́те;","ра́дуйтеся, бі́дних і убо́гих ми́лостивії попечителіє.","Ра́дуйтеся, от уз і пліне́нія скориє свободителіє;","ра́дуйтеся, пра́здника не почита́ющих строгіє наказа́теліє.","Ра́дуйтеся, о всіх чту́щих па́м'ять ва́шу пред Го́сподем предста́теліє.","Ра́дуйтеся, святі́ї равноапо́стольнії Константи́не і Єле́но, обрі́тшії Крест Госпо́день, ору́жіє спаси́тельноє."]},{"h":"Кондак 12","ps":["Благода́ть ми́ра, тишину́ іспросі́те притекающим к ва́шему заступле́нію, уго́дниці Бо́жії, сохрані́те оте́чество на́ше от враго́в, находя́щих на ни, і междоусо́бния бра́ні, да ми́лость Бо́жию улучи́м ва́шими моли́твами, вопію́ще со всі́ми святи́ми Влади́ці Христу́: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще і восхваля́юще вас, святі́ї равноапо́стольнії ца́ріє Константи́не і Єле́но, пра́зднуєм святу́ю па́м'ять ва́шу і про́сим: не забу́діте нас, грі́шних, чту́щих труди́ і по́двиги ва́ша, да всі с ві́рою і любо́вію зове́м к вам:","Ра́дуйтеся, гра́да і хра́ма сего́ покрови́теліє;","ра́дуйтеся, па́стирем Це́ркве богому́дрії учи́теліє.","Ра́дуйтеся, во тьмі заблуждшим яркіє світи́льници;","ра́дуйтеся, за оте́чество на́ше те́плії пред Бо́гом моли́твенники.","Ра́дуйтеся, я́ко больни́х, сліпи́х і глухи́х ісціля́єте;","ра́дуйтеся, я́ко от неча́янния сме́рті ізбавля́єте.","Ра́дуйтеся, єретико́в і ху́льников ві́ри стра́хом правосу́дія Бо́жия устрашаєте;","ра́дуйтеся, грешникам кающимся проще́нія у Престо́ла Бо́жия іспрошаєте.","Ра́дуйтеся, святі́ї равноапо́стольнії Константи́не і Єле́но, обрі́тшії Крест Госпо́день, ору́жіє спаси́тельноє."]},{"h":"Кондак 13","ps":["О дво́їце прему́драя, великіє ца́ріє Константи́не і Єле́но, приймі́те ма́лоє сіє́ моле́ніє на́ше і приноси́моє вам хвале́ніє! Ізба́віте чту́щих святу́ю па́м'ять ва́шу от гріхо́вних страсте́й і ві́чнаго осужде́нія, да хода́тайством ва́шим возмо́жем до сконча́нія дній свої́х покланя́тися Животворя́щему Дре́ву Креста́ Госпо́дня і та́мо, іді́же сія́єть світ невече́рній, пі́ти во сла́ву Креста́: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгельський собо́р на землі́ зря́ше ве́ліє чу́до — ка́ко обрі́теся Свято́є Дре́во, на мно́го літ в ні́дріх землі́ безду́шним ка́менієм храни́моє, ни́ні же рука́ми архієре́йськими возноси́моє, лю́діє же ви́дівше сіє́, ниць на зе́млю падо́ша, сле́зно вопія́: \"Го́споди, поми́луй! Го́споди, поми́луй! Го́споди, поми́луй!\" Вас же, святі́ї равноапо́стольнії Константи́не і Єле́но, смире́нно велича́ху:","Ра́дуйся, блаже́нная ма́ти, зіло́ возлюби́вшая Христа́;","ра́дуйся, боговінча́нний си́не, слуго́ Небе́снаго Царя́.","Ра́дуйтеся, земні́ї А́нгели і небе́снії челові́ци;","ра́дуйтеся, строї́теліє та́їн Бо́жиїх.","Ра́дуйтеся, я́ко ва́ми не́бо і земля́ духо́вно возра́довашася;","ра́дуйтеся, я́ко от всіх земноро́дних вку́пі просла́вишася.","Ра́дуйтеся, досто́йнії носи́теліє і́мене Христо́ва;","ра́дуйтеся, два світи́ла вели́кая во вселе́нній.","Ра́дуйтеся, святі́ї равноапо́стольнії Константи́не і Єле́но, обрі́тшії Крест Госпо́день, ору́жіє спаси́тельноє."]},{"h":"Кондак 1","ps":["Ізбра́ннії предві́чним Царе́м, святі́ї равноапо́стольнії Константи́не і Єле́но, на всеми́рноє воздвиже́ніє Животворя́щаго і Спаси́тельнаго Креста́ Госпо́дня, і́мже соді́лася спасе́ніє ро́да челові́чеськаго, іскупленнаго кро́вію пригвожде́ннаго на нем А́гнця Бо́жия, да всі пра́веднії і грі́шнії благода́рственно взива́ють вам:","Ра́дуйтеся, святі́ї равноапо́стольнії Константи́не і Єле́но, обрі́тшії Крест Госпо́день, ору́жіє спаси́тельноє."]},{"h":"Молитва перша","ps":["О преди́внії і всехва́льнії ца́ріє, святі́ї равноапо́стольнії Константи́не і Єле́но! К вам, те́плим засту́пником, возноси́м на́ші недосто́йния моли́тви, я́ко ве́ліє і́мате дерзнове́ніє ко Го́споду. Іспросі́те у Него́ мир Це́ркві і всему́ ми́ру благоде́нствіє, нача́льником му́дрость, па́стирем попече́ніє о па́стві, пасо́мим смире́ніє, ста́рцем жела́нноє упокоє́ніє, муже́м крі́пость, жена́м благолі́піє, ді́вственником чистоту́, детям послуша́ніє, младе́нцем христия́нськоє воспита́ніє, больни́м ісціле́ніє, враждующим примире́ніє, оби́димим терпі́ніє, обидящим страх Бо́жий. Приходящим в храм сей і молящимся в нем свято́є благослове́ніє і всім вся по коєго́ждо проше́нію поле́зная, да хва́лим і поє́м Благоді́теля всіх Бо́га, в Тро́йці сла́вимаго, Отця́, і Си́на, і Свята́го Ду́ха, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О святі́ї равноапо́стольнії Константи́не і Єле́но! Ізба́віте прихо́д сей і храм наш от вся́каго наві́та вра́жия і не оста́віте заступле́нієм ва́шим нас, немощни́х (імена́), умолі́те бла́гость Христа́ Бо́га на́шего дарова́ти нам помисло́в мир, от па́губних страсте́й і вся́кия скве́рни воздержа́ніє, благоче́стіє же нелицемі́рноє. Іспросі́те нам, уго́дниці Бо́жії, сви́ше дух кро́тости і смиренному́дрія, дух терпі́нія і покая́нія, да про́чеє вре́м'я житія́ на́шего во ві́рі і сокруше́нії серде́чнім поживе́м, і та́ко в час сконча́нія на́шего благода́рно восхва́лим просла́вльшаго вас Го́спода, Безнача́льнаго Отця́, Єдиноро́днаго Єго́ Си́на і Єдиносу́щнаго Всеблага́го Ду́ха, Тро́йцю Неразді́льную, во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 8","ps":["Креста́ Твоєго́ о́браз на Небесі́ ви́дів і, я́коже Па́вел, зва́ніє не от челові́к приє́м, в царі́х апо́стол Твой, Го́споди, Ца́рствующий град в ру́ці Твоє́й положи́, єго́же спаса́й всегда́ в ми́рі моли́твами Богоро́диці, єди́не Человіколю́бче."]},{"h":"Кондак, глас 3","ps":["Константи́н днесь с ма́терію Єле́ною Крест явля́ють, всечестно́є дре́во, всіх у́бо іуде́єв посрамле́ніє су́ще, ору́жіє же на проти́вния ві́рних люде́й: нас бо ра́ди яви́ся зна́меніє ве́ліє і во бра́ніх гро́зноє."]},{"h":"Величання","ps":["Велича́єм вас, святі́ї благові́рнії і равноапо́стольнії ца́ріє Константи́не і Єле́но, і чтим святу́ю па́м'ять ва́шу, ви бо святи́м Кресто́м всю вселе́нную просвіти́ли єсте́."]}],"notes":[]},{"u":"Акафіст преподобномученикам Серафиму і Феогносту Алма-Атинським","e":"Akathist to the Venerable Martyrs Seraphim and Theognostus of Alma-Ata","secs":[{"h":"Кондак 1","ps":["Ізбра́ннії служи́теліє Преві́чнаго А́гнця Бо́жия, во спасе́ніє на́ше на Кресті́ Себі́ прине́сшаго, Єму́же, взе́мше крест свой, во і́ночеськом благочести́вом житії́ усе́рдно послі́довавшії і кров свою́ за Него́ пролія́вшії, ди́вная дво́їце друзі́й Христо́вих Серафи́ме і Феогно́сте. Просла́вльшаго ви Подвигополо́жника на́шего і Це́ркві Зижди́теля, прославля́юще, і чи́стоє житіє́ і честна́я страда́нія ва́ша восхваля́юще, любо́вію вопіє́м:","Ра́дуйтеся, преподобному́ченици Серафи́ме і Феогно́сте, моли́твенниці на́ші і засту́пниці, от Бо́га просла́вленния."]},{"h":"Ікос 1","ps":["А́нгели земні́ї і челові́ци небе́снії во всем житії́ ва́шем яви́лися єсте́, преподо́бнії: із мла́да под кров Честні́йшей Херуви́мов і славнейшей без сравне́нія Серафи́мов Пречи́стой Ді́ви Богоро́диці прите́кшії і равноа́нгельному ли́ку і́ночествующих в Глинськой пусти́ні вчине́ннії, от онюдуже, гла́су Боже́ственному кро́тко послі́дуя, кра́я Семиречія дости́гли єсте́, іді́же во іспові́данії Христо́ві да́же до кро́ві подвиза́лися єсте́. Ті́мже, кро́тости і смире́нію ва́шему удивля́ющеся, восхваля́єм вас та́ко:","Ра́дуйтеся, із мла́да Христа́ Ісу́са возлюби́вшії і Тому́ усе́рдно потрудившієся;","Ра́дуйтеся, спасе́нія ра́ди ві́чнаго во оби́тель Глинськую под кров Пречи́стия Богоро́диці притекшия.","Ра́дуйтеся, равноа́нгельную честь в со́нмі гли́нських ста́рцев досто́йні восприявшия;","Ра́дуйтеся, цілому́дрія храни́теліє і душе́вния і тіле́сния чистоти́ рачи́теліє.","Ра́дуйтеся, душі́ ва́ша і тілеса́ во оби́телі Ду́ха Свята́го уготовившия;","Ра́дуйтеся, во пло́ті, а́ки бесплотния на землі́ пожившия.","Ра́дуйтеся, я́ко на небесі́ і на землі́ от Го́спода просла́вленнії;","Ра́дуйтеся, обретшия ві́чноє всесві́тлоє мі́сто упокоє́нія.","Ра́дуйтеся, я́ко, восходя́ та́мо душа́ми, нам мо́щі святи́я ва́ша оставившия;","Ра́дуйтеся, я́ко моще́й ва́ших де́мони трепе́щуть.","Ра́дуйтеся, я́ко чудоді́йствуєть ті́ми Госпо́дь с любо́вію к вам приходящим;","Ра́дуйтеся, преподобному́ченици Серафи́ме і Феогно́сте, моли́твенниці на́ша і засту́пниці, от Бо́га просла́вленния."]},{"h":"Кондак 2","ps":["Ви́дя Христо́с Госпо́дь непоро́чную чистоту́ серде́ць ва́ших, плотськи́ми страстьми́ не омраче́нную, суди́ досто́йни вас би́ти жре́бія апо́стольськаго благові́стія в Туркестанськом крає. Єго́же гла́су: гряді́те по Мні, і сотворю́ ви ловці́ челові́ков — вне́млюще по Нем с любо́вію і тре́петом ідо́сте. Ті́мже і нас, чад ва́ших, моли́твами ва́шими сотворі́те ско́ри би́ти на ді́ланіє за́повідей Боже́ственних, пою́щих Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум недоразуміва́ємий о дивном призва́нії ва́шем, Боже́ственним смотре́нієм проявленний, разумі́ти іща́, преподо́бнії,помишляли єсте́ ка́ко, Бо́гу соді́йствующу, возмо́жете мир і кня́зя єго́ — человікоуби́йцю іскони́ і отця́ лжі дия́вола — побіди́ти. Сего́ ра́ди, во вся ору́жія Бо́жия обле́кшися, я́ко возмощи́ вам ста́ти проти́ву всім ко́знем дия́вольским, разже́нния стрі́ли сего́ посто́м і моли́твою, слез тече́нієм, кро́тостію і смире́нієм угасили єсте́. Сего́ ра́ди сли́шіте от нас похвали́ сія́:","Ра́дуйтеся, душе́вная ловле́нія і стра́сті плотські́я мече́м воздержа́нія посекшия;","Ра́дуйтеся, по́мисли гріхо́вния молча́нія обуче́нієм і сокруше́нною і́сповідію істребившия.","Ра́дуйтеся, струя́ми слез покая́нія пусти́нную го́ру сію́ напоівшия;","Ра́дуйтеся, труда́ми по́стничеськими, я́ко світи́ла просіявшия.","Ра́дуйтеся, сладча́йшеє І́м'я Ісу́сово во умі́ своє́м і се́рдце непреста́нно носившия;","Ра́дуйтеся, стоя́нієм на моли́тві, бді́нієм і поклонами плоть ва́шу ду́хові покорившия.","Ра́дуйтеся, душа́ми ва́шими в Сіо́н го́рній моли́твенно восходившия;","Ра́дуйтеся, та́мо сла́вою небе́сною обогати́вшіїся.","Ра́дуйтеся, А́нгелов собеседници і челові́ков наста́вници.","Ра́дуйтеся, по́тами по́стничеськими у́гліє стріл вра́жиїх угасившия;","Ра́дуйтеся, во і́ночеськом житії́ про́пасти гріха́ ізбавившіїся;","Ра́дуйтеся, преподобному́ченици Серафи́ме і Феогно́сте, моли́твенниці на́ші і засту́пниці, от Бо́га просла́вленния."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго, в сія́нії светозарном явле́нная, трикра́ти ука́за вам со спо́стники ва́шими мі́сто подвижничеських трудо́в, іспові́дничества і упокоє́нія ва́шего на Кзил-Жарськой го́ре Заілійського Алатау. На ню́же, ра́дующеся, взошли єсте́, дре́внім столпником і пусти́нником подо́б'яся, і Го́сподеві поя́: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я неуси́пноє попече́ніє о спасе́нії душ ва́ших і вверених вам от Бо́га благослове́нієм архипастирей Туркестанських чад церко́вних, показу́я нелі́ностний по́двиг в подража́нії уго́дником Бо́жиїм, па́стирськи в душепопеченії сло́вом і сами́м ді́лом прилі́жно потруди́лися єсте́. Сего́ ра́ди от усе́рдія на́шего приймі́те похвали́ сія́:","Ра́дуйтеся, отцю́ ві́рних пра́ведному Авраа́му подражавшия;","Ра́дуйтеся, теплото́ю ві́ри согріва́ємия, оте́чество своє́ оста́вльшія.","Ра́дуйтеся, Богови́дцю Мойсе́ю, на Сина́йськую го́ру восшедшему, поревновавшия;","Ра́дуйтеся, на гора́х Тяньшаня поуче́нії Боже́ственними і доброді́телей ісправле́нієм Влади́ку Христа́ ви́ну ду́хом свої́м созерцавшия.","Ра́дуйтеся, І́ову многострада́льному в слеза́х і терпі́нії уподобившіїся;","Ра́дуйтеся, єле́єм благоче́стія і благотворе́нія душі́ ва́ша пома́завшия.","Ра́дуйтеся, я́ко дре́внії проро́ци ду́ха прозрі́нія іму́щия;","Ра́дуйтеся, ді́йством Того́ озаря́ємі, му́ченичеськую кончи́ну ва́шу предузнавшия.","Ра́дуйтеся, апо́столом Христо́вим во благові́стії Єва́нгельськом в краі Семиречія последовавшия;","Ра́дуйтеся, преподо́бному Серафи́му Саро́вському в житії́ ва́шем і́ночеськом усе́рдно подражавшия.","Ра́дуйтеся, му́чеников добропобі́дних ли́ку сопречтенния;","Ра́дуйтеся, преподобному́ченици Серафи́ме і Феогно́сте, моли́твенниці на́ші і засту́пниці, от Бо́га просла́вленния."]},{"h":"Кондак 4","ps":["Бу́рю богоборчества, от безбо́жния вла́сті воздви́гнутую, огне́м ві́ри крі́пкия, наде́жди несумні́нния і любве́ і́стинния угасившия, преподо́бнії, А́гнцю Бо́жию Христу́ Ісу́су, я́ко заколе́ніє благоприя́тноє, себі́ принесли́ єсте́, і душепа́губних волко́в суєму́дрія бу́рю укротили єсте́, Го́сподеві поя́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаша богохульнії і злочести́вії лю́діє ангелоподо́бноє житіє́ ва́ше, в тишині́ пусти́ннаго уєдине́нія на горі́ соверша́ємоє, богопротивною я́ростію ди́шуще і бога́тство обрісти́ мня́ще, преда́ша вас сме́рті, кова́рно в рассветния часи́ у́тра расстреляв. Сего́ ра́ди Це́рков Свята́я, кро́вію іспові́дничества ва́шего, за Христа́ пролія́нною, украша́єма, сріта́єть ви приві́тствії си́ми:","Ра́дуйтеся, во́їни Христо́ви, не об'язавшіїся ку́плями жите́йськими, да Єму́ уго́дні бу́дете;","Ра́дуйтеся, во всем житії́ ва́шем Єго́ іскавшия і в Нем намі́реніє полагавшия.","Ра́дуйтеся, на го́ру висо́кую доброді́телей возшедшея, мона́шеськи Тому́ угодившия;","Ра́дуйтеся, неви́нно от пребеззако́нних за ві́ру і любо́в к Нему́ пострадавшия.","Ра́дуйтеся, вінце́в неув'яда́ємих от Небе́снаго Царя́ сла́ви сподо́бившіїся;","Ра́дуйтеся, к Распе́ншемуся нас ра́ди на Кресті́ ра́зум свой ви́ну возводившия.","Ра́дуйтеся, страда́льчеською кончи́ною ва́шею незло́біє А́гнця Бо́жия проповедавшия;","Ра́дуйтеся, в небе́сном всевесе́лом пребива́нії в ли́кі А́нгелов і всіх святи́х от Него́ прославления.","Ра́дуйтеся, дерзнове́ніє моли́твенноє о нас к Нему́ іму́щия;","Ра́дуйтеся, потемне́нния гріхми́ очеса́ душ на́ших сві́том єва́нгельським просвіща́ющия.","Ра́дуйтеся, гріхо́в оставле́ніє і в доброді́тельном житії́ укріпле́ніє нам подаю́щия;","Ра́дуйтеся, преподобному́ченици Серафи́ме і Феогно́сте, молитвеници на́ші і засту́пниці от Бо́га просла́вленния."]},{"h":"Кондак 5","ps":["Боготе́чния зві́зди яви́лися я́сте в христоподража́тельном житії́ ва́шем, блаже́ннії, луча́ми доброді́телей душі́ ві́рних озаряющея і путь к достиже́нію Ца́рства Небе́снаго іщущим спасе́нія указующе, поуча́я тіх благода́рні пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дяще правосла́внії лю́діє гра́да Ві́рнаго премно́гую любо́во ва́шу к Бо́гу і ревностноє благочести́воє і́ночеськоє житіє́, усе́рдно іска́ху назида́нія і моли́твеннаго предста́тельства ва́шего, преподо́бнії. Єгда́ же о невинном убіє́нії ва́шем узнаша, єди́ними усти́ і єди́ним се́рдцем ко Христу́ Подвигополо́жнику на́шему о упокоє́нії ва́шем в селе́ніях пра́ведних на ло́ні Авраа́ма моля́хуся, надгро́бноє рида́ніє, творя́ще победной песнью: Аллилу́я. Ті́мже і до днесь, святи́й гроб ваш обстоя́ще, ві́рнії взива́ють:","Ра́дуйтеся, житіє́м і кончи́ною ва́шею А́гнця Бо́жия проповедавщія;","Ра́дуйтеся, закла́ни би́вше, я́коже а́гнці.","Ра́дуйтеся, пе́рвіє слез ва́ших теченми фарао́на ми́сленнаго потопившия;","Ра́дуйтеся, посліди́ во успе́нії ва́шем пролія́нієм му́ченичеськия кро́ві того́ сокрушившия.","Ра́дуйтеся, к жи́зні нестареємой і присносущной преставльшіїся;","Ра́дуйтеся, преподо́бних похвало́ і му́чеников украше́ніє.","Ра́дуйтеся, по́стников сликовници і ді́вственников ра́дованіє;","Ра́дуйтеся, і́ноков і і́нокинь путеводящия в селе́нія небе́сная.","Ра́дуйтеся, богобоя́зненних миря́н скоропослушливия попечителіє;","Ра́дуйтеся, стада́ своєго́ іночествующіх наста́вници і хранитиліє.","Ра́дуйтеся, пусти́нния оби́телі ва́шея похвало́ і утвержде́ніє;","Ра́дуйтеся, преподобному́ченици Серафи́ме і Феогно́сте, моли́твенниці на́ші і засту́пниці, от Бо́га просла́вленния."]},{"h":"Кондак 6","ps":["Пропові́дують Семиречія конці́ Казахстанськой страні́ вели́чіє мона́шеських по́двигов і невинную страда́льчеськую за Христа́ кончи́ну ва́шу, преподобному́ченици, ї́хже ра́ди дарова́ вам Госпо́дь благода́ті чуде́с струю́ непреста́нно теку́щую. От нея́же благогові́йно ми́ро те́плаго хода́тайства ва́шего че́рплюще, благода́рні Бо́гу вопіє́м: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ Казахстанстей страні́ світ благоприятного хода́тайства ва́шего ко Престо́лу Живонача́льния Тро́йці, і́бо тлі́нная і скоротекущая ми́ра оста́вльше і крест на ра́мена взе́мше, де́монськия побіди́ли єсте́ полки́ і А́нгельськия дости́гли єсте́ чи́ни. Ті́мже восхваля́юще болі́зні і страда́нія ва́ша, любо́вію вопіє́м:","Ра́дуйтеся, ві́ру і́стинную, наде́жду несумні́нную і любо́в нелицемі́рную в себі́ імевшия;","Ра́дуйтеся, любо́во ва́шу к Бо́гу любо́вію к бли́жнім свої́м показавшия.","Ра́дуйтеся, воздержа́нія пра́вило в житії́ ва́шем приявшия;","Ра́дуйтеся, смире́ніє, кро́тость і послуша́ніє друг ко дру́гу імевшия.","Ра́дуйтеся, сего́ ра́ди Боже́ственную зарю́ Свята́го Ду́ха разу́мні приявшия;","Ра́дуйтеся, Трисія́ннаго і Трисо́лнечнаго Божества́ це́ркві нерукотворе́нния явившіїся.","Ра́дуйтеся, богодухнове́нними наставленіями ва́шими в правосла́вії ві́рния утвержда́ющия;","Ра́дуйтеся, проти́ву зло́би гоня́щих вас незло́биви і про́сти явившіїся.","Ра́дуйтеся, незло́бію і братолю́бію нас научающия;","Ра́дуйтеся, ми́лості і сострада́нія преісполненния.","Ра́дуйтеся, нестроє́нія, раздо́ров і всякого нече́стія іскорени́теліє;","Ра́дуйтеся, преподобному́ченици Серафи́ме і Феогно́сте, моли́твенниці на́ші і засту́пниці от Бо́га просла́вленния."]},{"h":"Кондак 7","ps":["Хотя́щим нам воспіва́ти сла́вно вінча́вшаго вас, преподобному́ченици, Го́спода і ва́ша сла́вити по́двиги і труди́, любве́ ра́ди Боже́ственния, ва́ми под'ятия, помозі́те нам, недосто́йним, сви́ше да́нною вам благода́тію Ду́ха Свята́го, се́рдця на́ша от гріхо́вния тьми очища́я, во є́же чи́сті пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вия, побідоно́сния, боговінча́нния во́їни Христо́ви Того́ бла́гостію в послі́днія сія́ времена́ лю́тих гоне́ній, преподобному́ченици, яви́лися єсте́, до́брий житія́ ва́шего по́двиг сконча́вше і ві́ру правосла́вную непоро́чно соблю́дше. Ті́мже о таково́м Бо́жиєм благоволе́нії ра́дующеся, воспіва́єм вам такова́я:","Ра́дуйтеся, во єди́но єстество́ Боже́ственния Тро́йці веровавшия правосла́вно;","Ра́дуйтеся, креще́нієм во І́м'я Отця́ і Си́на і Свята́го Ду́ха слове́сноє ста́до Христо́во приумножившия.","Ра́дуйтеся, Бескровную Же́ртву о свої́х грісі́х і о людськи́х неведеніях со стра́хом і тре́петом Бо́гу приносившия;","Ра́дуйтеся, во вре́м'я соверше́нія Боже́ственния Литургі́ї сле́зи умиле́нія проливавшия.","Ра́дуйтеся, пречи́стими Та́йнами Христо́вими в наслі́діє житія́ ві́чнаго себе́ і чад церко́вних насищавшия;","Ра́дуйтеся, славосло́вія і благодаре́нія к Бо́гу во хра́міх благогові́йно приносившия.","Ра́дуйтеся ві́рних научившия поклоня́тися Творцю́ в Тро́йці;","Ра́дуйтеся, Пресвяту́ю Ді́ву Богоро́дицю во всем житії́ ва́шем прославлявшия.","Ра́дуйтеся, Єя́же преблаго́му Покро́ву і всіх ві́рних поручившия;","Ра́дуйтеся, чи́на і уста́вов Святи́я Це́ркви ві́рнії храни́теліє.","Ра́дуйтеся, благи́х оби́чаєв і преда́ній святоотечеських ревни́теліє;","Ра́дуйтеся, преподобному́ченици Серафи́ме і Феогно́сте, моли́твенниці на́ші і засту́пниці, от Бо́га просла́вленния."]},{"h":"Кондак 8","ps":["Стра́нно єсть ви́діти, я́ко благода́тією Бо́жиєю, і по сокрове́нії в ні́дра земна́я страда́льчеськая тілеса́ ва́ша, преподобному́ченици досточу́дния, присносу́щную жизнь явля́ють. Приходящим бо к вам і те́плаго ва́шего хода́тайства к Бо́гу во Святі́й Тро́йці сла́вимому і покланя́ємому іщущим я́ко жи́ви су́ще во благо́є пособствуюте, науча́я прославля́ющему вас Бо́гу пі́ти: Аллилу́я."]},{"h":"Ікос 8","ps":["Вся дні христоподражательного житія́ ва́шего, во єди́но существо́ Боже́ственния Тро́йці ві́ровав правосла́вно, богодухнове́нними наставле́нії ва́шими в правові́рії ві́рних утверждали єсте́ і наслі́дія небе́снаго сподо́билися єсте́, духоно́сния отці́, А́нгелов сослужи́теліє. Ті́мже честну́ю па́м'ять ва́шу соверша́я, прино́сим вам похва́льная сія́:","Ра́дуйтеся, ди́вная дво́їце друзі́й Христо́вих;","Ра́дуйтеся, соу́з любве́ духо́вния до сме́рти ві́рно сохранившия.","Ра́дуйтеся, не то́кмо в житії́ земно́м, но і по отше́ствії в небе́сния селе́нія о Го́споді соєдине́нния;","Ра́дуйтеся, на світоза́рную колесни́цю доброді́телей Боже́ственних восшедшия.","Ра́дуйтеся, Небе́снаго Ца́рствія достигшия;","Ра́дуйтеся, і нам, грі́шним, о́браз доброді́телей сло́вом і житіє́м яви́вшия.","Ра́дуйтеся, смире́нієм і цілому́дрієм ві́чноє блаже́нство улучившия;","Ра́дуйтеся, ми́лостію і моли́твою Небе́сноє Ца́рство стяжавшия.","Ра́дуйтеся, сла́ву вре́менную ні во что́же вміни́вшия;","Ра́дуйтеся, моли́твами ва́шими от мно́гих бід нас ізбавляющия.","Ра́дуйтеся, вся блага́я проше́нія на́ша ісполняющия;","Ра́дуйтеся, преподобному́ченици Серафи́ме і Феогно́сте, моли́твенниці на́ші і засту́пниці, от Бо́га просла́вленния."]},{"h":"Кондак 9","ps":["Всі А́нгели Бо́жії і ли́ки святи́х ра́достно восприя́ша богоно́сния душі́ ва́ша на небесі́, христоімени́тих же люде́й мно́жество, обстоя́ще с любо́вію гроб ваш, на землі́ пі́снми і пенми духо́вними ублажа́ють вас, преподобному́ченици, псало́мськи поя́: Аллилу́я."]},{"h":"Ікос 9","ps":["Вити́йствующий язи́к не возмо́жеть по достоя́нію ізнести́ похва́льная в прославле́нії ва́шем, о, блаже́нная дво́їце друзі́й Христо́вих. Ви же, ми́лостиви і благопослушли́ви су́ще, приймі́те убо́гая похвали́ на́ша, дерзнове́нними свої́ми і богоприя́тними моли́твами, скудность на́шу восполня́ющи, да благода́рственні зове́м вам:","Ра́дуйтеся, Трисія́ннаго Божества́ таї́нници;","Ра́дуйтеся, Сла́ви небе́снаго Ца́рствія наслі́дници.","Ра́дуйтеся, А́нгельських лико́в собесі́дниці;","Ра́дуйтеся, со святи́ми на небесі́ ві́чно царствующия.","Ра́дуйся, от го́рних висо́т ра́йських к нам, недосто́йним, ми́лостивно приникающия;","Ра́дуйтеся, благодія́ній мно́жество нам істоча́ющия.","Ра́дуйтеся, ми́лостію сострада́нія ва́шего всіх об'ємлющия;","Ра́дуйтеся, Бо́жиїх ми́лостей і щедро́т нам пода́теліє.","Ра́дуйтеся, беспомощних ско́рії помо́щници;","Ра́дуйтеся, си́рих і вдови́ць корми́теліє.","Ра́дуйтеся, болі́зней душе́вних і тіле́сних врачи́ безме́здния;","Ра́дуйтеся, преподобному́ченици Серафи́ме і Феогно́сте, моли́твенниці на́ші і засту́пниці, от Бо́га просла́вленния."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ душі́ своя́, да не осужденно предста́ніте на суди́щі Христо́ві, вся су́щая в ми́рі доброхотне оста́вили єсте́, ті́сним путе́м покая́нія в безмо́лвіє Заілійських гор возше́дше, слез тече́нієм і тве́рдим духо́вним трудолю́бієм богодарова́нния тала́нти ва́ша умно́жили єсте́, моле́ніє те́плоє за всіх Бо́гу принося́ще, да всі в позна́ніє І́стини при́йдуть, поя́ Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіно́ю непоколеби́мою богоприя́тних моли́тв і хода́тайств ва́ших, преподобному́ченици, остеніте град і страну́ на́шу, утоля́я пра́ведний гнів Бо́жий, поражающий нас, грі́шних і непотре́бних, бездо́ждієм і гла́дом, тлетво́рними ві́три і болі́знми, селями і землитрясенії, да, сих ізба́вльшеся, благода́рственно поє́м:","Ра́дуйтеся, блаже́ннії, в боголю́бії на землі́ пожившия;","Ра́дуйтеся, ми́лості і сострада́нія преісполненния.","Ра́дуйтеся, благода́тних даро́во ві́рним раздаятеліє;","Ра́дуйтеся, приходящим к вам с ві́рою і любо́вію предста́тельство і покро́ве.","Ра́дуйтеся, ізнемога́ющим от уни́нія і печа́лі помо́щници;","Ра́дуйтеся, ю́них наста́вници і ста́рцев пита́теліє.","Ра́дуйтеся, растлі́нних оби́чаєв іскорени́теліє;","Ра́дуйтеся, ко спасе́нію ві́чному добриє путеводи́теліє.","Ра́дуйтеся, кро́тости, воздержа́нія і покая́нія учи́теліє;","Ра́дуйтеся, Це́ркве Христо́ви огражде́ніє і Правосла́вія побо́рници.","Ра́дуйтеся, па́стирей учитиліє і мона́шествующих наста́вници;","Ра́дуйтеся, преподобному́ченици Серафи́ме і Феогно́сте, моли́твенниці на́ші і засту́пниці, от Бо́га просла́вленния."]},{"h":"Кондак 11","ps":["Пі́ніє всеумиле́нноє от ю́ности Христу́, Со́лнцю Пра́вди, у́треневав приносили єсте́, богоно́снії отці́, і у́мную чистоту́ безстра́стієм стяжа́в, це́ркві нерукотворе́нния яви́лися єсте́ Ду́ха Свята́го, І́мже непреста́нно в сердця́х ва́ших Отцю́ Небе́сному воспіва́ли: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рная світи́ла во гра́ді Алма-Ате і всей Казахстанськой страні́ яви́лися єсте́, просвіща́я лю́ди сві́том і́стиннаго богові́дінія і разгоня́я мрак безбо́жия, Трисо́лнечнаго сві́та Єва́нгельськаго сія́нієм, і́мже і на́ша, гріхо́м помраче́нная, сми́сли просвіті́те, вопію́щих вам такова́я:","Ра́дуйтеся, чистоту́ серде́чную і тіле́сную до сме́рти опа́сно хранившия;","Ра́дуйтеся, цілому́дренно і пра́ведно на землі́ пожившия.","Ра́дуйтеся, ві́ру свою́ во страда́нії, я́ко зла́то в горни́лі, очистившия;","Ра́дуйтеся, стезе́ю ті́сною воздержа́нія і оскуді́нія і́ночеськаго шествовавшия.","Ра́дуйтеся, я́ко то́ю широти́ рая́ Бо́жия достигшия;","Ра́дуйтеся, от го́рнія оби́телі земни́я во Оби́телі Небе́сния удо́б возшедшия.","Ра́дуйтеся, со А́нгели і ли́ки всіх святи́х Трисвяту́ю піснь Бо́гу воспіва́ющія;","Ра́дуйтеся, я́ко па́м'ять ва́ша с похвала́ми і успе́ніє со святи́ми.","Ра́дуйтеся, я́ко імена́ ва́ша че́стни і благогові́йни в Це́ркві Христо́вой;","Ра́дуйтеся, світи́льници трисолнечного сві́та, уми́ і се́рдця ві́рних озаря́ющия.","Ра́дуйтеся, ста́до своє́ от волко́в хи́щних соблюдающия;","Ра́дуйтеся, преподобному́ченици Серафи́ме і Феогно́сте, моли́твенниці на́ші і засту́пниці, от Бо́га просла́вленния."]},{"h":"Кондак 12","ps":["Благода́ть небе́сния сла́ви от Христа́ Бо́га восприя́вше, пречу́дния і кро́ткия страстоте́рпці Христо́ви, земни́х нас не оставля́єте без по́мощі і заступле́нія ва́шего, утвержда́я нас во ві́рі, укріпля́я в наде́жді, совершенствуя в любві́ і наставля́я в му́дрості, і науча́я благи́х пода́телю Бо́гу пі́ти: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще ди́внаго во святи́х Свої́х Бо́га на́шего, прославля́єм вас, блаже́ннії, с му́ченики Христо́вими сочетаємия і с ли́ки преподо́бних вчиняємия, с девственники ликовствуємия, с по́стники і пустинники ублажаємия, с ни́миже непреста́нно піснь хвале́бную Це́ркві Зижди́телю возсилаєте і молі́теся о нас такова́я вам глаго́лющих:","Ра́дуйтеся, Це́ркві Ру́ськия украше́ніє;","Ра́дуйтеся, Казахстанськия страни́ заступле́ніє.","Ра́дуйтеся, гра́ду Алма-Ате сокро́вища пребога́тия;","Ра́дуйтеся, во благоуха́нії святи́ні почива́ющия.","Ра́дуйтеся, всіх с ві́рою приходя́щих к вам благода́тно освящающия;","Ра́дуйтеся, усе́рдно призива́ющим вас помога́ющия.","Ра́дуйтеся, возлага́ющим по Бо́зі упова́ніє на вас посо́бствующия;","Ра́дуйтеся, крепції защи́тници на́ша от враго́во ви́димих і неви́димих.","Ра́дуйтеся, при́снії нам хода́таї спасе́нія;","Ра́дуйтеся, тіле́с на́ших благода́тния целебници.","Ра́дуйтеся, о душа́х на́ших усе́рдния ко Го́споду моле́бници;","Ра́дуйтеся, преподобному́ченици Серафи́ме і Феогно́сте, моли́твенниці на́ші і засту́пниці, от Бо́га просла́вленния."]},{"h":"Кондак 13","ps":["О, пречу́днії і кротції страстоте́рпці Христо́ви, преподо́бнії Серафи́ме і Феогно́сте, всім с ві́рою і любо́вію вас призива́ющим скориє і тепліє помо́щници, приймі́те от нас недосто́йних ма́лоє сіє́ со усе́рдієм приноси́моє вам благодаре́ніє і засту́питі ни от всіх враго́во ви́димих і неви́димих і ві́чния муки́ ізба́витися нам Го́спода умолі́те, да с ва́ми в невече́рнім дні Ца́рствія Бо́жия воспоє́м: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгели земні́ї і челові́ци небе́снії во всем житії́ ва́шем яви́лися єсте́, преподо́бнії: із мла́да под кров Честні́йшей Херуви́мов і славнейшей без сравне́нія Серафи́мов Пречи́стой Ді́ви Богоро́диці прите́кшії і равноа́нгельному ли́ку і́ночествующих в Глинськой пусти́ні вчине́ннії, от онюдуже, гла́су Боже́ственному кро́тко послі́дуя, кра́я Семиречія дости́гли єсте́, іді́же во іспові́данії Христо́ві да́же до кро́ві подвиза́лися єсте́. Ті́мже, кро́тости і смире́нію ва́шему удивля́ющеся, восхваля́єм вас та́ко:","Ра́дуйтеся, із мла́да Христа́ Ісу́са возлюби́вшії і Тому́ усе́рдно потрудившієся;","Ра́дуйтеся, спасе́нія ра́ди ві́чнаго во оби́тель Глинськую под кров Пречи́стия Богоро́диці притекшия.","Ра́дуйтеся, равноа́нгельную честь в со́нмі гли́нських ста́рцев досто́йні восприявшия;","Ра́дуйтеся, цілому́дрія храни́теліє і душе́вния і тіле́сния чистоти́ рачи́теліє.","Ра́дуйтеся, душі́ ва́ша і тілеса́ во оби́телі Ду́ха Свята́го уготовившия;","Ра́дуйтеся, во пло́ті, а́ки бесплотния на землі́ пожившия.","Ра́дуйтеся, я́ко на небесі́ і на землі́ от Го́спода просла́вленнії;","Ра́дуйтеся, обретшия ві́чноє всесві́тлоє мі́сто упокоє́нія.","Ра́дуйтеся, я́ко, восходя́ та́мо душа́ми, нам мо́щі святи́я ва́ша оставившия;","Ра́дуйтеся, я́ко моще́й ва́ших де́мони трепе́щуть.","Ра́дуйтеся, я́ко чудоді́йствуєть ті́ми Госпо́дь с любо́вію к вам приходящим;","Ра́дуйтеся, преподобному́ченици Серафи́ме і Феогно́сте, моли́твенниці на́ша і засту́пниці, от Бо́га просла́вленния."]},{"h":"Кондак 1","ps":["Ізбра́ннії служи́теліє Преві́чнаго А́гнця Бо́жия, во спасе́ніє на́ше на Кресті́ Себі́ прине́сшаго, Єму́же, взе́мше крест свой, во і́ночеськом благочести́вом житії́ усе́рдно послі́довавшії і кров свою́ за Него́ пролія́вшії, ди́вная дво́їце друзі́й Христо́вих Серафи́ме і Феогно́сте. Просла́вльшаго ви Подвигополо́жника на́шего і Це́ркві Зижди́теля, прославля́юще, і чи́стоє житіє́ і честна́я страда́нія ва́ша восхваля́юще, любо́вію вопіє́м:","Ра́дуйтеся, преподобному́ченици Серафи́ме і Феогно́сте, моли́твенниці на́ші і засту́пниці, от Бо́га просла́вленния."]},{"h":"Молитва","ps":["О, Богоблаже́нная дво́їце друзі́й Христо́вих, преподо́бнії страстоте́рпці Серафи́ме і Феогно́сте! Казахстанськия страни́ світи́льници достопочтенния, гра́да Алма-Ати защи́тници і покрови́теліє богодарованниє, правосла́вних всіх неуси́пния наста́вници! На небесі́ богопросвещенними душа́ми ва́шими престо́лу Бо́жию предстоя́щії, на землі́ же му́ченичеськи за Христа́ пострада́вшими тілеси́ ва́шими на гора́х Заілійських почива́ющия і разли́чная дарова́нія духо́вная всім с ві́рою і любо́вію к вам приходя́щим істоча́ющия! Ми́лостивим призрі́нієм благосе́рдія ва́шего при́зріте на лю́ди, святу́ю па́м'ять ва́шу почита́ющия, на мі́сті ісповедничеських по́двигов і преподо́бничеських трудо́во ва́ших святи́й гроб ваш обстоя́щия і те́плаго ва́шего ко Го́споду хода́тайства во обдержа́щих ну́ждах прося́щия. Всі бо ми по мно́жеству гріхо́в на́ших не дерза́єм возвісти́ на Не́бо оче́с на́ших, до́лу пони́кших, ви же, я́ко стяжа́вшії дерзнове́ніє ко Го́споду і ни́ні со А́нгели Єму́ предстоя́щії, принесі́те о нас благоуханниє моли́тви ва́ша, во є́же ізба́витися нам от гла́да, пото́па, тру́са, огня́, меча́, наше́ствія іноплеме́нник і междоусо́бния бра́ні, от вся́кия ско́рби, зол і болі́зні душе́вния і тіле́сния от люде́й і дия́вола по гріхо́м на́шим бива́ющия. Да сих избіжа́вше, Го́споду усе́рдно рабо́тающе, моли́твами ва́шими і те́плим предста́тельством вни́дем в несконча́ємий поко́й Ца́рства Небе́снаго і та́мо с ва́ми і ли́ки всіх святи́х просла́вим Вели́коє І́м'я Святи́я Тро́йці, Отця́ і Си́на і Ду́ха Свята́го во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 1","ps":["Любве́ ра́ди Христо́ви оте́чество своє́ оста́вльше, вся ми́ра сего́ кра́сная, я́ко скороїсчезающая, презрі́вше, го́рняго Ієрусали́ма взиску́юще, на гора́х Тянь-Шаня в по́двизіх благоче́стія Святу́ю Тро́йцю просла́вили єсте́. І вінця́ми добропобеднаго му́ченичества украси́вшеся, гра́ду Алма-Ате богодарованнії покрови́теліє яви́лися єсте́, преподобному́ченици Серафи́ме і Феогно́сте, Правосла́вія му́жественнії іспові́дниці. Ті́мже і ми, духо́вная ча́да ва́ша, любо́вію вопіє́м: Сла́ва Да́вшему вам крі́пость, Сла́ва Вінча́вшему вас, Сла́ва Подаю́щему ва́ми ми́лості і ісціле́нія."]},{"h":"Кондак, глас 2","ps":["Благо́є і́го Христо́во на себі́ восприє́мше і ле́гкоє бре́м'я Єго́ любо́вію облобиза́вше, житіє́м свої́м А́гнця Бо́жия пропові́давше, за і́стину, ра́дующеся, пострада́ли єсте́, і в поко́й Небе́сний преше́дше, с ли́ки святи́х Престо́лу Бо́жию предстоїте́, преподобному́ченици Серафи́ме і Феогно́сте, гра́ду Алма-Ате іспросі́те ми́ра і всім чту́щим вас ве́лію ми́лость."]},{"h":"Величання","ps":["Велича́єм вас, / преподо́бнії страстоте́рпці Серафи́ме і Феогно́сте, / і чтим святу́ю па́м'ять ва́шу, / ви бо мо́лите за нас // Христа́ Бо́га на́шего."]}],"notes":[]}];
export default D;
